INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0c966e56a60b38c1db26', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Can I just try to make that point really clear? I think in the report, if I remember rightly, you said there were an extra 75 staff to handle the changes in Senedd reform. I think eight staff have yet to be recruited because we''re awaiting that decision from the Business Committee. I guess that''s an example of what Ben''s looking at, isn''t it, and then as and when that decision gets made by the Business Committee, whether to recruit those extra eight staff. Is that fair?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3653&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.462794', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777510', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0cae8cb46fd7a43e00b4', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Yes. [ Interruption .] Oh, I beg your pardon. Yes, of course. [ Interruption .] No problem. Again, the—. Could you repeat the question, please?', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=749&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.833993', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773143', NULL, NULL, NULL, NULL);
