INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('102d9978d7a27c035fc5', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Can I ask a little question?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15988&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.787886', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775382', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('103b0ad4ba75994d3660', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', '5. Will the First Minister set out a timeline for the introduction of new measures to better protect renters? OQ64467', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'David Hughes', '', '12159', '', '', 'Plenary', '1. Questions to the First Minister', '16260', '', NULL, 99.0, 'High', 'digest', 'private_rented_sector', 'Private rented sector', 'First Minister / Cabinet; LGHP Committee members', '', 'renters', 0, '2026-09-16T11:53:07.201557', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769000', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('103bad91cfa1f5987749', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'And appreciating that the main focus of the wildfire summit has to be how we can get ourselves ready for next summer and the events that might unfold then, I also just wanted to ask about you keeping an eye on the longer term view with all of this as well. So, one thing I''m really interested in is beaver restoration. I know that''s a long-term goal, but there''s some really excellent evidence coming out from around the world—Canada in particular—about how the reintroduction of beavers can really help with that rewetting agenda, and help with the whole situation around wildfires. So, just to see if you''ve got any thoughts there.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Vikki Howells', '', '5107', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1874&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.536333', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772012', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('103e85a2f16f22daae2a', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Diolch yn fawr. I do recognise the specific way that poverty and deprivation can affect rural areas in particular. So, one of the things that I did was make sure that, when I announced funding for local authorities—which provides support for wider poverty prevention activities and also emergency food aid, which include those community hubs where preventative services are provided—that funding also included an allocation for rural local authorities, a rural allocation, recognising the added challenges of delivering support in rural areas. That rural premium element has been included on a test-and-learn basis, to recognise the additional challenges, as the Member has outlined, and also the costs that rural local authorities and other services can face when delivering cost-of-living and poverty support.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1050ca651f8c61e38a73', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you, Chair. I would argue that one of the key ways for us to reach net zero is for the public sector to lead the way. Under the previous Welsh Government, there was a range of support and funding streams to assist with that. The previous Government had the target for net zero in the public sector by 2030. Is that a target that you will maintain?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Vikki Howells', '', '5107', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4748&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.922058', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771784', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('106a44a01c03af9f5d65', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'I''d first like to thank the finance Minister for taking the time out of her busy day to join us here in the Senedd, but if I''m truthfully honest, I''m not sure what the point was, given you''d already announced to the press in writing what you were going to do over 24 hours ago. I''m reminded of that excellent phrase from the former Plaid Cymru leader and current Government Minister, Adam Price, who said, when Labour did exactly the same thing, ''government by press briefing''. He also said it was disrespectful to the Llywydd and that, quote,
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('10aa7e99d579b5b9c35c', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Right, okay.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peter Fox', '', '4787', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4128&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.809180', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770464', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('10c7309edc15f956119e', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thank you, Tom. Rebeca, you''ve got a question on timings.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2317&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.041359', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769858', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('10fc7a462069cbb50e77', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Thank you. You also note in your report the intent to bring primary healthcare bodies under your complaints standards policy, starting with general practitioners, and you noted it would require, in your words, ''significant work''. I wonder how you''re planning to use your resources to incorporate this.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=12020&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.455773', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777608', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('11051b35b17a8b4fa8ee', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Your general point regarding trying to simplify the way we collect data is one that''s appropriate to be doing. In terms of these regulations, we have set which local data we''re hoping that electoral officers will use, and I''ve written to them talking about universities and housing associations and so forth. On the general point that you make, maybe not within these specific regulations, but certainly there is a need to ensure greater consistency across the situation, not just with electoral data, but data in general, in terms of the data that the health service is collecting, for example, as well. Sorry, what was your second point?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=10355&l=en', NULL, 86.2, 'High', 'digest', 'social_housing; committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee; housing associations', 0, '2026-10-07T06:31:26.352708', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774505', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('11089827407de5c07dc7', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Okay. I guess I''m going to go back to that notification period. So, I''m actually looking at the pack. The concern, I think, that I have is: does it provide the right balance between the effective administration of this scheme and the safeguarding of vulnerable people? I''m going to cite an example: if you think of a victim of domestic abuse who has to leave the marital home, and then that mail goes to that home, she''s no longer there, so how do we capture that? How do we deal with that sort of issue?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9281&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.101142', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774400', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('113a4e3ae59d48936d00', 'calendar', 'Senedd forward look', 'Local Government, Housing and Planning Committee — 22 October 2026, 09.30', 'Local Government, Housing and Planning Committee is scheduled to meet on 22 October 2026 at 09.30.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1140c71862de1c86d655', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'In what fields?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5284&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.070838', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770553', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1153f1a66a5345eb4054', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'The particular thing that we can''t do, which happens at the moment, is get the Department for Work and Pensions to verify national insurance numbers, because the restriction in particular is around modifying the functions of reserved authorities or adding to them. It''s not so much that we can''t use national data sets per se, if they have them for other reasons, lawfully, locally, but you can''t be getting other people to check them for you. They''ve got to be things that you know are data already. There might be other reasons for that, to do with, say, benefits information that might have been held centrally. No doubt, most of the information they''re going to have easy access to is going to be locally held, so locally held by the local authority, but it needn''t be exclusively that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1169650e95afae775fec', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Okay, thank you. So, for legislation and enforcement powers, I know that Marc and Rebeca were down originally. Does anybody else want to come in as well, otherwise we''ll move on from it?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17177&l=en', NULL, 212.7, 'Critical', 'immediate', 'taxation_of_property; local_government_enforcement; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; enforcement powers; evidence session; inquiry', 0, '2026-10-07T06:31:27.003087', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775563', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1175b621f631b2357a23', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'It''s on capital and technical, so I''m going to ask Lisa just to give us an overview.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3899&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.498667', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777423', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('119ae8a29788a7a35bba', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''ve got a long list of speakers coming up now, but I''ll take them in order—. Is this related to Vikki''s point, Anna, because I know Paul''s been waiting a while?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1958&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.551862', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772017', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('119c46ddc7517f4e51a1', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Empty property services is seen as a cinderella service in most local authorities. It''s not a statutory requirement, so when there are cuts to be made within the authority, it is seen as quite an easy service to lose. However, if you look at the empty property officers per se, the amount of work they do and the amount of investment that creates into the local community, as far as bringing empty properties back into use and job creation go, it''s quite significant, so they pay for themselves many times over, but it''s a matter for the authority. As far as the Welsh Government goes, I suppose the only suggestion is whether you make it a statutory requirement, which would put the onus of obligation on the authority to provide a service in that regard.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Andrew Lavender', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=536&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; empty property; evidence session; inquiry', 0, '2026-10-07T06:31:24.845542', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774640', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('119ca2f421916f0b102d', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'I''m very proud to serve a diverse constituency in Caerdydd Ffynnon Taf, with people coming from all walks of life. For the first time, many individuals and families placed their trust in Plaid Cymru, and they did this because they believe it will make a positive, tangible difference in their communities. I have spoken to many constituents over the last few months who are concerned about the rise in hate crimes, poverty, housing issues and other matters that negatively impact on their lives and the lives of their families.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('11b9d18ed6e1666e7772', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, I think this is a success story—I can''t even say it. I think it shows what is possible with the right investment in the right place. I had the pleasure of visiting a scheme up in Conwy near me, and really the learning that I took from that was that some of these places are recovering more quickly than anticipated and expected, and bringing those benefits sooner than anticipated. Yes, it''s a longer term project, over time, clearly, but we are already seeing benefits in terms of water management, flood resilience, water quality, but also then the whole biodiversity restoration and improvement as well. So, I''m particularly keen to continue to support these kinds of investments and schemes. I don''t know, Rhodri, if you want to add anything in particular.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1729&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.513717', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772004', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('11e24c48d869aa136b99', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Yes, that''s the point, really. It''s a wider point than just around the regulations, isn''t it? It''s about raising the awareness about anonymity and the ability for you to remain anonymous but still not be disenfranchised, because at the moment that isn''t used enough, as you say. So, moving in that direction is really helpful for vulnerable groups.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9523&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.150475', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774428', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('11e74091e21c5497e579', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Well, as I said before, it is for the EHRC to monitor that. Obviously, for those things that are—. For instance, health—the responsibility for that then lies with the governance structure of the health boards, the people who deliver health services. The Government doesn''t deliver health services. The boards that do the services and the public services that do provide those services, they are the ones who are responsible for making sure that they are compliant with the law, and the EHRC will give them guidance and monitor them on that.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=3449&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.952732', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771210', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12119a04648ef33a772c', 'plenary_transcript', 'Plenary', '6. Statement by the Deputy Minister for Public and Preventative Health: Priorities for Public and Preventative Health', 'I''d like to welcome the Minister to her post. I''ll stop the pleasantries here because people are watching the clock and we''ll be here all night. So, anyway, I''ll move on to your statement, Minister.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('122292f04c1917713a36', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'I think in terms of the consideration of the estimate for 2027-28, what you will see in there is a revised staffing establishment that we have going forward. That is, if you like, as much as there can be, a steady state, because there are always going to be changes and variances there. We expect that, for 2027-28, it would be, if you like, more of a steady line, but of course, you always have to look at things in parallel; it''s not just the reduction in staff costs, it''s also the impact on audit fee income.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Kevin Thomas', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=1773&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.071850', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774213', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('124ac3883de077b6f55c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Okay.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Michael Kay', '', '', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8743&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.994309', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774364', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1273c56d376c6a055c67', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'We haven''t had a housing strategy for 20 years. If you don''t have a strategy, you then end up with unintended consequences all over the place. If you don''t know as a committee already, you certainly will by the time you''ve looked at all the priorities: housing is such a connected area that you can''t do a policy change over there without it impacting on something else elsewhere. Empty homes are just a small bit of that, but one of the mantras we come out with is that we can''t build ourselves out of this housing crisis. It''s about, I suppose, being more joined up between housing, sustainable communities and regeneration. It''s that kind of interaction of people needing homes, but homes needing people and properties needing people. I''d love to see that sort of thing being tied into a future housing strategy for Wales.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16321&l=en', NULL, 172.5, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Sector bodies', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.844289', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775409', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12761bfc70793f8971ad', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'May I come back to the third question? This sector has been trying to contact the Government for over two years now and hasn''t received any attention. They ask whether it would be possible for them to meet with the Minister, just to put forward the way that they work and what they see are the difficulties in the sector.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Elfed Williams', '', '12165', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=7416&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.347385', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771290', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('128244ebfb13c717d447', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Exactly. Thank you very much for coming today. I think it''d be useful for everybody around the table if you wouldn''t mind introducing your officials, if that''s okay.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=63&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.276225', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771838', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('128c816f329debc12c6b', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Thank you. Just a couple more quick points, then. You mentioned how you''re seeing AI-assisted complaints, perhaps, from complainants. What can you do about that?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=7495&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:37.771622', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777597', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12c2be3adf56adf27366', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you for drawing attention to a very important area here. I won''t get drawn on particular local issues, but, more generally, we do know that the nutrient impact on housing delivery is concerning. The Cabinet Minister for Local Government, Housing and Planning and I both recognise the importance of this issue. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12de05959159f8b31998', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes. I''ve only got two more. I''m aware that, towards the end of the last Senedd, a lot of legislation came through in those last few months, over quite a short period. This obviously presents issues for Senedd scrutiny but also for officials as well, having to do so much in such a short space of time. So, I guess I''m wondering how this would be prevented from happening again at the end of this Senedd term and what lessons have been learned.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Kiera Marshall', '', '12166', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=986&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.208580', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770411', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12e9c55d8c2da8101687', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch. And I just wanted to ask about the national crime prevention agency for Wales. Obviously, crime prevention is something that our communities care very deeply about. We need to make sure that we are finding some practical outcomes for communities with this. And I just wonder if you could perhaps talk a little bit about that agency and what it''s expected to deliver. Again, we''re keen on timelines, as I know you were on this committee, Minister. So, we''re keen to have more of an idea about that.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jayne Bryant', '', '5038', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6252&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.213374', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771278', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12f0b0da572e72273fb2', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Carmarthenshire''s revised development plan allocates nearly 9,000 new homes within the county, and those new homes are needed and welcomed. However, the infrastructure to support them just does not keep pace. Glangwili is about to take on specialist critical care for the whole Hywel Dda area and people cannot see a GP or an NHS dentist. So, my question is: what can the Welsh Government or the local planning authority employ to ensure local infrastructure keeps pace with development? Diolch.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sarah Edwards', '', '12161', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=5398&l=en', NULL, 88.0, 'High', 'digest', 'housing_supply; planning_system', 'Planning & place', 'Housing minister', '', 'new homes; planning authority', 0, '2026-10-10T14:39:12.504636', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776759', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('12fd2f573587eed9230f', 'consultation', 'Senedd — Committee work', 'Forward work programme – Finance Committee', 'Forward work programme – Finance Committee
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1321bf023f07729048c9', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Well, I''m not sure we do. That''s why I''m asking if it''s net income or not, because if the catering—. If the employment costs are shown elsewhere, are we actually making any money on it?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1696&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.165803', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777282', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1346497b1e50bee3f9ab', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Lovely. Do any Members have anything on this? I''ve got a question. I''m just interested—. You are the Minister responsible for biodiversity. I''m just interested in the balancing act in Government, because we''ve seen in certain parts of the country large-scale infrastructure, for example, which is planned for certain parts, which some people contest will have huge impacts on biodiversity and biodiversity loss. I''m just interested where the Government''s thoughts are on that balance between large-scale infrastructure and the loss of biodiversity. I''m just interested where you''re working across Government portfolios to try and balance those competing priorities of wanting one thing and wanting the other.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3196&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.771856', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771921', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('134d0797e63b48517399', 'legislation', 'Acts of Senedd Cymru', 'Development of Tourism and Regulation of Visitor Accommodation (Wales) Act 2026', 'Development of Tourism and Regulation of Visitor Accommodation (Wales) Act 2026', 'https://www.legislation.gov.uk/asc/2026/10/2026-04-28/data.xml', '2026-07-31', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 84.5, 'Medium', 'digest', 'second_homes_and_short_term_lets; named_welsh_legislation', 'Context; Planning & place', '', '', 'Development of Tourism; Development of Tourism and Regulation of Visitor Accommodation (Wales) Act; Regulation of Visitor Accommodation; visitor accommodation', 0, '2026-08-04T14:04:14.608080', 'https://www.legislation.gov.uk/asc/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('134eedd45b1d615015ed', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Certainly. I''m Peredur Owen Griffiths. I''m the Commissioner with responsibility for finance, and I''ll ask officials to introduce themselves. I''ll start with Manon.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', 'Commissioner', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=65&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.894461', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777340', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1372835b2b70d541d3b5', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Within the estimate, we include an estimate for the lease rental payments for three main Audit Wales offices. So, Cardiff, north Wales, at Llandudno Junction, and in west Wales, Penllergaer. We account for those in terms of resource accounting evenly over the lifetime of the lease. Within the accounts, though, you''ll see reference to the cash payments that we physically make to the landlord, and there can be variance in those cash payments from one year to another. So, I think, in the case in question, the £73,000 difference, there were three payments to one particular landlord in 2024-25; there were five payments to that landlord in 2025-26. It''s purely a timing difference. The cost of the lease remains the same over the lifetime of the lease.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Kevin Thomas', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=3013&l=en', NULL, 132.2, 'Critical', 'immediate', 'private_rented_sector; committee_scrutiny', 'Housing system; Private rented sector', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session; landlord', 0, '2026-10-02T12:57:51.348991', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774557', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('13767e6aaf67bc6f8c79', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Yes. You don''t have to think very hard to work out the poverty that somebody is driven into in real terms when they have so little of their income left after paying their rent. The issues that cause that, there''s a multitude of them, supply of homes is one of them and social housing—that''s why we are determined to bring in an extra 20,000 additional social homes by 2030. It''s bringing homes into use that are currently not in use. It''s about raising the quality of the housing stock, as well.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('137f39e3a02239988fa0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'You would.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17106&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.986546', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775522', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('139663140ca2314ff3e6', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, okay, fair enough. I''ll bring the chief vet in on that.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6772&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.223070', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772119', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('139d17160fef2c791cef', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Absolutely. A large element of the cost is around decant and taking on additional leases—and you hear the plural there—to allow—. That is making budget provision; that is not necessarily what we''re going to spend, but this is a full potential provision that allows the Commission room to manoeuvre to take decisions. So, what we''re budgeting for is towards a maximum of what we think—not an absolute maximum, but a reasonable maximum—we might spend, based on what we know today. There are other elements within those, and I''m happy to talk more about the temporary accommodation options. Peredur gave the context. Just to say also, whilst you are seeing the costs there, quite rightly, and need to scrutinise those, our decant planning overall—our current estimate—generates a saving to the whole life of the project so far on the options that we''re looking at. But, obviously, it comes with upfront cost, but there are some longer term savings there as well. In these costs, just to say, there''s a large element of professional fees. There is a lot of legal, commercial and procurement advice.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Ed Williams', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2427&l=en', NULL, 115.0, 'High', 'digest', 'homelessness; fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session; temporary accommodation', 0, '2026-10-09T13:34:37.280750', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777275', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('13bebef07dc6e9a27478', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'No, he hasn''t answered it.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16150&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.820009', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775388', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('13deb8363a5ed52eb2c7', 'plenary_transcript', 'Plenary', '9. Voting Time', 'Item 8. Reform UK Debate - access to HMOs and social housing for foreign nationals. Cynnig wedi’i ddiwygio: For: 51, Against: 37, Abstain: 0
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('13fbc642110b612b35b5', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'As we''ve said already, the project is a major one, and there''s a lot of movement in it. The decisions, in terms of proceeding with the project will be made before the end of the year, and the process—. I''ll ask Ed to expand on the process so far and what is to come. We''ve gone to all the groups and offered a technical briefing on this and, of course, as you understand, there is some commercial sensitivity on certain elements, in terms of when these things are released publicly. We''re negotiating on contracts at present, so we have to consider what we do release. But it''s possible to come back to this committee with a technical briefing, maybe in private, with those figures in the future, if you would desire that as a committee. But I''ll bring Ed in now in terms of the timescales and when the next decision points will emerge.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2194&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.249270', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777497', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1421b92f098647dbab28', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Could I just add further on that? The Government paper says work has begun on child poverty targets and that it has refreshed the child poverty strategy. It also says Cynnal is being developed to provide a weekly payment for up to 15,000 children in universal credit households, with an expert group advising on delivery. What the paper does not provide is a baseline, target level, timetable, and a success criteria for Cynnal. You say work has begun on the child poverty targets. When will those targets be published? What baseline will they use? And by what date should the committee expect to see measurable reductions rather than simply evidence the programmes have been delivered?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Steve Bayliss', '', '8696', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1270&l=en', NULL, 80.5, 'Medium', 'digest', 'welfare_and_support; committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee; universal credit', 0, '2026-09-25T06:30:35.699136', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771161', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1433b9e3b82450f7a89d', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. They''re really important points, because I think—. This Government is determined that we aren''t going to pursue a course of providing solutions that are just going to tackle the fact that a third of our children are in poverty. We have to ensure that we create resilience, and of course, again, this is a cross-Government issue, as it''s related to the economy, it''s related to health, it''s related to education, it''s related to the skills agenda. So, it is something—and more. It''s across the food strategy as well in terms of nutritious food. It''s a cross-Government issue, and that''s why I''ve convened and I chair the Cabinet group, the cross-Cabinet group, on tackling child poverty in particular, and it''s one of the Government''s main priorities. So, we will be looking at measures that we can take to not just respond to the need, and of course we need to respond to the need for support in the short term, but also looking at the long-term picture. So, that strategy will take that longer term view on these issues.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('14353926a849018176ee', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'If it''s okay just to come back, I think I would also pick up, in light of that, that obviously it''s a policy decision for the Senedd and the UK Government whether they take different approaches to AVR, and obviously the UK Government are going through that debate at the moment. That''s another area where, if there is a divergence, clearly, cost and time increases. So it''s just important to be aware of that.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Ian Bancroft', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=7235&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.739177', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769974', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1447254cd8686f78dca4', 'plenary_transcript', 'Plenary', '2. Questions to the First Minister', 'Our ambition is for everyone in Wales to have access to good-quality affordable housing in the right area for them. The UK Government decides how many people seeking asylum are accommodated in Wales. We work with local authorities and third sector partners to provide fair support and help services plan effectively. The Welsh Government''s approach promotes safer communities, focusing on integration, access to support and, all importantly, community cohesion.', 'https://record.senedd.wales/Plenary/16264', '2026-09-29', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '2. Questions to the First Minister', '16264', 'http://www.senedd.tv/en/16264?startPos=3755&l=en', NULL, 49.5, 'Low', 'dashboard', 'housing_supply', 'Planning & place', 'First Minister / Cabinet', '', 'affordable housing', 0, '2026-10-03T13:38:58.414544', 'https://record.senedd.wales/XMLExport/Download?meetingID=16264&xmlDownloadType=EnglishTranscript#772906', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('144fa80ce1d9992eae6e', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'As has already been said, the tourism sector is of huge importance to the communities I represent in Ceredigion Penfro, so I''m pleased to speak up on behalf of the tourism businesses and providers in my constituency who are operating under significant financial pressures.
