INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1463b79156d21fe7b349', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'It''s not profit. Yes, exactly, it''s not profit.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1722&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.179485', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777948', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('146fe2e23e4e04ef9f9b', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Sure. Thank you very much. Are there any more questions from anybody else around the table? No. Thank you for your time this morning and afternoon. We appreciate that. We will continue with our agenda today. Thank you.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=12216&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.483516', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777620', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('14a60c3d0c30b3569757', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'I don''t know, so, give us a sense of the findings and what you''re doing.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2804&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.312383', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774184', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('14d0470fd3e6eeb5d3dd', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes. Diolch, Gadeirydd. There actually used to be four. So, it puts it into context quite well. So, during the initial period of the Measures from 2007 to 2011, there were only four. There weren''t actually that many shortly after that—so, shortly after the referendum—and it was a significant issue for the Government at the time, because I think that, by that point, we were maybe five or six, and the other issue was that we were not very experienced. So, one thing I''d say about legislation, and I think most people would agree, is that it''s complex and it''s technically difficult and, as lawyers, there is a big difference between advising on the current state of the law and changing the law and taking responsibility for implementing policy and turning that into words on the page in relation to legislation. So, we''ve gradually increased the size of the office, and there is a proposal to continue that and to expand the office further.29
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('14d8d297488369cd3320', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I welcome many of the steps taken by the Plaid Cymru Government since coming into power in order to address the real challenges facing the health service in Bangor Conwy Môn. We have seen a direct commitment to Betsi Cadwaladr University Health Board as well as additional funding for the health service in the supplementary budget. I''m sure that everyone would recognise the difference that that funding could make for patients and staff, and therefore how important it is that we pass the supplementary budget this afternoon. In looking to the future and to ensure that the good work can continue, we must encourage more efficient use of public funds within the health service. With that in mind, will the First Minister provide an update on the Government''s commitment to establish a health finance efficiency team and when he hopes to see that being established?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elfed Williams', '', '12165', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=2924&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.446582', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767550', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('150d1790dd110ade37ba', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'The interest charges are again to do with right-of-use assets. When you set up the initial right-of-use asset as a depreciation charge and an interest charge, the interest charge reduces over the life of the asset. So, it''s not interest in terms of an interest on finance, it''s almost notional in terms of the right-of-use asset calculation.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=667&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.005282', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777396', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('151763173df8b0a693ef', 'plenary_transcript', 'Plenary', '2. Questions to the First Minister', 'The current devolution settlement is outdated, constrains our economic potential and hinders our ability to deliver the best public services to people in Wales. Our immediate constitutional priorities are the devolution of policing and justice, the Crown Estate and rail infrastructure, alongside fair funding and greater fiscal flexibility. As a matter of principle, there is certainly no reason why powers that have been devolved to Scotland shouldn''t also be devolved to Wales.', 'https://record.senedd.wales/Plenary/16264', '2026-09-29', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '2. Questions to the First Minister', '16264', 'http://www.senedd.tv/en/16264?startPos=3557&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'devolution settlement', 0, '2026-10-03T13:38:58.390356', 'https://record.senedd.wales/XMLExport/Download?meetingID=16264&xmlDownloadType=EnglishTranscript#772899', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('152ac2e6e1e719990fc0', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Thank you. So, would you agree that we shouldn''t be placing that issue onto more vulnerable people, particularly people who are seeking asylum in the United Kingdom and end up in Wales? And so, we''re just combating these two groups that are both in need of housing, when the issue itself is what needs to be resolved in supporting people who do actually deserve to have housing. We should have enough appropriate housing for everybody to live a safe life.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sarah Rees', '', '5196', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=16076&l=en', NULL, 55.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', '', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.405445', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776963', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1561a42b4f6c9b96cbda', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Yes, I would say it''s something we''re having a very active discussion about in the frame of the new strategy, actually, in terms of how we really demonstrate impact in all its many forms. And I think that traceability point is something that we''re very alive to. I think it''s fair to say we''re having quite a transformational conversation about all the different impacts that good public audit can have, absolutely built on a foundation of quality, which Ann-Marie''s already described, but all the way through to the role that public audit plays in reassuring inward investors that we''re a stable place to come and invest your pound, right through to how we support individual bodies to get on to that preventative agenda and so on. So, it''s quite a holistic conversation. So, I''m sure it''s something we''ll have more to say on when we come back to the committee, perhaps, in the future.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Catherine Mealing-Jones', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=1364&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.988683', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774250', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('156c1064da02a510010b', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Are there any more questions from anyone? No. On behalf of the committee, I''d like to thank you all for coming here today. It''s been challenging, giving evidence and taking questions from the floor. We will send out to you the record of today''s meeting so that you can ensure that we''ve captured that discussion accurately. Again, thank you very much.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=7404&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.768851', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769987', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('158bb52759c15fd2aee9', 'committee_transcript', 'Petitions Committee', '2. New Petitions', 'Thank you very much. So, people in Carmarthenshire want Natural Resources Wales to start regularly dredging rivers again to help stop flooding. Dredging was scaled back in the 1990s, partly because of EU rules and that, and rivers have clogged up since then, flooding homes, farms, businesses and roads and so on and so forth. Two hundred and fifty-eight signatures. The petition also criticises local councils for failing to keep drains and roads in good enough shape. The petitioner says locals blame the end of dredging on the Gwendraeth Fawr river 30 years ago for worse flooding, as well as riverbank erosion and problems for emergency crews using the river, but accepts that dredging is only part of the answer.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('15c5662b62cae11c42db', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'I was reading about the upcoming Cynnal payment scheme, so £10 for families on universal credit, per child, per week. I was interested to know, because, obviously, Reform had their conference earlier this month, and a big thing that Reform are passionate about is benefits going to British people as opposed to foreign nationals—. Obviously, Plaid Cymru are a nationalist party; they make a big deal about putting the people of Wales first. So, could we expect something like that from Plaid Cymru, where, if this Cynnal payment scheme''s going to be trialled, it could go to just Welsh people or just British citizens and not foreign nationals?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Joe Martin', '', '12146', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1941&l=en', NULL, 80.5, 'Medium', 'digest', 'welfare_and_support; committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee; universal credit', 0, '2026-09-25T06:30:35.766695', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771164', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('15d2097099667980170a', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Lisa, do you have the figure to hand?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1457&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.094537', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777210', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('15f201fb8a4dd490c785', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'May I add, Mr Thomas, that''s a crucially important question? Where the Bill that I''m involved in is in question, it''s my intention to ask the Bill team to connect appropriately and often with all the opposition parties, even before it''s introduced, to set out, ''These are our intentions, this is what we think, this is what the third sector says about this and that, what are your views, will you look at it?'' and so on, and to do so early on in the process, not later. Because the argument, very often—. It''s possible to make changes after a Bill has been introduced to the Senedd, of course, but it''s often better to have that conversation when there''s less pressure on people during the creation of that Bill.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16004d7ed9a4c8164de1', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you, Minister. Minister, your Government promised 20,000 additional social homes by 2030, despite Wales''s nation of sanctuary and Swansea''s city of sanctuary status potentially drawing further claimants into our lands, and you just said that we do not have enough social housing. My understanding is that Swansea Council does not collect immigration status data for social housing applicants. I consider that remiss. I was also surprised that you said that you were not sure why we would collect that data. The people of Swansea and Wales deserve transparency to understand the full scale of the situation. Will your Government take concrete action to close this unacceptable void in the data and publish clear comparisons of social housing allocations and waiting times for established local residents versus newly arrived people and how crucial allocation decisions are made?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Steven Rodaway', '', '12191', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=7982&l=en', NULL, 77.0, 'Medium', 'digest', 'housing_supply; social_housing', 'Housing system; Planning & place', 'Housing minister', '', 'social homes; social housing', 0, '2026-10-10T14:39:12.743045', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776775', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1642b7eaee1da74cece4', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'I will raise my voice, Llywydd.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16563c69f75ff910ea57', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thank you, Chair. I''ve got three questions about public sector accountability, but I''d like to ask an extra quick little one, if you wouldn''t mind, based on a response you gave to Sera Evans a few minutes ago. Correct me if I''m wrong, but I think you suggested that UK Government national increased spending on defence was going to therefore mean that we get less funding to Wales. Has a statement been issued to confirm that or is there any evidence to back that up at all?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Iain McIntosh', '', '12170', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=8568&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.862187', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774311', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1656502d6b192bee451d', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Will you take an intervention?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sarah Rees', '', '5196', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=16053&l=en', NULL, 55.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', '', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.401803', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776961', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('165bdf93ebbcd0fa8fee', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Well, Minister, I think data matters when it''s taxpayers'' money, and we need to know who is in our social homes. When we''ve got parents waiting for years for social homes, we need to be prioritising our own. So, Minister, there are actions you can take if you wanted to fix the problem right now and put our own people first. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('167230e2d3ab0c97b049', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Me again? [ Laughter .] I think the frequency—. The flexibility in the regs does allow EROs some idea of timing an AVR exercise that might suit their circumstances and their type of local authority area better. I would say that AVR isn''t the only mechanism that the electoral registration officers have to get people on the register. We already do quite a lot of work, and I think this is pretty much commonplace across local authority areas. We regularly receive updates from our council tax team with regard to movers coming into the authority, account changes, and most electoral registration officers and teams would be fairly proactive in reaching out to those individuals and encouraging them to register because they''ve moved address and, therefore, they will have, potentially, lost their right to vote at their last address. So, I think electoral registration teams have got quite good at becoming proactive and chasing up changes to addresses. So, I would say that AVR isn''t the only mechanism we have to get these people registered. Obviously, it does require a little bit more input from those individuals themselves.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Sandra Matthews', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=4996&l=en', NULL, 109.2, 'High', 'digest', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; evidence session', 0, '2026-09-18T11:33:49.353066', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769950', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16871f9449bc46f43507', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Because we''ve managed it over time.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4045&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.531596', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777440', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16a24f3d4fffbde09ef2', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'The accountability is here to this committee. We set our own targets, so we''ve set that target. We don''t set targets to fail them. We set that target because we felt it was important and we want to try and achieve it. But my accountability is to this committee.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Michelle Morris', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=8356&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:37.922087', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777493', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16bffd2f6fdd755ba64b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'I refer Members to my declaration of interest. In the programme for government, Minister, there is a piece that talks of the Government looking at examining the permitted development rights and bringing into beneficial use redundant farm buildings for housing purposes. When councils are developing development plans, they require clear guidance from central Government so that those plans can be enacted and deliver the houses that many local communities are desperate to have. If that measure was introduced, that would have a big impact on freeing up redundant buildings for beneficial purposes and creating properties that people could live in in rural settings. It''s already been enacted in many parts of the United Kingdom. When will the Welsh Government be giving that guidance to councils to bring forward those properties to be redeveloped out of redundant buildings that exist in the countryside?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Andrew R.T. Davies', '', '143', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=7360&l=en', NULL, 77.0, 'Medium', 'digest', 'planning_system; fiscal_and_legislative_context', 'Context; Planning & place', 'Housing minister', '', 'permitted development; programme for government', 0, '2026-10-10T14:39:12.674536', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776740', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16c263fca60cb087d583', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I thank the Member for drawing attention to the genuine pressure that exists, which is caused by childcare costs. Even though my children are getting older now, I remember clearly the heavy costs involved in providing childcare, and we as a Government are determined to help, with regard to the financial costs, the opportunities given to children, and the economic opportunities that follow for parents and so forth.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16c3ac11e787d003519b', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'I think, on this, what we have heard is that it is incredibly complex and the variety of stakeholders and people interested in this that should be involved in this work is really, really broad. We''re thinking community groups, developers, landlords. It is a huge swathe of people who might be involved in this. I think, yes, there is a role for legislation, but if we think the solution is only going to come from legislation, that''s not going to work. I think we need to look at a really broad suite of policy tools because what we have seen through developing the handbook is that ways of working and that idea of culture and corporate responsibility at a local authority level are really, really important. So, it is finding, I think, the appropriate policy tools to enable that to happen that is really important.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Dr Helen Taylor', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=2860&l=en', NULL, 201.2, 'Critical', 'immediate', 'private_rented_sector; taxation_of_property; committee_scrutiny', 'Housing system; Private rented sector; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry; landlords', 0, '2026-10-07T06:31:25.208085', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774965', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16ec55b74352c8f33ffb', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'It''s probably also worth drawing the committee''s attention to the ‘Wellbeing of Wales’ report that was published today, which is where we publish the national indicators, the outcome indicators—things like life expectancy, household income, a whole range of different kinds of outcomes that Government activity intended to influence positively, obviously. But, yes, that''s a very transparent and detailed account of the kinds of things the Government''s seeking to influence in the wider world, which can be assessed against the spending that the Government''s making.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Andrew Jeffreys', '', '', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=7942&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.763283', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774217', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('16f6e268ccf90c15e10b', 'calendar', 'Senedd forward look', 'Local Government, Housing and Planning Committee — 19 November 2026, 09.30', 'Local Government, Housing and Planning Committee is scheduled to meet on 19 November 2026 at 09.30.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('17470f2c6d6845c78d19', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'It''s revenue.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1716&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.176285', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777310', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('174d82afb9545ff773bc', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Yes, I was recently at a couple of events for an organisation in Hull called Giroscope—one in Hull and one down in London—and they''ve just celebrated 40 years, and they literally started off that way. They started off with one house, now they''ve got over 100. Although they did stress that they acquired a third of their stock during that very short period when there was a funding programme that allowed them to have funding to acquire it, and that really emphasises how you can step things up, whether it''s at the beginning or later on in the journey.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Chris Bailey', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16900&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.947854', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775582', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1750d5b4944a9494f945', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Oh, I agree, yes.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9768&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.214302', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774253', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('176d5eb003670da098b5', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Yes, originally.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Matthew Jones', '', '12151', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=16182&l=en', NULL, 55.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', '', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.419001', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776985', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1786ff4771fc8623373d', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'On the Bay 32 deal, it was reported that the contract would finish in 2082, in 56 years, to be purchased for £1, which means, essentially, the deal is expected to benefit us much further than 2082. Has there been any consideration into the fact that, in the future, we may not require the same style of office that we require today, and certainly not yesterday?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Cai Parry-Jones', '', '12174', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3059&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.386299', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777383', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('17a0826ebfda2b217fbd', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I tell you what, Llywydd, if the Member thinks you can only do one thing at a time in Government, she should give up her aspirations right now, because it is all about dealing with a host of issues that are in the interests of building our nation. It is about doing the work that we''ve done over the summer to pump money into health and to change our attitude on how we bring those waiting times down. It is about the numeracy and literacy strategy that is being published today by my Minister for education. And when it comes to this pursuit of more powers, which Reform absolutely rejects, let''s remind the Member that it''s because of powers taken on around a decade ago over non-domestic rates that we are now able to make a positive decision to help businesses in Wales through a cut of a third in the rates for businesses in hospitality and leisure. We have our eyes on the future of Wales, and I suggest that the Member opposite does the same.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=976&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:24.966630', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768990', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('17ba2d9d03eb72631d05', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I was just going to say, along the way, we''ve got into a bit of a mess in terms of our homes became assets. We talk about rental yields and profits, rather than just being our home. If you watch Homes Under the Hammer , you know, you''ll get a feel of that. But Maslow says shelter, home, is the foundation, and I think if we get this area right—. We work with so many people who, when you boil it back down to what''s going on, they haven''t got that stable home. They can''t build on it. They can''t get access to employment or training or move forward in life because that home isn''t stable. It impacts everything. So, I think, call them ''homes'', not ''assets'', and getting this right is so important to everything that precedes that.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Trystan Jones', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17746&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:27.106187', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775424', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('17c7ef3cbf33565bd687', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Thank you, Ian, and I think that is something for us as a committee to consider. I think that in the advertising material for a seat on the board, there is an example—', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2764&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.292958', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774171', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('17e2d658ddf1ef4badf2', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Certainly. It''s good to be here, and thank you very much, Chair, for the welcome. The staff salaries and costs for 2026-27, £34 million, and then the £37 million in 2027-28, 2027-28 includes the new baseline with Senedd reform added into it. The Senedd reform cost was split out into the ''Ring-fenced project'', which is a line lower down in the table. It doesn''t quite match up because that''s the whole of the ring-fenced budget rather than just the staffing costs. So, when that is taken into account, that''s where the difference comes in.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('17e7540f33478d91c109', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I don''t know if I can answer that because it''s from a council tax perspective, I guess, but I think it''s having the manpower to be able to monitor the properties to identify when this is going on, because we''re only becoming aware of this when we get a complaint. Generally, we only get that complaint when the property''s falling into disrepair. There are certain checks that can be made and are being made in certain local authorities, so owners are asked to provide confirmation that they''re living there in terms of utility bills and that sort of thing. So, there are checks that can be made, but, again, it boils down to staffing, I believe. I don''t know if further legislation is needed to manage that better. I don''t know if anyone else has got any views.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Georgina Wayman', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6211&l=en', NULL, 195.5, 'Critical', 'immediate', 'hmos_and_standards; taxation_of_property; committee_scrutiny', 'Housing system; Private rented sector; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; disrepair; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.673932', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775505', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('17fa29b342341c768e15', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'In terms of the draft budget, the money is in it for bilingualism, and, in terms of our priorities as a Senedd, everything is planned bilingually as a matter of course. In terms of measures in terms of holding sessions such as this bilingually and, in terms of the papers and the clerking duties, managing that and ensuring that we have enough people who can do that. Of course, we''ve talked about AI earlier in terms of how translation can be used in that field as well. So, it''s becoming more and more interesting to see at how technology can help us. We know that in terms of the Chamber, and committees like this, that the interpretation service works very well, but we''re always looking at how that works. It depends on the availability of translators, and, of course, we''re a trilingual Senedd now, rather than a bilingual one, because we have BSL in the Chamber, which is a very good development following the Act that is now in place, for deaf people.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1808d667d737624efecb', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Thank you. Georgina, can I just bring Rhian in quickly and then we''ll go to you? Rhian.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5805&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.608386', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775416', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('181474e8f30e7045828d', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Well, look, we found ourselves, post Brexit, in a situation where we didn''t have that environmental governance oversight. It was a vacuum that needed to be filled. Other parts of the UK filled it. And regrettably, we didn''t get to the point where we had that body in as timely a manner as we would have wished. We''re now getting to a position where that is in place. And it will be a key part in that ecosystem, if you like, in terms of having that oversight on Government and others. And it''s one element, I think, in a bigger picture here, because we will have the statutory targets for biodiversity coming on board. Work has already started on that as a consequence of legislation passed in the last Senedd. And as somebody who sat over there arguing for strong and meaningful targets, we will make sure that that is the case. And as somebody also who sat over there arguing for the environmental governance body to have teeth, I will make sure that that is the case as well. So, there''s a lot happening. Rhodri, do you want to add anything on that?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2835&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.709782', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772000', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('183ea6c3ab7778f2f11c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'So, the information that we, hopefully, will get now from the universities on their data, which is really up to date since September now, of all the students that they have, will make sure that we''re capturing and giving them that opportunity to vote. Because sometimes they''re not on their home electoral register, so they find themselves disenfranchised—they turn up to a polling booth, they want to vote, but they can''t, because they''re not registered. So, this would capture that particular cohort, as well as lots of other people. I think there are—. What''s the figure?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9769&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.218043', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775799', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1840cfc390358b15400f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Well, the software is about the registration, isn''t it? It''s not about how people actually use their vote.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=10946&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.468262', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775025', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('184f710f10433904848e', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes. Thank you, Chair. Good morning, both. Thank you for joining us this morning. It is an important area that we need to discover. I suppose, if I could start with some of your thoughts on the evaluation of the pilots and just, really, if you could help us understand the main challenges you''ve found, through the pilots, to delivering automatic voter registration effectively. What are they likely to be for us?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=156&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.702076', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769807', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('186263c59a5f60861833', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'No, no, you''re the expert. [ Laughter .]', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6322&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.151053', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772121', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1869449e69298b3cf6b8', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you for that full and comprehensive answer, Richard. Cabinet Secretary.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5804&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.071022', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772062', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('189105299d3dd29c74db', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. I think that what Joe was maybe clunkily referring to is positive action that''s being taken to tackle barriers to equality. So, I''d be really keen to hear what actions the Welsh Government is taking to tackle gender inequality and whether you have—I''m not sure whether it comes into your portfolio—had any evaluation of—it was quite delayed—the previous work that the Welsh Government did on gender budgeting pilots and to see if that will be taken forward at all.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4309&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.989947', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771294', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('189581ac0a90d7e360d8', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Thank you, David. Elyn.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5547&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.444879', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#770015', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('18a6da320a947773ddfd', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'So, that''s what these regulations are actually about. It''s about making sure that people are on the register, and, should they wish to take that up then, they can. The point you make about the specific care home, I''ve no idea what that would be about. But if there are concerns, obviously, they are matters for the police. But, on the other hand, I would say it is a delicate balance, isn''t it? Do you want to disenfranchise a particular cohort of people? It is a balance. But if there are obvious signs that something is not right, well, that''s a matter for the police, then.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8523&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.961968', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774451', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('18ac55fbd84b6d0f1ae1', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'We just haven''t got to that stage of the transition yet in terms of the design of what that will look like. It''s just far too early days. So, yes, nothing more detailed, but, obviously, we won''t be looking to throw the baby out with the bathwater, in that sense.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Lia Murphy', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=2362&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.032489', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773171', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('18d47def200da8baf283', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Okay, thanks. And just sticking to staff salaries and related costs, you''ve outlined an efficiency saving of £227,000. Are those identified projects or is that just a broad challenge you''ve given yourselves for the year?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=10832&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.284898', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777646', NULL, NULL, NULL, NULL);
