INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1954ed14e644bb51ca83', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Before I come to the questions that I have, I just wanted to pursue future rent and what it is now, given that you mentioned that it will be cheaper, the rent, if I understood correctly. Over 50 years, I think it''s £135 million. If we were to do nothing and not continue with the project, what would the cost of the rent be moving forward?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4052&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.534745', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777442', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1967025046d9c410694d', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'You know, I was listening to the radio this morning and I heard one of the commentators talking about it being a bad week for NATS; I thought they were talking about the Welsh nats, but actually, they were talking about the National Air Traffic Services, as it happens, and the chaos at our airports. [ Laughter .]
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('19766bdf9ec6310cd40b', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'Today I''ll talk about our first phase of legislation. This recognises the dual importance of bringing early momentum to this legislature''s work whilst allowing space to build agreement and develop genuinely impactful legislation across a full four-year term. There are several areas where action can be taken swiftly.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1999c752dd8a86b89b83', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you. Swansea University are the fourth in the UK in terms of innovation in biodiversity, including pest control, fertilisers and drug-control-resistant plants. I''m just wondering if the Minister has had any discussions with Swansea University. The scientists that they have there are really quite cutting edge and exporting a lot of what they currently have, and, with the change in the climate, the work that they do is ever more suitable for the needs of what we have here.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'John Davies', '', '4650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3105&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.755436', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771911', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('19bb93716c78780f3daa', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I''m just conscious we''ve just hit the 1.30 p.m. mark—', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5239&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.041242', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770547', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('19d0ed706b7c8b42b29f', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Thank you, Llywydd. As noted, this is the first time that I have spoken in a Plenary debate in my capacity as Chair of the Early Years, Children, Young People and Education Committee. The committee discussed the supplementary budget as it relates to its remit at its first meeting on 8 July. The committee agreed to write to the Minister for finance, and that letter was published on Monday.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('19d4772fe52aa87f0275', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Formally.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sian Gwenllian', 'Cabinet Minister for Local Government, Housing and Planning', '4981', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=14922&l=en', NULL, 88.0, 'High', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', 'Housing minister', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.292277', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776949', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1a1fa96a66538f5d614e', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'It''s something that I know the Llywydd has spoken about in the Commission, looking at the shop provision. And, obviously, as somebody who visits other Seneddau around the world, it varies very much, even if you go to Westminster. But it''s certainly something that we need to possibly look at and see what that looks like.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1a5662b079ea97f1a951', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Thank you. And then the last one from me is just on project expenditure and capital funding. What''s the distinction between the project fund and the capital expenditure in the budget, and what will you achieve with the combined £2 million in the budget next year?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Benjamin Hodge Mckenna', '', '12142', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3884&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.495413', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777422', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1a592191a94369feba69', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'We, of course, are continually—officials are continually—in touch with those organisations, of all types, who deliver on our work programmes. I have, since coming into post, attended the forum where the Welsh Refugee Council is a member, so I have heard directly from them about their experiences in that regard. But, of course, as a Government and as officials, we are ensuring that we hear from them about anything that interferes with their ability to deliver with what they''re seeking to do to support our communities.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6844&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.289883', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771264', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1a8fa11eb7ac52df595f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Sometimes people make houses uninhabitable. There is a house in Penllergaer that is a four-bedroomed detached house, which is very nice and it''s on the main road, and the doors have been bricked up, the windows have been bricked up. It''s uninhabitable, because you cannot get access to it, but it is an empty property that is very nice and incredibly saleable.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=1690&l=en', NULL, 184.0, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; empty property; evidence session; inquiry', 0, '2026-10-07T06:31:25.027661', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775354', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1a990319593c5be42531', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'On that one, making sure that new homes are built to those standards, particularly around heating, is going to be another win there.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Paul Rock', '', '12176', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4598&l=en', NULL, 97.7, 'High', 'digest', 'housing_supply; committee_scrutiny', 'Housing system; Planning & place', 'LGHP Committee members', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; new homes', 0, '2026-09-25T06:30:34.896984', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771943', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1ae0796eec9ed991eb26', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'Well, I''m sure I could have made this statement at any point during the summer term. The statement was ready to be made. I chose in particular to wait for the first day of the Senedd being back in session to make the statement, and I''m making it on the floor of the Senedd in order to receive questions from other parties and from Members here to see how they respond to the statement, and what else they think that this system should deliver. After that five minutes from the Reform representative, I''m not sure whether Reform are going to support this reduction of 30 per cent in business rates for this sector, which is a really important sector for our town centres, or not. It wasn''t clear to me, from what you said, whether you would support it or not. But you''ll have to decide on that, of course, before the voting happens on the floor of this Senedd one way or another on a change of this kind. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1af1ecc165aab829de36', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'No.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Francesca O''Brien', '', '12190', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=10284&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; Opposition housing leads', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.335398', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774487', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1b147d84c23d84b5fbe6', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'In response to the recommendations, we have reviewed our entire process in terms of own-initiative investigations.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Katrin Shaw', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=9676&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.105936', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777720', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1b2adb4e7f3797518ac7', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Yes, definitely, and I think the beauty of community-led housing as well, and you''ve touched upon it there, is that they can actually bring in additional grant funding as well to be able to bring these properties back into use. So, they''re not solely reliant on Welsh Government or local authority funding. So, it does have the potential to grow, so it doesn''t just have to be that one property, for example.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1b62099c5235de38e4e7', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Thanks.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Cai Parry-Jones', '', '12174', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1612&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.134962', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777256', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1b7e5671b7c265361420', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Four hundred thousand people in Wales don''t vote because they''re not on the register. So, you know, they''re missing out on a huge opportunity, aren''t they? And many of those are young people. I think it''s 48 per cent—?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9813&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.229509', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775801', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1bb10d37862512937891', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much. This touches on the next topic as well, to be honest. Unfortunately, during the sixth Senedd, we heard about the experiences of organisations that support refugees, for example. I just wanted to check and to hear from you how you have reached out to those organisations, for example, the council working here in Wales with refugees—just to hear a little bit about that, that''s all.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jane Dodds', '', '4983', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6813&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.285773', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771261', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('1bc20705bd8bcdcdafbf', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Throughout our ambitious programme for government, we commit to take action to reduce financial pressures facing households, working to break the cycle of poverty that too many find themselves in. Our new child poverty strategy will set clear targets and milestones to drive ambitious, deliverable change. We''ll also seek to introduce the Cynnal child payment pilot. This Government will help those in crisis, while taking longer term, strategic action to prevent people falling into poverty in the first place.', 'https://record.senedd.wales/Plenary/16313', '2026-10-06', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16313', 'http://www.senedd.tv/en/16313?startPos=2910&l=en', NULL, 55.0, 'Medium', 'digest', 'fiscal_and_legislative_context', 'Context', 'Sector bodies; First Minister / Cabinet', '', 'programme for government', 0, '2026-10-09T13:35:09.667988', 'https://record.senedd.wales/XMLExport/Download?meetingID=16313&xmlDownloadType=EnglishTranscript#775904', NULL, NULL, NULL, NULL);
