INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('201c2c9c22af95ce28ff', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Thank you very much for coming. A transcript of the session will be available for you to check for any inconsistencies or errors. We will see you again.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5295&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.080482', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770556', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('20463e29877e8e5838c9', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thanks. I used to sit on the human rights advisory group with Welsh Government, so I wanted to ask whether that group was going to be reinstated or whether there would be any sort of different group, to ensure that there are relevant organisations able to inform the work—for example, Amnesty International, who obviously have a lot of expertise in this area. I''m very aware, from all the work that Welsh Government did on that previous group, that the incorporation, and the progress of that incorporation, was slow because of funding constraints, time constraints. This is obviously really complex and detailed work, and I think it''s important to flag and find out how complexity will be avoided whilst ensuring that we don''t lose the nuance of specific conventions because, from my limited legal experience, the change of a word can have a huge impact. And I''d like to ask whether the Welsh Government has ruled out direct treaty incorporation. Thank you. Sorry, there''s a lot in there.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2822&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.872079', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771215', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('206dbf1f65030045d368', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Who puts the limit—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1659&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.152391', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777273', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('208125a8148202194f39', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Yes, very good.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Ed Williams', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4568&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.610791', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777351', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('20c224bd610f68bc30fd', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I was waiting to speak, sorry—I guess I''ll jump in first. What''s been most difficult over the years is the 0 per cent, 30 per cent tax premiums. Our project takes six to 24 months to renovate these empty houses. We''re working with local community groups to do that, so our tax bill is enormous, but we''re bringing these properties back into use in a meaningful way and things are happening. So, the new exemptions are a step forward in the right direction, but they''re still time-bound; I think they would be 12 months long. It would be good to see them aligned with the renovation plans, perhaps. But it''s definitely a step forward in the right direction, anyway.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Trystan Jones', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17013&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.971266', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775593', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('20e38da69a57b9404517', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think it''s bigger also than just elections as well, that input. This is being done and, as Sandra said, it''s influenced, maybe, what Powys have done through their lessons learnt. But I think it''s more around how you create an infrastructure within local authorities and even with national data sets. Through conversations with the Democracy Club, they''ve talked about the quality of data, of addressing that across the board, to allow you to have the data sets that take away properly the risks that sit around those things, such as assuming everyone has a UPRN, on what data, or how the context or standardisation is, as you said. But that''s a wider, bigger problem across the board.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Clare Sim', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5789&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.484261', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769951', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('21105520a8be21247aa0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Under Data Cymru, you''ll have a list of all the exemptions. There''s about 19 under council tax and they''ll have class A, which is uninhabitable, very poor-condition properties. Class C is properties that are empty between lets. Class F would be exemptions from people dying. So, you will have from Data Cymru—I can certainly provide them to you—. They will be able to give you the split for the reasons why the exemption applies under council tax.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Andrew Lavender', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=1663&l=en', NULL, 172.5, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Delivery bodies', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.022591', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775353', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('211a3a60b5209251084a', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'In the order of about £4 million. That makes the difference.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=218&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.923307', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777380', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('212e358268d3c481d735', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I think it''s important to note that different local authorities treat commercial properties, when it comes to empty properties, in different ways. So, just within our shared service, my role doesn''t extend to commercial premises. I''m very much residential, unless we have a particularly problematic property that needs intervention. So, I''m very much residential. In the Vale, it''s very different. It''s more commercially driven at the moment, and, again, Cardiff is very residential. And that would be the same across Wales. They sometimes are very separate roles within the organisation. Maybe there''s a need to bring that together so that it''s more coherent, but it does make it difficult to deal with things like churches and chapels, because, from my experience, that remit sits with regeneration and relies on the grants and loans that they are able to offer, and I wouldn''t really be able to input to that.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Georgina Wayman', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6745&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.754151', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775469', NULL, NULL, NULL, NULL);
