INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('272e704e5e735ed47cc6', 'plenary_transcript', 'Plenary', '6. Reform UK Debate: Default 20 mph speed limit', 'It''s a pleasure to be able to speak in this debate today, tabled in the name of my friend Llŷr Powell, on scrapping one of the most hated pieces of legislation to come out of this Chamber in a decade. A policy cooked up by Labour and Plaid Cymru, not in response to public demand, not with solid evidential basis, but because it was a fashionable left-wing policy that was gathering steam elsewhere, and they didn''t want to lose out on the trend. The same can be said about the tourism tax, and now plans for rent control—all disastrous policies stolen from other failing far-left governments.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2762a6e874b06fbd99a3', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Thank you so much, Presiding Officer. Minister, fuel poverty has been, and remains, a huge concern for many residents across Wales, and it''s something my former colleague Mark Isherwood campaigned on tirelessly during his time here. We have heard warnings previously that the former Labour Government''s Warm Homes scheme was nowhere near what it needs to be and would not have provided what was required to tackle fuel poverty. A report by the Equality and Social Justice Committee back in 2025 found that it would take more than a century to improve the energy efficiency of all fuel-poor households.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2776fb493372e1eae844', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Will the Member take an intervention?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Zaynub Akbar', '', '12141', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=14692&l=en', NULL, 66.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', 'Other committee chairs', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.257244', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776901', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('27823627ade8a6955504', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Thank you, Members, and thank you Chris, Lia and Mark for your contributions this morning in committee. We really appreciate your time. A draft transcript will be sent to you to check for accuracy. Thank you very much indeed.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Vikki Howells', '', '5107', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3472&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.199060', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773309', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('278391f97f5f38c74d86', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Thank you. First Minister, we know that immigration increases demand on housing which, in turn, leads to increased rents. So, can the First Minister confirm that any planned changes to private and social renters'' protections will be prioritised for Welsh people over recent arrivals?', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'David Hughes', '', '12159', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=2197&l=en', NULL, 99.0, 'High', 'digest', 'private_rented_sector', 'Private rented sector', 'First Minister / Cabinet; LGHP Committee members', '', 'renters', 0, '2026-09-16T11:53:07.208142', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769004', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('27b130b356887d3792c5', 'calendar', 'Senedd forward look', 'Finance Committee — 26 November 2026, 09.30', 'Finance Committee is scheduled to meet on 26 November 2026 at 09.30.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('280ce97ed087c9e643dd', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'Holding you to account is our responsibility as an effective opposition. Take the NHS. You''re promising up to 10 surgical hubs, more diagnostic capacity, stronger clinical pathways and up to 100 more general practitioners. Those are ambitious commitments and people will expect this Government to deliver them. So, my first question is this: by the end of this Senedd term, how much lower should the overall waiting lists be, when will those surgical hubs be operating at full capacity and how many additional patients will they treat? Give us the baseline. Give us the target. Give us the date. Then, this Senedd can hold you to it. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2815f9c5eb1aa1e4f7b6', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'I''d like to move on to the human rights Bill now. I wondered what the expected timeline for the Bill is, and how Welsh Government intends to keep the Senedd committee and civil society up to date on the progress.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2611&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.852013', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771209', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('282853c0fab48b0d424a', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Well, we do annual letters every year for the public bodies that are operating under the complaints standards, and we''ve just recently released those annual letters, and that includes all health boards. So, I think they''re very aware of their complaints numbers and the increase that is happening. 
