INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2996875010bb7eb8ca1f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'How many apply? What''s the percentage of people who apply and actually go through with it?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5726&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.589857', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775403', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('29fd8d1f8b5bfdeb8449', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'One thing I was going to mention on that specifically was social media and the increase in misogyny and whether that''s being considered.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5275&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.101327', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771253', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('29fda3702f77a154cee8', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'There''s a question, as you say, about vaccination in cattle, but vaccination in badgers is an approach that''s being utilised. And not to prejudge the work that''s ongoing at the minute, but that could well be a part of the approach here in Wales. I don''t know if you want to add anything on that. The DIVA test is obviously the issue there for cattle, isn''t it?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5886&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.084230', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772075', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2a05bc97256ca1c149d6', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'But it''s that starting one, isn''t it? That''s the problem.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=3548&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.315439', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775329', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2a0bbcea37e9b478a9eb', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Of course, the decision on going ahead hasn''t yet been taken. That''s why it wouldn''t have been reflected in this budget currently.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=583&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.986327', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777386', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2a38971e07e7efe159a7', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'I''ve got two issues, and I genuinely really want to understand this. You keep using the phrase, ''I want the people of Wales to decide their future'' in relation to the issue around independence, and I really would like some clarity on that. What does that mean? How will you measure it? How will you make sure you know what the decision is by the people of Wales? And just to put on record, I''m anti-independence, but, absolutely, we need more powers here in the Senedd.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2a471361009aca6b365f', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'So, if a particular project costs many, many times what was predicted and becomes a money pit, essentially, do you have a way of seeing that?', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Paul Rock', '', '12176', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=2153&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.999185', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773184', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2a71fa16a8c4d942759b', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'You will have a lot of students joining in the next couple of weeks. So, the matching system and the work with universities will, obviously, help you with that and you''d hope to get the halls of residence and other university accommodation picked up. So, this is the time of year to do that, isn''t it, for universities? But, for people in HMOs, people in other types of accommodation who move very regularly, people in bedsits who move very regularly, people who are in supported accommodation who move fairly regularly, how are you going to make sure you keep on picking them up?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5079&l=en', NULL, 138.0, 'Critical', 'immediate', 'hmos_and_standards; committee_scrutiny', 'Housing system; Private rented sector', 'Opposition housing leads', 'Opportunity to influence', 'HMOs; Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.363589', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769941', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2a8a8a995c7023b7229c', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you. I think you''re right, the programme for government did list a non-exhaustive list of a number of health issues that are related to people in Wales. When I say ''non-exhaustive'', it means that there are others out there that we will be tackling and looking at. Lung disease is clearly one of them, and we know that, when it comes to lung cancer, it is one of the biggest killers in Wales still. That''s why one of the priorities of our Government is in that preventative field, so that we stop people reaching that stage of living with or suffering from lung cancer. And that''s why one of our ambitions is to roll out lung screening in Wales.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16314', 'http://www.senedd.tv/en/16314?startPos=3624&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-10-10T14:39:12.359823', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776659', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2aad5d842249d15ca771', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Following up on that as well, I was just wanting to have an idea of how the marine environment ties up to it as well. Sometimes, as we''ve discussed as a committee, it gets quite overlooked, the marine environment, and I feel like progress has been halted a bit from previous Governments when it comes to marine environments, when it comes to marine protected areas as well. So, I was just wondering what your vision is for that as well, and, with the Office of Environmental Governance Wales, how that ties into it from a marine side.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2924&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.720776', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771888', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2ab169490c7ed735a1ff', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Thank you. I find this really interesting. Like Marc, in a previous life I was a councillor, and I was chair of a scrutiny working group looking at empty properties, so I do appreciate the challenges that councils do face and I''m sure that''s going to impact next year with financial decisions as well. You mentioned, Georgina, that things could be made easier in terms of streamlining. I appreciate there''s no silver bullet—if only there were, it would make life a lot easier. However, is there anything that really jumps to the forefront of your mind that would have made, let''s say, the compulsory purchase a little bit easier, or is there anything that, day to day, would make life a little bit easier? What I don''t want us to do is have a top-down approach. I’m all for regulations. However, before we start thinking of that, I would look at, maybe, sometimes, the red tape and bureaucratic processes that we might have at local government level so that we can make your life a lot easier to execute your work properly.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Francesca O''Brien', '', '12190', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5276&l=en', NULL, 207.0, 'Critical', 'immediate', 'taxation_of_property; local_government_enforcement; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; compulsory purchase; empty properties; evidence session; inquiry; working group', 0, '2026-10-07T06:31:25.523712', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775237', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2abf402a66205015a288', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'This is beneath you, finance Minister, it truly is. It truly is. And I wish that you would focus more on negotiations than attacks, I really do, because you may be more successful in getting future budgets through this Senedd.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Ken Skates', '', '267', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26436&l=en', NULL, 44.0, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'Opposition housing leads', '', 'supplementary budget', 0, '2026-08-04T14:03:10.859541', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767977', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2b03083a3439e9c843bc', 'plenary_transcript', 'Plenary', '5. Statement by the Cabinet Minister for Local Government, Housing and Planning: The Revision of the National Development Framework and National Conversation', 'Thank you very much, and thank you for raising a number of important points there. Whilst this consultation is ongoing, and it is an important consultation, of course, there is also a great deal of action taking place in this Government. As a mother who brought up four children alone, I know full well what it means to juggle different priorities and to keep many plates spinning simultaneously. So, the suggestion that one simply does one thing and therefore can''t do anything else just isn''t realistic in my own experience. Many Ministers and I have a whole host of different issues that we are working on as we speak today.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2b1b7d44f087b2371695', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much for the question and I know of your interest, Jane Dodds, in this matter and I agree with the need for targets, and you know that. So, we are currently developing these targets. There are a number of dimensions to poverty, and poverty is felt in different ways, so we want to ensure that we consider that as we develop the targets. As I said, the experts are engaging with us on that, in terms of what they think the most meaningful targets would be. Because, yes, you could take one poverty measure and decrease it by 5 per cent, say, and then you would expect that that would have an impact, but if that isn''t felt, perhaps, by the families in terms of the impact in their daily lives, is that what we want to focus on? So, we are discussing all of these things at the moment.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2b625a81ba863433a0f0', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you very much, all. As I said, this is our first general scrutiny session with you, Minister, and we look forward to, in the rest of this Senedd term, having regular sessions with you and, hopefully, you''ll be accommodating to our asks in the future. Given recent events, Cabinet Minister, with drought and wildfires across the country, I was going to focus the first part of the session specifically on that area; I think it''d be beneficial to Members. But, before I hand that over, I''ll probably just give the opening question, as is my prerogative as Chair. If you could just outline some of your priorities for your term of office, because, obviously, if everything is a priority, nothing is a priority. So, it''d be quite useful to hear from you what your priorities are as the Cabinet Minister.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=98&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.287937', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771857', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2b8b8bf498c3f33ccc29', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Families across Wales are waiting to find out when exactly they will receive their child payments. The work needs to have been done with the DWP to make sure that it does fit with UK welfare benefits, and also with the use of data that can be done across with the UK Government. But it''s also critical that it''s done with local authorities on issues such as the council tax reduction scheme. So, can the Minister confirm when the child payments will start, and that it will not affect families'' eligibility for other financial support?', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Jayne Bryant', '', '5038', '', '', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', '16084', 'http://www.senedd.tv/en/16084?startPos=1024&l=en', NULL, 88.0, 'High', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet; Opposition housing leads', '', 'council tax; council tax reduction scheme', 0, '2026-08-04T14:03:15.541377', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#766816', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2bced3597f6480d5d19d', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I welcome the emphasis in the consultation on increasing community energy, and I think it''s shameful and shameless of Reform UK to abandon—[ Interruption .] It''s my job—to abandon and just to sideline net zero. The world is on fire. As the First Minister has said, you just needed to look and see and talk to the communities that we represent over the summer just to see how bad it is.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2be89c3733607ebf40b0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'My name''s Andrew Lavender, I''m a housing consultant. Morning.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Andrew Lavender', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=91&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:24.784483', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775123', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2bec7431a4371da87b50', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'You''re right to say that the group needs the time and the space to do what they need to do and not rush the process. I''ve been saying previously that it''s imminent. I now understand that maybe there is a bit more work that they need to do, but again, I don''t think that necessarily takes us beyond Christmas.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6176&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.121251', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772136', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c02ecc18156f89ad812', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'One example is one that we''re going to be looking at later—the Commercial Payments Bill SLCM. It''s particularly—. We''ll report on it, so you''ll get to know about it, but certainly that''s one example there. I''m speaking on behalf of myself: it wasn''t acceptable what we received. Huw, did you have anything further?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3962&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.772805', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770454', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c04b5e2105c61f05d88', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Okay. Thank you. Can you tell us, maybe, a little bit about the discussions with Welsh Government around that new national water strategy for Wales as well?', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Vikki Howells', '', '5107', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=738&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.831971', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773141', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c12d5b2349e01f9fed3', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Lorna Hall, deputy director of equalities.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Lorna Hall', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=108&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.567876', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771146', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c2c376650c4b74cd808', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'I''m not a Canadian at all. [ Laughter .]', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'John Clark', '', '12169', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=16182&l=en', NULL, 55.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', '', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.420025', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776976', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c526352158cedf39812', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Sure. And it''s about striking the right risk balance here, I suppose. We''ve heard clearly that slurry stores are fuller than they should be at this time of year. Going into a closed period would be problematic for many because, clearly, those slurry stores potentially would be too full. You could have those stores overflowing or even failing, which would be quite catastrophic for the environment if that were to happen.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c74a3694a7db0795172', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Thank you. Foreign nationals living in Welsh and British social housing should be given a grace period of three months to find private housing, after which, they should be deported. It isn''t the responsibility of the Welsh or British taxpayer to fund the living arrangements of people from overseas. People moving to the UK should be able to afford to buy or rent a house at normal market rates before they move here. If they can''t afford to live here without help from the taxpayer, then they shouldn''t come to the UK.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c800b310d61801f1e24', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'I think one of the failings in the current system is there seems to be no end for teachers and headteachers at times in that process. The lack of that independent oversight and external oversight at the end of the process—whoever it is, whether it''s PSOW or not—means that complaints can sometimes go on and on, and of course that has a detrimental impact on the learner.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c93500d7df8efc9f7b0', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Well, I''ve spoken, haven''t I, about my role in managing the Welsh public finances in-year that I''ve inherited from the previous budget and how we''ve put together a programme for government and priorities into action for this year. So, there is no supplementary beyond the annual budget that we inherited at this point. That causes me concern, that some of the allocations that we are making within this financial year need at some point to be formalised by a supplementary budget. You''ll know that discussions with political parties are continuing on how we can successfully navigate a supplementary budget through the Senedd. Those discussions are ongoing, and you will be amongst the first to know if there are any changes to the situation we''re in at the moment.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c98fac71ac9abc1c5ca', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Okay. I just wanted to—.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1511&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.109299', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777225', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c9ed8e0a24bbbff8e7d', 'committee_transcript', 'Legislation Committee', '1. Motion to elect a temporary Chair under Standing Order 17.22 for this meeting', 'Good afternoon, everyone. Welcome to today''s meeting of the Legislation Committee. Under Standing Order 17.2P(v), the position of Chair of a committee becomes vacant when the Member concerned joins or leaves a political group. With Sarah Cooper-Lesadd MS having left the Reform UK group and joining the Plaid Cymru group, the position of Chair of the Legislation Committee is now vacant. The first item of today''s agenda is the election of a temporary Chair for today''s meeting. Therefore, under Standing Order 17.22, I call for nominations for a temporary Chair.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Sarah Sargent', '', '', '', '', 'Legislation Committee', '1. Motion to elect a temporary Chair under Standing Order 17.22 for this meeting', '16254', 'http://www.senedd.tv/en/16254?startPos=3&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.034721', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770407', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2c9efd768f7f15fefcd1', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Okay, thank you.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4939&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.953783', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771805', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2cbfcff6f91711b9bde4', 'committee_transcript', 'Petitions Committee', '2. New Petitions', 'Diolch, Chair. In the sixth Senedd, a petition similar to this had around 4,000 signatures, and was considered with input from RSPCA Cymru and Blue Cross on how to strengthen enforcement at the time. That petition closed in 2022, with the previous committee noting the then Minister''s plans to improve the training and skills of local authority enforcement officers.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2cc0b7471e5d8b0f942a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'The thing we''d always come back to is that the fall-back position is that the duty with this is that they have a duty to add people to the register. If they can be satisfied that that person isn''t eligible, what happens there is they don''t just reach a deadlock; this duty is discharged, and then they can seek to try and register them by other means. So, this is an add-on, really, because it''s undoubtedly the case, as you say, that there will be hard cases and ones where they can''t be satisfied, for some reason, but it''s just that that then opens up a new route to try and find out more information from the person, either by invitation to register or other means of contact that they''re allowed to do, and then they can try and pursue it that way again as well. That will always be at their discretion to decide, ''We can''t do it with this position, we''ll try another way.''', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Ben Mincher', '', '', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=10234&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.320637', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774480', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2d006ad39ba8e878314f', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Diolch, Elin. I think the point you make about ''fully funded'' is a fair one, but I would just urge you to press ministerial colleagues when they are developing plans and legislation. Passing legislation here is the easy bit. Delivering it ar lawr gwlad is the tricky element, and, if funding doesn''t follow, then all we have is a nice piece of paper.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=9364&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.994832', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774595', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2d1d36537559c374e350', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thank you for the invitation this morning, and thank you, as a committee, for putting aside the time to have this discussion on the annual budget. Just to say, perhaps, as some context to start with, how difficult and challenging the financial context has been for us for the next financial year. You will know that the budget, as it has been allocated at the moment, is facing a cut next year of 0.7 per cent in real terms, and that the estimates for the settlement for the next three years, in terms of capital, are even more challenging, with a cut, over three years, of 9 per cent in real terms for the capital budget, as it is at the moment.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2d4911b50387898be74b', 'committee_transcript', 'Health and Social Care Committee', '2. Legislative Consent: Health Bill - evidence session 1: NHS Wales Joint Commissioning Committee', 'Thank you. I''ll going to ask you questions in Welsh, if you want to wear the translation equipment. Before I ask my question, I wanted to note very quickly that I would have liked to ask you about general things that are happening with NWJCC at the moment—things such as the Welsh Gender Service. I know we can''t focus on those today because we need to focus on the LCM and the health Bill in England and time is very short, but I do hope we''ll be able to welcome you back to go into detail on that in the future, and I look forward to that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2d4b511920a1e6bb6621', 'consultation', 'Welsh Government — Consultation', 'Allocation of Housing and Homelessness (Wales) (Eligibility) (Amendment) Regulations 2026', 'Allocation of Housing and Homelessness (Wales) (Eligibility) (Amendment) Regulations 2026
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2d75e7cab089b13c2e2b', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Okay, thank you. Those are the bits from my side at the moment. Lyn, do you want to come in?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=10884&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.294308', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777671', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2daf9ba558734b169b22', 'committee_transcript', 'Petitions Committee', '2. New Petitions', 'Thank you very much, Chair. We know that ALN provision has been a regular subject of Senedd petitions. This is a petition from the school leaders union, NAHT Cymru. It''s calling for that ring-fencing of funding, specifically calling for the Barnett consequential for special educational needs and disabilities funding in England to be allocated to the supplementary budget that was published on 23 June. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2db42e9c15f0f08d9754', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Each local authority has the ability to choose its own system. In practice, there are a small number of systems that are available for use by EROs across the United Kingdom, and they will be choosing from either two or three suppliers. So, it''s not a big marketplace. The Welsh Government will be able to engage with each of those systems providers individually as well.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=599&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.773743', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769827', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2db4af43da841cced89f', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Well, again, Chair, that isn''t my responsibility, it''s very much with the Minister with responsibility for energy and planning. I fear that, if I did pick up on that question, I really would be straying into other people''s responsibilities.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5094&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.978985', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771847', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2db58e272a163b46cedf', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'First Minister, I welcome the programme for government, and particularly the work to embed public health and preventative health across Government. One of the ongoing challenges is that the benefits of having a preventative health programmes are often delivered years after the investment is initially made, whilst the pressure on acute services is direct and immediate. In considering that, how will the Welsh Government ensure that preventative health programmes, be that in physical activity, healthy eating, the early years, or tackling health inequality, are safeguarded and prioritised when budgets are under such pressure? And what measures will you put in place to show that preventative health is steering budgetary decisions across Government? Thank you.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Sara Crowley', '', '12150', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=11852&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:20.212351', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#771030', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2dc0f5a5da05f7a42cf8', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Okay. David.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5417&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.419066', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769995', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2dd16efb5ad426ded568', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'In terms of that software, is it one consistent system across Wales, or does each local authority have their own system or something that''s slightly divergent?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=587&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.770078', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769822', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2dd420d8d0c112e4fef3', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Can I just—?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=440&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.332700', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771756', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e13bf9d2ed679784f81', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'So, as far as the reasons why properties are empty—', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Andrew Lavender', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=1647&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.017506', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775351', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e235d95b82b86dbb1e0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I think Osian did touch mainly on the point around properties that have been taken out of valuation. We don''t have information on these figures. These properties are not being charged council tax or a council tax premium either, which sort of gives a get-out-of-jail-free card for empty property owners who don''t wish to return their property to beneficial use, engage with the council or predominantly pay the penalty for having an empty property. So, I think having that data and having it accessible to empty property officers would certainly be beneficial and welcomed.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'James Wagenaar', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4599&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; council tax premium; empty properties; empty property; evidence session; inquiry', 0, '2026-10-07T06:31:25.407100', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774769', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e2ff68c7095d008ddf3', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Prif Weinidog, last week your Deputy First Minister told me that childcare must be flexible for families and deliverable for providers. Yet, when I asked what this expanded offer will actually cost, she told me that the figures will only become clear in the forthcoming draft budget. But flexibility has a price tag. Longer hours, greater capacity, rural provision and the workforce to deliver it cannot be paid for with aspiration. So, how can your Government promise parents a flexible childcare offer when it still cannot tell them or this Senedd what the fully modelled policy will cost? Surely you cost the flexibility before you promise it, rather than promise it first and work out the bill afterwards. Because however flexible the promise, First Minister, the budget remains stubbornly inflexible. Eventually, the numbers will have to add up. So, please reassure us that Welsh parents will not be left quite as baffled by your childcare maths as your Deputy First Minister apparently was by mine.', 'https://record.senedd.wales/Plenary/16313', '2026-10-06', 'Cristiana Emsley', '', '12185', '', '', 'Plenary', '1. Questions to the First Minister', '16313', 'http://www.senedd.tv/en/16313?startPos=2006&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'draft budget', 0, '2026-10-09T13:35:09.580913', 'https://record.senedd.wales/XMLExport/Download?meetingID=16313&xmlDownloadType=EnglishTranscript#775875', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e3d3d73f6a3f56b8e08', 'plenary_transcript', 'Plenary', '6. Debate: Fiscal Reform', 'Every local authority in Britain can move money into and out of reserves. This includes town and community councils and it actually includes school governing bodies, who can also move money into and out of reserves. No controls, no rules. It''s their money, they can spend it or save it. Why is the Welsh Government treated differently? Once money is allocated to Wales or is raised in Wales, the Treasury has no legitimate interest in that money. This is the way they treat Westminster committees and how they treat different spending areas in Westminster. It is not the way to treat a Government.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e48ae8c5d1e859f961a', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much for the question. We know that the signs are not positive for this winter. So fuel poverty is something that we are entirely alive to. It''s something that''s complicated. It''s something that''s deep-rooted. There are several factors involved here. There are factors that are related to household income, low incomes, but also high energy costs. And we know that they are increasing once again. And in Wales we have that poor efficiency in our housing stock, generally speaking.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e5a2b65ed630c4e17df', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'I don''t know if—. Amelia, do you want to take that question as regards the work on that?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=3387&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.941933', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771199', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e664e0854be857468f8', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. Minister, I''d like to ask how the findings of the completed violence against women, domestic abuse and sexual violence strategy review will shape the new strategy that''s due by summer 2027, and how we address implementation gaps that have been identified by the national adviser and specialist stakeholders. And would you be sharing the review of findings and recommendations with the committee?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5091&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.082665', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771320', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e68f6d2af0e4a81aafe', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you, Llywydd. Cabinet Minister, Wales continues to face significant housing pressures. We hear it all the time in this Chamber: rising homelessness, growing demand for affordable homes. Now, at the Conservative conference this week, which I''m sure you were following, the shadow chancellor announced some excellent proposals, aimed at reducing the costs of building new homes and reforming planning rules to support housing delivery.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e86117f5c014d1e4678', 'committee_transcript', 'Economy, Energy and Connectivity Committee', '2. General Ministerial Scrutiny: Enterprise, Connectivity and Energy', 'Well, I''m happy to look at that, and I don''t want to provide an answer without my officials looking at objective sources. I think that it''s possible to look at some sources of information, isn''t it, in terms of grid connections, which are not decisions that are within our remit, as it were, but the question of the length of planning decisions is something where there might be comparative data, and we''ll look at that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2e9d82dbbee21788828b', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Okay, thank you.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1554&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.119709', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777244', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2eb1d6bf33c55664ce3f', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you so much. I anticipated that response from you, Cabinet Minister—surprise, surprise. And I appreciate carers do fall under the Deputy Minister''s brief, but I am talking specifically about the programme for government. And, as Cabinet Minister, I''m afraid the buck stops with you on this one.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2ecb075ff26529b642b2', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I''m interested in what works for Wales and it''s about what works for council tax payers, Llywydd, and it''s what works within the bounds of the finances of Welsh Government. And I remind the Senedd that we will be facing a real-terms cut in the day-to-day spending that we have available in the next financial year.
