INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('2f8f3d63a93e644010b4', 'plenary_transcript', 'Plenary', '5. Statement by the Cabinet Minister for Local Government, Housing and Planning: The Revision of the National Development Framework and National Conversation', 'Thank you very much. I do sympathise with your comments. The planning process does take too long. The planning process is complex. The voice of the community isn''t heard sufficiently within the process of the development of local development plans, for example. I could go on and on. You as a local councillor will have come across some of those frustrations when we try and get developments through.
