INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('36636f6c8efe7e86a482', 'plenary_transcript', 'Plenary', '5. Member Debate under Standing Order 11.21(iv): Contaminated land', 'Can I begin by thanking Niamh, with Elwyn''s support, for bringing this important issue to the Chamber today? Some of what I''m going to say may repeat some things that Niamh and Elwyn have said, but that''s because they are important and need to be said more than once.
