INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('36d32ce541b6615e071d', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Excellent, thank you. The programme that the Government has set out seeks additional powers relating to policing, welfare, justice, and further tax-raising powers, but we need to see the economic aspects to this, and then there are arguments on the economic aspects. So, when will you see the basis for these that are powers being sought, which are identified in the programme for government?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=9678&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget; programme for government', 0, '2026-10-02T12:57:52.038886', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774373', NULL, NULL, NULL, NULL);
