INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('385c8a3bc2ed89c308d8', 'oral_question', 'Question not reached in Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '<p>I am pleased to announce that the Welsh Ministers formally agreed the council’s delivery agreement on 29 September, enabling it to commence preparation of a local development plan. My officials look forward to engaging with council officers in due course.</p>', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', '', 'Cabinet Minister for Local Government, Housing and Planning', '', '', '', 'Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', '', NULL, 55.0, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'local development plan', 0, '2026-10-10T14:39:13.894224', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
