INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('40ffbeccbdc3fe347ae6', 'oral_question', 'Oral Question', 'Oral Question - OQ64642', 'What plans does the Government have to build good-quality affordable housing in Bangor Conwy Môn?', 'https://record.senedd.wales/OralQuestion/64642', '2026-09-30', 'Mair Rowlands', '', '5084', '', 'Bangor Conwy Môn', 'Senedd (tabled business)', 'Tabled on 30/09/2026', '', '', NULL, 25.0, 'Low', 'dashboard', 'housing_supply', 'Planning & place', '', '', 'affordable housing', 0, '2026-10-07T06:31:53.562234', 'record_search:type=oral_question:query=housing', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('410ab42262c4c3cb708b', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. So, Hawliau i Gymru is our programme for developing and testing options for strengthening human rights in Wales. It brings together an expert group, therefore a group of people who are legal experts, academics, practitioners. We also have a wider network of stakeholders who have an interest in strengthening human rights in Wales. The work of this group is also to look at lessons from other jurisdictions, to see how other places in the world have approached this. But what I am interested in doing is developing a Welsh model that is ambitious, but that is also practicable.
