INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4354b5e9a0e7aeb724a6', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Oh, yes, on British Sign Language.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4953&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.065641', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771306', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4363792812bf02550414', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Could I ask you to clarify, are you talking about nationality as self-recorded or are you talking about citizenship and UK passport holders, because there is a difference between both?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Dafydd Trystan Davies', 'Cabinet Minister for Government Effectiveness and the Constitution', '12140', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=14581&l=en', NULL, 55.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', '', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.245210', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776899', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4373e859ed1b84119ff5', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Diolch, Chair. That leads on nicely to my question. In terms of the revenue that is raised from the empty homes council tax premiums, do you think that that could or should be ring-fenced specifically for empty properties? And secondly, are there any wider changes to taxation, for example land transaction tax or the way that council tax premiums are structured, that could be looked at to improve bringing empty properties back into use?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=2406&l=en', NULL, 224.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny; named_welsh_legislation', 'Context; Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Land Transaction Tax; Local Government, Housing and Planning Committee; council tax; council tax premiums; empty homes; empty properties; evidence session; inquiry; land transaction tax', 0, '2026-10-07T06:31:25.142464', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775307', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('43c3ee6bdd91069aa4dd', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Thank you so much. It just leaves it for me to say that, obviously, we''re going to invite the Members to ask you some questions over some themes that we''ve been running through all the morning. So, in relation to data, Marc, did you want to lead on this again?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=14511&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.539348', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775453', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('43dd6cf417f0e27c954f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think our experience is, from what we''ve heard from electoral administrators, is that a lot of them are struggling to get even access to council tax data in their authorities at the moment. So, while there are provisions there, as we said earlier, that allow them to have access to that, there are definitely difficulties in getting the relevant other teams in the council to provide the information and to provide it on the frequency of the basis, particularly in those sorts of circumstances, for them to actually have that. I don''t know whether, Sandra, your experiences are—', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Clare Sim', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5357&l=en', NULL, 109.2, 'High', 'digest', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; evidence session', 0, '2026-09-18T11:33:49.406711', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769988', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('43e7a83cd44cf59b8b02', 'consultation', 'Senedd — committee consultation', 'Priorities Consultation: Equality, Human Rights and Social Justice Committee', 'Priorities Consultation: Equality, Human Rights and Social Justice Committee
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('43eb26cf890dbc767702', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Just to add, really, our experience has been quite different to that of Flintshire. Our empty homes grants have been really successful in Bridgend. We''ve approved 81 grants since the scheme was introduced. So, it''s been a massive benefit in terms of having that tool available to us within Bridgend. Whereas, our loans, whilst we have that, we don''t get the appetite for people to take on the loans, and that''s mainly because it takes us so long to get through the process, because we haven''t got the resource to be able to push them through quickly in terms of officer resource and legal resource to do the loan agreements, et cetera. So, again, we''re struggling because we''re lacking on the resource side to push it forward.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Georgina Wayman', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5863&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.619346', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775420', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('440f694a42c73da86a19', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'I think the issue for us—. Thanks for the question. I think that part of that increase in IT costs last year was driven just by inflationary or cost uplifts in licences and IT. That was beyond where we projected them to be. So, about £10,000 of that was in that category. We''ve got a case management system, which is absolutely critical, it sits at the heart of our organisation; it''s how we manage all our case load. What we''re continually doing—and we referred to it earlier—is looking at how we work. We can''t stand still, so how can we be more efficient? How can we change ways of working to try and get through the case load that we''ve got and make it easier for staff to deal with it? And when we do that work, particularly if we change how we handle complaints, then we have to change, the case management system has to change, to accommodate that. It drives our ways of working. So, a lot of the money we invested last year, this increase here, was around those sorts of changes: how we deal with that, how we communicate with our professional advisers.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('442bbc7f917d8644b811', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thank you. That''s helpful. Thank you, Chair.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Iain McIntosh', '', '12170', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=9047&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.941613', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774479', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('443f4eb68b474584fd5f', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'That''s an option. Certainly, I''d be open to considering that. There''s a logistical challenge in terms of getting that money out the door in a timely fashion, because setting up a scheme and administering it isn''t something that you do by pressing a button. But, certainly, I''m happy to consider that. I''m aware as well of calls for a UK-wide emergency scheme, which is something I would really be supportive of, something I would like to see happen. So, there are a few potential elements there. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('444e99356c1509cd19da', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'In the—forgive me if I don''t remember correctly what the defence plan that was announced by—', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elin Jones', '', '162', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=8597&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.868371', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774318', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('44560bd7c77f51efdb7d', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Thank you for the question. Of course, Antoniazzi''s is a well-established business of almost 100 years'' standing. What we will see outlined by the Cabinet Minister for Finance this afternoon will be truly significant. SMEs are the backbone of our economy, and we''ve made it clear, particularly through the Cabinet Minister for Enterprise, Connectivity and Energy, that we are determined to support and grow indigenous Welsh businesses and to ensure that successful businesses continue in Welsh ownership, giving them the confidence to invest in their future. The changes to non-domestic rates will be introduced as soon as possible, from the beginning of next year or the next financial year. They will be permanent, which, again, is a step that gives business confidence. I look forward to hearing the details from the Minister later this afternoon.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=614&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:24.916248', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768973', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4470b8eca03e4afcbb0a', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Well, it''s one of our policy areas that we feel very strongly about, quite clearly. We would like to see a statutory basis for the Sewel convention, in a perfect world. Meantime, a well-worded, strong memorandum of understanding is required, in our view. I have not had discussions, but I know the First Minister has had discussions, and my colleagues had discussions, and it''s something that we are raising even now. There''s a discussion on the memorandum of understanding. It is, as the Member obviously recognises, vitally important. For far too long, it has been mistreated, or, should I say, disrespected, perhaps. It''s something that is core to getting good government, and it''s something that our colleagues in Scotland feel equally strongly about. I''m sure that my colleague can address that, because he''s been in discussion there as well. So, to reassure the Member, there is an ongoing dialogue now about this issue. As I''ve said, we would like to see statutory underpinning, but, meantime, we would be in favour of a strongly worded, fully understood memorandum of understanding that is respected by all.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4017&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.790026', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770460', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('44992e31aeb4037e6e8d', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'There was a lot there. I appreciate it, though, because, as you say, it''s a huge topic. Sera, is there anything you want to pick up in particular on that issue?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=9000&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:37.997058', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777672', NULL, NULL, NULL, NULL);
