INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('44ab2c9392a98a902acd', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'That''s fine.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6806&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.280754', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771257', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('44e2139c5c087bc616b4', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Yes. How are you adapting and investing in translation services and other services that support bilingual business? And what possible impact could an update to the Senedd''s official languages scheme have on your draft budget for 2027-28?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4670&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.630796', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777404', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4503b42b1c4e19e55ace', 'written_statement', 'Welsh Government — Written Statement', 'Written Statement: Consultation on making the “general crisis” provision in the Allocation of Housing and Homelessness (Eligibility) (Wales) (Amendment) Regulations 2026 permanent', 'Written Statement: Consultation on making the “general crisis” provision in the Allocation of Housing and Homelessness (Eligibility) (Wales) (Amendment) Regulations 2026 permanent', 'https://www.gov.wales/written-statement-consultation-making-general-crisis-provision-allocation-housing-and-homelessness?utm_source=rss-announcements&utm_medium=rss-feed&utm_campaign=announcements-Written+Statement%3A+Consultation+on+making+the+%E2%80%9Cgeneral+crisis%E2%80%9D+provision+in+the+Allocation+of+Housing+and+Homelessness+%28Eligibility%29+%28Wales%29+%28Amendment%29+Regulations+2026+permanent', '2026-09-28', '', '', '', '', '', 'Welsh Government', '', '', '', NULL, 88.0, 'High', 'digest', 'homelessness', 'Housing system', 'Sector bodies', 'Consultation open', 'consultation; homelessness', 0, '2026-09-28T14:21:47.444159', 'https://www.gov.wales/announcements/rss', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('45109db5eab4e178974b', 'committee_transcript', 'Early Years, Children, Young People and Education Committee', '2. Welsh Government Scrutiny Session', 'I gave you some leeway there, but no problem. Thank you very much for those opening remarks. It is of assistance to us in terms of setting the context, so I appreciate you doing that. I''ll take the first question. What I would like to mention is that we have allocated our questions into themes, but clearly those themes overlap at times. So, if you see that we are perhaps straying from one theme to another in an agile manner, that''s the purpose of this morning''s discussion, to be very agile in our questioning.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('455bfdaa413b411135ce', 'research', 'Senedd Research', 'The cost of living: Ongoing pressures and recent developments', 'The cost of living: Ongoing pressures and recent developments
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('455c1685e0b1457375cf', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'As the former Chair of the Finance Committee, I reflect on what we were told by former finance Ministers about the fiscal position of the previous Government. I''ve also been following what the new finance Minister has had to say in her analysis of her inherited tight fiscal position, once the actual line-by-line detail has been seen. It also appears that things have got even tighter in recent months as a result of events out of this Government''s control. Nevertheless, it''s good to see that Plaid Cymru''s manifesto commitments are being delivered in this legislative programme this afternoon. I firmly believe that these commitments are for the benefit of the people and communities that we all represent—for example, the community right to buy.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('455e442500fd3f39533f', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Can I just unpack that slightly? Following what Adrian is suggesting and the conversation there, where does this committee—? Well, this is the Legislation Committee, so we would have no role, necessarily, in the scrutiny of that, but for the Senedd as a whole, how does the scrutiny of that decision making and making sure—? Obviously, if legislation is in front of us, we can scrutinise that legislation; if it''s done through other mechanisms, do we need to look at how that scrutiny element is done?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5170&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.027089', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770532', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('459345f6c1a295429013', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, and, of course, the global impacts we can''t do anything about. The Strait of Hormuz and all that will have an effect, and it just underlines, I think, the need for us to be as self-sufficient and resilient as possible, and that goes for meat and horticulture as well. We''re woefully underproducing in that space, and both of those are particular areas that have been identified as priority workstreams for the food strategy.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2489&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.653438', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772039', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('45bca3f736c27a74d1c8', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'A couple of questions, one on Sewel. I wonder if you could give us any detail you can on discussions that you may have had with UK Government on the Sewel convention. Perhaps you could, in answering that, give us an indication of what progress has been made around agreeing a memorandum of understanding on the Sewel convention.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peter Fox', '', '4787', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3991&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.784362', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770458', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('45e64904141ff44145b7', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Dirprwy Lywydd, I''d like to thank the Member for that line of questioning. Now, the programme for government is an excellent piece of work—many here would agree. But the job of the programme for government isn''t to set out the absolute detail of every piece of legislation or every part of work that we''ll be doing; it''s to set the direction. And the same applies to the announcements that we as Ministers have made. Now, this question lies in the portfolio of my colleague the Deputy Minister. She has set out the priorities that she has in her portfolio, and she did mention and talk about the importance of unpaid carers. In fact, a lot of what we''ve been doing with unpaid carers is based on the brilliant report by the health committee—health and care committee, I should say—in the last Senedd, of which I was a member. And we are now actively working on those recommendations in order to ensure that unpaid carers here have the dignity and respect that they deserve. But I would suggest that you raise it with my Deputy Minister in order to push the agenda forward on this.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16314', 'http://www.senedd.tv/en/16314?startPos=3506&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-10-10T14:39:12.346458', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776646', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('45f00aaf77b72bef7cca', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Okay, I''m sure you will.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1933&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.546819', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772015', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('45fba01c7800aac1d460', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Okay. Diolch yn fawr iawn, Cabinet Minister, and to your team as well. I can''t see anybody else wanting to ask any more questions, so thank you for your time, and we''ll see you again here soon, no doubt. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('460616078689b761d63a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'And then, if I can, Chair, lastly from me. What''s really struck me today is the barriers to accessing data sets, even within one''s own local authority. So, how do you best see that being tackled?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5870&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.499970', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769965', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46065d2cfeb9d2843e95', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes, we''re in the process of developing the timetable, as the Cabinet Minister has outlined. There are lots of different parts to developing a timetable, I''m sure you''ll appreciate. A big part of thinking is ensuring that proper scrutiny time is factored into those timetables, as well, and ensuring that committees don''t become swamped, for example, with particular pieces of legislation. So, it''s a bit of a 3D jigsaw puzzle, but we''re working on that at the moment, and I''m sure, as it firms up, we''ll be able to provide more information. As the Cabinet Minister says, we expect that a tax Bill will likely be one of the first runners. At the moment, nothing is absolutely finalised through the autumn term, but, once things do firm up, I''m sure we''ll be able to share more.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Sophie Brighouse', '', '', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=332&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.092416', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770363', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46279214c93c92d11f6a', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'Item 8, legislative consent motion, Steel Industry (Nationalisation) Bill. I call on the Cabinet Minister for Enterprise, Connectivity and Energy to move the motion—Adam Price.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', '16085', 'http://www.senedd.tv/en/16085?startPos=20135&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'Legislative Consent Motion', 0, '2026-08-04T14:03:10.217391', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767871', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('463936ad670504ba6022', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I think that''s a good question. Are we in a position to answer that today? I''m not sure. Of the six key points of Noble, we''re working through each of those. I was pondering to myself whether the most appropriate thing for us to do would be, in 12 months, to update the committee on the progress on each of those. Some of them are clearer than others in terms of how you might demonstrate and measure success.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3226&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.640493', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770415', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4669e1978ea041d56450', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Rural Resilience and Sustainability', 'Minister, Wales needs both renewable energy and secure domestic food production. Welsh planning policy already gives considerable weight to protecting our best and most versatile agricultural land. Can you explain how the protection works alongside the Government''s drive for renewable energy, so that we increase green generation without unnecessarily losing our most productive farmland?', 'https://record.senedd.wales/Plenary/16265', '2026-09-30', 'Lyn Ackerman', '', '4967', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Rural Resilience and Sustainability', '16265', 'http://www.senedd.tv/en/16265?startPos=3155&l=en', NULL, 27.5, 'Low', 'dashboard', 'planning_system', 'Planning & place', '', '', 'planning policy', 0, '2026-10-03T13:38:48.094899', 'https://record.senedd.wales/XMLExport/Download?meetingID=16265&xmlDownloadType=EnglishTranscript#773572', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4673d3c1cc800e15a00e', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Danbert House, which is a very big building in Morriston and which has been derelict for about 20 years, the council have only taken it on every time they''ve had to do safety work and, having done the safety work, they can then sell it in order to recoup the cost. It''s then sold to somebody else and ''please repeat'' several times. And sometimes when they go against the owner, the ownership transfers to the British Virgin Islands or somewhere like that, which makes it, as far as I can see, very difficult, but you may think it''s easier.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=3188&l=en', NULL, 184.0, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.259356', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775324', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('467ec023cf3e7afeb15a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Housing associations are exempted but local authorities aren''t at the moment. So, even if they''re buying back former council properties, at the moment, they have to pay land transaction tax.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17108&l=en', NULL, 207.0, 'Critical', 'immediate', 'taxation_of_property; social_housing; committee_scrutiny; named_welsh_legislation', 'Context; Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Land Transaction Tax; Local Government, Housing and Planning Committee; empty properties; evidence session; housing associations; inquiry; land transaction tax', 0, '2026-10-07T06:31:26.989676', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775526', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46840275e398e6772eaa', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', 'Presiding Officer, I understand that you have given your permission for questions 5 and 9 to be grouped.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4686a26c970604bceb79', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Coming back to the temporary office, has there been any consideration of taking advantage of the Welsh Government estate or somewhere else? I get that they''re different institutions, but, ultimately, the stakeholders are the same, which is the taxpayer. I''m sure they''d appreciate knowing that you guys have been working together to see if there''s some space available. I''m sure there is space available, given there''s been a revolution in working from home.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Cai Parry-Jones', '', '12174', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2985&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.376879', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777369', NULL, NULL, NULL, NULL);
