INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46ca80b4541bd27cd4be', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'Thank you for those comments.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=9317&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:19.807919', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#770983', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46d003b2b0220930abd6', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. We''ll move on to poverty more widely and the cost of living. Steve Bayliss.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1265&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.697122', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771157', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46d07c87a2ab6ec40137', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Welcome. Thank you very much. And it just leaves me now to invite the Members to ask any questions of the Minister. So, we''ll start off, and we''ve got some subject headers. So, regarding the timing for introduction of automatic voter registration, Francesca O''Brien.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=7846&l=en', NULL, 132.2, 'Critical', 'immediate', 'committee_scrutiny', 'Housing system', 'Housing minister; Opposition housing leads; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.822589', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774404', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46ec0465c4cef7c49494', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Thank you, Helen. I''m going to just quickly say we really are up against the clock this morning with everything. So, as Marc has already said, this is a very important subject, so I think what I''m going to suggest is that, for everybody that wants to ask a question now, if you could just make a written note of it and we will submit it to the panel; I''m sure they''ll accommodate us with a suitable response. And then we can move through it that way. It''s just that we''ve got so many questions and so many contributors today that I''m just mindful that everybody gets a fair shout.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46f6c6e949a4b9b02f39', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Can I just come in on a quick point on compulsory purchase orders as well? Looking to Scotland as an example, they''ve recently reformed the compulsory purchase order process, because they also recognised that it was not working for the majority of people and was very expensive. So, they''ve reformed that and hopefully made it more simple for people. But what they''ve also done is added a clause around working in partnership with community groups and housing associations, as well, to make it easier to bring those properties back into use. So, it doesn''t all lie with the council having to bring those properties back into use, but they''re able to work in partnership with these new compulsory purchase orders. So, it was just worth a reference to that work that''s being done in Scotland.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Casey Edwards', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16555&l=en', NULL, 195.5, 'Critical', 'immediate', 'taxation_of_property; social_housing; local_government_enforcement; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; compulsory purchase; empty properties; evidence session; housing associations; inquiry', 0, '2026-10-07T06:31:26.889353', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775547', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4732361805504d1c66fd', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'No.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1429&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.901281', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769878', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47380e5c1a3d30457653', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'On this point here, on the school complaints, with the governing body effectiveness piece of work taking place, do you have a formal position—? Do you sit around a table formally with the Welsh Government as part of that work, or not? Are you just feeding in as and when they request?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=9022&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.007901', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777678', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('476367ee289d7b1ade6b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you for the question. We are supporting households across Pontypridd Cynon Merthyr to improve their home''s performance in terms of energy, to improve living standards, to tackle fuel poverty and to reduce carbon emissions. I have allocated £17 million of additional in-year funding to boost delivery of this across Wales, including an investment of at least £1.6 million in your constituency.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=5632&l=en', NULL, 71.5, 'Medium', 'digest', 'energy_efficiency', 'Property & energy', 'Housing minister', '', 'fuel poverty', 0, '2026-10-10T14:39:12.523545', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776688', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47682430fbace53c5d37', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'Reform believes Britain must do everything it can to retain the ability to make its own steel. Our MPs supported this Bill in Westminster, and today we will support it in the Senedd. But, we have to be very clear, this Bill comes far too late. The workers and their families at Port Talbot know that better than anyone. For years, they were promised certainty, instead they got delay. They were promised a plan and, despite the £1.25 billion transition programme, including up to £500 million of taxpayer support, many workers are still asking what replaces the secure skilled jobs that have been lost. Instead of those jobs, they got managed decline. Thanks to praying at the altar of net zero, we all now know that economic decline comes hand in hand with net zero. The blast furnaces have gone, thousands of livelihoods have been affected, and Britain has become more dependent on imported steel as a result.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('479a4ca6d98db0ac751f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'No, it''s just—[ Inaudible .]—land transaction taxes, council tax. There''s nothing more to add.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Trystan Jones', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17172&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:27.000937', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775561', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47c528f7637745ea6ffa', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'I accept that there is a higher ask of those businesses across the business rates portfolio that have the higher rateable values. The bit you didn''t mention in your question was those up to 20,000 businesses that will benefit from lower taxes as a result of the announcement yesterday and the support for retail premises as well. I think the premise of your question is, though, that this is not just about how we allocate the public funding that''s available to us, but how we also use our taxation system to ensure, yes, that we''re using it to fund public services, because taxation is what enables public services to be run, but also how we get that balance right in terms of supporting our economy. All of those together, again, are part of the considerations when we need to think about where we strike this balance.', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Elin Jones', '', '162', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=3992&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-19T12:39:17.053404', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769547', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47d7bcb2385a0a821fc0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Thank you, Chair.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=4955&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.342536', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769944', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47e4c1b22b6bff68cd5d', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'The fact that I''m now a Minister in Government doesn''t change my values at all. I continue to be a campaigner as well as a Minister in the Welsh Government, and I''m sure that other members of the Cabinet agree with that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47f91319415d55a6d218', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Also on the new staff and the 75 positions, is it possible for you to provide us with a breakdown, by function and pay range, and identify the specific additional workload that justifies each post?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Cai Parry-Jones', '', '12174', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1555&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.121176', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777245', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('48241ea934d1e62da985', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thank you, Minister. I have a question about multi-year planning. In the draft budget, as well as funding for 2027-28, are you also providing indicative funding allocations for future years?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sera Evans', '', '330', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=7043&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.608991', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774358', NULL, NULL, NULL, NULL);
