INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('484d8ada88abb2f7b82b', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'And something we forget about when we''re talking about community-led housing is that in the 1970s, a lot of our smaller housing associations started in that way, so we kind of talk about it as this new grass-roots thing, but that philanthropic community kind of action is where a lot of our housing associations—. They''re stock transfers—that''s where they started. So, it''s not new. I''m a great advocate of looking at what we''ve already achieved.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16873&l=en', NULL, 172.5, 'Critical', 'immediate', 'taxation_of_property; social_housing; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; housing associations; inquiry', 0, '2026-10-07T06:31:26.943080', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775579', NULL, NULL, NULL, NULL);
