INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4d463030a28293caa72a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'I was going to say, finally from me, that one of the problems is that some of them are empty because of battles over probate, battles over wills, the fact that, even when probate is granted, people want to go to court to say that the will is not fair and that they hadn''t done what they expected. Is there anybody in this room who has not come across that? The other one that we get continually is, ''It''s a family home; I don''t want to lose it.''', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=1565&l=en', NULL, 184.0, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.003980', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775343', NULL, NULL, NULL, NULL);
