INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('550021a345bd85f15f05', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'The evidence seems to show that you are, doesn''t it?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=1874&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.087121', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774220', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('5501d0ab0435ab45d27e', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thank you. So, I wanted to start on the eight weeks that the guidance advises local authorities to allow a minimum of. To what extent do you think that eight-week period is adequate in terms of the work required to cleanse and standardise and prepare those data sets? Do you expect that process to become quicker in subsequent years as a result of the work happening in the first round of automatic voter registration? And in addition to that, do you think that we can retain the benefits of that first cleanse going forward, so that the work should become less as we progress?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2128&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.017051', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769845', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('5502a40170d766cd2804', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'There are swings and roundabouts there. We''re very mindful of the pressure on public sector funding. We don''t come here without really strong consideration to ask for any uplifts. I think we have got a bit of a windfall this year, to be honest, from that pension contribution. Others will have that as well in certain parts of the public sector. What we''re saying is that we want to use that to invest in things that will help us in the future, and, hopefully, keep our uplifts in the future that we''re coming to committee to talk about more modest.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Michelle Morris', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=11684&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.404706', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777661', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('55149dd652f5ffa864ec', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Thank you. Manon Bonner, clerk and chief executive of the Commission.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Manon Bonner', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=76&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.897159', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777342', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('55459e911a0e61a1bbdc', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Okay, thanks. Anything else, Ben?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3839&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.486576', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777415', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('554c45ceab2e9cefea95', 'plenary_transcript', 'Plenary', '1. Questions to the Trefnydd, Chief Whip and Cabinet Minister for Culture and Sport', 'I''m grateful for that response. Of course, at the other end of the spectrum, it''s vital that the Welsh Government is building a pipeline of sporting talent, and that, of course, means investing in sports facilities across the country. The financial challenges facing the sports sector are well known, and if the Welsh Government is serious about creating legacies from major sporting events, then the sector will need more funding. Your party''s own manifesto commits to increasing funding for culture and sport year on year throughout this Senedd term. So, Cabinet Minister, can you provide a guarantee to the culture and sports sector that they will receive a real-terms increase in the upcoming draft budget and every other year under this Government? Can you also provide an update on your audit of community and regional sporting facilities, so that we can better understand where capital investment needs to be targeted going forward?', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Paul Davies', '', '145', '', '', 'Plenary', '1. Questions to the Trefnydd, Chief Whip and Cabinet Minister for Culture and Sport', '16261', 'http://www.senedd.tv/en/16261?startPos=1320&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'draft budget', 0, '2026-09-19T12:39:16.674340', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769453', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('5577bbba1fe7716d6f48', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Joe Martin', '', '12146', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2022&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.780348', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771228', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('558627a5bc67c96ac511', 'committee_transcript', 'Economy, Energy and Connectivity Committee', '2. General Ministerial Scrutiny: Transport', 'We''ve actually remitted TfW recently on reopening the consideration of a fast bus link from Cardiff Central to Cardiff Airport. I don''t have the conclusion on that, but, obviously, we can feed back. But really, it''s just about that connectivity and having a—. The programme for government commitment is on a fully integrated transport system, so we need to look at all options to get people quicker from the middle of the city and out, and also as you''re coming down the M4 and how those links work. So, that''s an addition to the local services. So, I think that''s one we''d like to come back to you on once that review concludes.', 'https://record.senedd.wales/Committee/16288', '2026-10-07', 'Duncan Hamer', '', '', '', '', 'Economy, Energy and Connectivity Committee', '2. General Ministerial Scrutiny: Transport', '16288', 'http://www.senedd.tv/en/16288?startPos=5438&l=en', NULL, 17.2, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-10-08T13:49:57.970104', 'https://record.senedd.wales/XMLExport/Download?meetingID=16288&xmlDownloadType=EnglishTranscript#777146', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('5595164aaa9efc3758b6', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I think, in the way it''s presented, it seems like less of an increase being requested from £102 million to £109 million. The reality is there''s £4.5 million, which is very unusual and is outside of your control. So, really, what''s been asked for is a £98 million increase up to £109 million in terms of things that are within your control.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=334&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.941397', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777346', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('559b6baa09a3c4c5c533', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Just picking up on what Sera was saying there a minute ago about the growth in costs for Bay 32, which I guess are partly related to the decant, by 2029-30, between the Bay 32 lines and the depreciation, you''re up to about £30 million. Is that the peak, and does it fall off—are you expecting it to fall off after that? I appreciate this is not the go/no-go on Bay 32, but what''s the profile for the Commission budget going to look like beyond the three years?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2580&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.315333', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777305', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('55d29cc4f7adda0499a5', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Thank you, Chair. Good morning, Minister. I''ve just got some concerns on the timing of the introduction. I know that has been picked up in some of the reports, but, obviously, we''ve got the Gould convention, which states that it shouldn''t be longer than—. You''ve got that six-month buffer. I appreciate we''re now at 1 October. So, it''s just flagging that as a concern on the time for implementation, and the reasons why we might be pushing up against that deadline. I don''t know, maybe you want to pick up on that first, and I can come back then on the Gould convention.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Francesca O''Brien', '', '12190', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=7860&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; Opposition housing leads', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.828031', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774412', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('55db5b18116539273965', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. Really important work in terms of bringing investment into ecosystem services and being able to leverage that in. We''re undertaking work at the moment on a consultation to be able to bring that forward and intend to publish that consultation shortly, in the autumn.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Rhodri Asby', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3065&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Consultation open', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; consultation', 0, '2026-09-25T06:30:34.744048', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771903', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('55f03063606e956dbbd9', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Sarah''s going to pick that one up.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Michelle Morris', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=11808&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.426089', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777723', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('55fd4c96d65e1b886df0', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''ll ask officials to come in on that. What I would say, though, is that rewetting and peatlands is a longer term project; it isn''t necessarily going to help us next summer. So, we need to be mindful that we need the more immediate interventions that we can absolutely put in place to mitigate risk for the coming year—well, I say the coming year, but, crikey, it could be February or March, couldn''t it, depending on the weather and circumstances. But is there anything in particular we can add on that?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1030&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.417156', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771743', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('562541abc74580cc571c', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Ultimately, executive remuneration is a matter for the remuneration committees of company boards, Glas Cymru in Dŵr Cymru''s case, for example. Since 2025, Ofwat has had the powers to prevent the payment of bonuses that are unjustified by company performance, financially and operationally. Since then, we''ve banned over £4 million of unwarranted bonuses. You will have seen, despite that, that other payments have been made. Yesterday, we heard in the Prime Minister''s speech at the Labour Party conference an intention to include in the forthcoming clean water Bill a provision to tighten those restrictions even further. So far, we can only work within the restrictions that we have, the rules that we have. We wrote to companies earlier this year to remind them of our very strong expectation that they would stick to not just the letter of the law, but the spirit of the law. But you will have seen reports since then that I think resulted in the comments that we heard yesterday from the Prime Minister about tightening, as it was put yesterday, those loopholes.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3385&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.185704', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773293', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('564f1e7ed63c7a9c10d9', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. Cabinet Minister, I have three questions, but I want to make a few comments before coming to my questions. I''m sure that you would agree that the third sector is a very important one, a professional sector that is important to the preventative agenda. I have over 20 years of experience of working in this sector. I would like to draw attention to a piece in the evidence pack, page 17, on the voluntary sector—unfortunately, it''s the English copy that I brought down with me. I''ll just read out the first paragraph. This sector is', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Elfed Williams', '', '12165', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6896&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.297820', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771270', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('568d67a34b7fa3b40052', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I think members of the public would be surprised, really, that that type of scrutiny wasn''t embedded for a long time. The fact that it is there now, I''m sure that our audience of thousands who are watching would not like that to be something that would be lost.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('568dda563b61eeb9a0a1', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'So, before I bring Niamh in—and I know John wants to speak—just so that I can be absolutely clear, and it''s on the public record: whatever that committee, that TAG recommends, the Government won''t have sight of it first to alter it or change it. What scientific evidence is provided will be what''s provided, and it won''t be, shall we say, Government-proofed before it''s released to the public.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6224&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.132597', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772106', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('569dc594a4da7f79b139', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Well, I think that''s the magic formula, isn''t it? If we crack that one, then I think we''re sort of halfway there, at least. But I''m just thinking, for example, of water management. There are catchment-based partnerships out there that bring a lot of these players together. The Welsh Government is investing tens of millions of pounds in flood mitigation schemes in this financial year. But we also have water companies that have a role to play. We have Natural Resources Wales that have a big part to play. We have landowners themselves that have a big part to play, bringing those communities in so that we can make sure that you maximise investment when you bring that investment together. They could all do their individual things, which would be all well and good, very laudable, but when you bring partners together on that catchment scale, I think you can do so much more, utilising probably the same resources but in a more joined-up way. So, there is more that we can do, and, yes, I''m all ears if you have any particular ideas, but nature finance is a big part of that as well. But those people on the ground need to be empowered as well to make decisions.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3509&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.815788', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771891', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('56a582d18c2d5099a92a', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', 'As I''ve already spoken on in this Chamber, councils are in real financial distress. We are seeing massive increases in council tax, growing debt bubbles and serious service cuts. This is why the Government''s plan to review the funding formula is so important. However, as with everything, Minister, detail is key. Strong words and bold promises aren''t enough. So, with local government on tenterhooks waiting for this review, can you tell us how you intend to review the formula? What components are you looking to change and, most importantly, how will the Welsh Government define success when it''s reviewing the formula? What does a successful review look like to the Welsh Government? Minister, this place and, most importantly, local government need answers.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Tom Montgomery', '', '12183', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', '16085', 'http://www.senedd.tv/en/16085?startPos=6085&l=en', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'council tax', 0, '2026-08-04T14:03:08.748244', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767661', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('56ddf1a8ddef16bbd25e', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Thank you.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Anna Nicholl', '', '12178', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=1689&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.940787', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773165', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('56f34c6f8bd0e0fb26be', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Well, we have to publish it by the end of the year, so there will be a statement around that time. It''ll be before Christmas, I suppose, to be general. This is what Ministers say usually, isn''t it? Which Christmas I didn’t say. [ Laughter .]', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4390&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.861017', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771850', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('57597bc06869c5a4cec8', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'And do you think a significant element of that is the culture within the organisation? I guess the first point of complaint could be with somebody right at the front line and if they feel empowered to handle that and deal with it appropriately, then there''s a significant resource saving to the organisation and to the complainant themselves in getting it dealt with very quickly. But is that a cultural thing in some organisations perhaps, where complaints aren''t dealt with as close to the front line as possible? And is there a piece of work that you''re able to highlight to show that if there''s more focus culturally within organisations to empower their staff to deal with complaints early on, actually, it has a significant knock-on effect elsewhere?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=7339&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:37.751480', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777585', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('576075d0cc2196a093a4', 'plenary_transcript', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', 'Thank you very much to the former Minister, or Cabinet Secretary, who was responsible for steering, very agilely, the Bill that is now an Act during the last Senedd, and I was very pleased to work together with you. And, yes, as you remind us, it was the first time for this Senedd to operate in that entirely inclusive, collaborative way and to pass that legislation unanimously. It is my intention to try and work in that same way with everyone in this Chamber.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('576176896f16d24179fe', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I''m going to ask this in English, if that''s okay.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Huw Thomas', '', '12156', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=2134&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.430081', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770384', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('57e17a25de8c9088bdef', 'oral_question', 'Question not reached in Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '<p>The new changes to the energy efficiency requirements of the building regulations in Wales will come into force in March 2027. These will mandate requirements for low-carbon heating systems, such as heat pumps or heat networks, and renewable electricity generation, such as solar panels, in all newly built dwellings.</p>', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', '', 'Cabinet Minister for Local Government, Housing and Planning', '', '', '', 'Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 65.0, 'Medium', 'digest', 'energy_efficiency', 'Property & energy', 'Housing minister', '', 'heat pumps', 0, '2026-08-04T14:03:06.994042', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
