INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('5938c8eabb1bc7670eda', 'oral_question', 'Question not reached in Plenary', 'Questions to the Deputy First Minister and Cabinet Minister for Social Justice and Equality', '<p>I recognise that any child living in temporary accommodation is a serious concern. That is why this Government is taking action to prevent homelessness, reduce dependence on temporary accommodation and implement the Homelessness and Social Housing Allocation (Wales) Act 2026, with children''s rights and well-being at its core.</p>', 'https://record.senedd.wales/Plenary/16265', '2026-09-30', '', 'Deputy First Minister and Cabinet Minister for Social Justice and Equality', '', '', '', 'Plenary', 'Questions to the Deputy First Minister and Cabinet Minister for Social Justice and Equality', '16265', '', NULL, 90.0, 'High', 'digest', 'homelessness; social_housing; named_welsh_legislation', 'Context; Housing system', 'First Minister / Cabinet', '', 'Homelessness and Social Housing Allocation; Homelessness and Social Housing Allocation (Wales) Act; homelessness; social housing; temporary accommodation', 0, '2026-10-01T13:39:20.014989', 'https://record.senedd.wales/XMLExport/Download?meetingID=16265&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('5947121540b9cb458d4f', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch. I''ve got Sarah and then Laura.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=777&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.640822', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771205', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('594938d4f5facce7e3b2', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'I rise today to address yet another example of Welsh Government introducing policy without fully understanding the consequences. I refer to the 182-day occupancy requirement for self-catering accommodation providers. The policy was supposed to help tackle housing pressures and the impact of second homes. Instead, it is placing genuine tourism businesses under increasing strain, particularly in Ceredigion Penfro. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('5959cae2ed6e0a6168e1', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Sorry, may I add to that? Just in terms of funding, I think there''s uncertainty in terms of how long the funding will last for. With the empty homes grant and, particularly, Leasing Scheme Wales, both of which we''ve found beneficial in shared regulatory services, in particular in Bridgend, we''re at this point now with Leasing Scheme Wales where we''re having to turn properties away, because the certainty as to whether there''s future funding is unknown. So, I think that anything that can be done to ensure we''ve got sustainability, I guess, with funding would be really welcomed, because, without the tools like funding, it makes our jobs really difficult to get properties back into use.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('59afb6d3bff3a7cf8327', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Yes, thank you. Sorry, I''m going to go back to the question about working with RSLs and local partner agencies. What we have found here in Caerphilly, where we''ve enforced the sale of a property, it was within our enforced sale strategy to, firstly, offer those properties to RSLs. But, on occasion, unfortunately, there has been no appetite to purchase those properties, which could be for many reasons: (1), being able to bring that property up to standard; (2), being away from their other local housing stock; (3), probably because it''s not financially viable to then purchase that property at fair value, spend the money, obviously, to get it up to that standard, to make it a worthwhile project for them. So, maybe something could be done, which would be welcomed, in assisting those RSLs in bringing back those properties that may be problematic or difficult for them to bring back into use otherwise.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'James Wagenaar', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6819&l=en', NULL, 172.5, 'Critical', 'immediate', 'taxation_of_property; social_housing; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; RSLs; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.765022', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775487', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('59efa414e676099aa7d2', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'But does the First Minister agree with me that the Plaid Cymru Government’s commitment to adjust business rates in favour of our independent small businesses will give them the confidence to grow and invest, breathing new life into our town centres in the process?', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Mair Rowlands', '', '5084', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=600&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-16T11:53:07.101073', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768970', NULL, NULL, NULL, NULL);
