INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('62149b69206dc7a37a56', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Looking at the experiences of this Senedd so far and the impact of Business Committee decisions, you''ve stated that there are further staff and non-staff costs in regard to decisions regarding Senedd business—changes to Plenary and things like that—and that those will only be allocated when the need is evidenced. Can you explain how that decision is made when you decide to make that allocation, and have you mapped out any different scenarios so far as to potential changes to business and the associated costs that would come with them?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Benjamin Hodge Mckenna', '', '12142', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3433&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.435415', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777530', NULL, NULL, NULL, NULL);
