INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6223d8735d2205f790bc', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'My mother is Heulwen Roberts from Llangefni. My father—[ Inaudible .]', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'John Clark', '', '12169', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=16199&l=en', NULL, 55.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', '', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.424592', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776981', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('623c256e4de5c81ab151', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'I completely agree with you that vulnerable groups, including women in refuges or women who are worried that they can be recognised from the register by abusive partners—. I absolutely understand that concern. So, there is an ability for people to register anonymously. So, you can register yourself, you can vote, but your name would not be out there in public. That''s been a long-standing ability, but people haven''t really recognised that that is something that they can do. So, we are really eager now to push information out regarding that ability, because the last thing we want to do is create tension, create fear. So, that is a real opportunity within this now to—. So that people can vote. And it''s very important that we don''t disenfranchise people in vulnerable positions from having their vote, because this is what it''s all about, really, making sure that more people have that ability to vote if they wish to. But we don''t want to create any unforeseen circumstances. And for that reason, the anonymity clause is something that we will be writing—. It will be in the letters that go out to people. The initial letter will point out that you can have this anonymity through the new system.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8161&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.870565', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774439', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('623cf5a69f985ee8fba0', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Thank you very much for that answer. It''s good to hear there that the Welsh language is one of your priorities. We have already touched on the need in terms of bilingual working, and my ears pricked up when I heard about Canada earlier—that was very interesting. So, what steps will the Government be taking in the programme to improve accessibility of the law in order to facilitate any use of the Welsh language in particular, then?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Beca Brown', '', '12186', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4457&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.869698', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770545', NULL, NULL, NULL, NULL);
