INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('62e1683ce2a1d00eb753', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you. Swansea Council has been allocated over £38 million in social housing grant funding and £9.5 million through the transitional accommodation capital programme this year alone. Together, this will contribute to the delivery of 541 additional homes across this Senedd term.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=7958&l=en', NULL, 49.5, 'Low', 'dashboard', 'social_housing', 'Housing system', 'Housing minister', '', 'social housing', 0, '2026-10-10T14:39:12.740556', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776772', NULL, NULL, NULL, NULL);
