INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('631f65aace7fff647fbf', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'But if you invest in empty property officers, then you get better records.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Dr Henry Dawson', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=2061&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; empty property; evidence session; inquiry', 0, '2026-10-07T06:31:25.091897', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775346', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('63b957eb61ea1540d92c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Yes, the second part. Thank you, Minister, for that. I noted in the report as well—. Sorry, I''m getting feedback on the headphones. I think the committee wrote out to various stakeholders. In particular, I''m interested in victims of domestic abuse who''ve had to flee their home for those reasons. I''ve noticed that not one representative from that group have responded, for one reason or another. But, again, just a red flag there. Because I don''t want these women, who equally have a really strong voice in our society, who are fleeing terrible circumstances—I don''t want them to miss out because of this new regulation. I don''t want their voices not heard in May''s election next year, Minister. So, what reassurance—? Or is there anything that we can do to make sure that we can capture those women''s voices for May''s elections, which are not long away?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Francesca O''Brien', '', '12190', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8094&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; Opposition housing leads', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.860494', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774427', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('63c602b67d2d49031f43', 'plenary_transcript', 'Plenary', '2. Questions to the First Minister', 'Tackling child poverty and securing the best future for every child in Wales is at the heart of our programme for government. We are creating a new strategy to tackle child poverty. We''re setting clear targets and milestones to drive ambitious, deliverable change. We''re also introducing a new ambitious childcare offer to support families with the cost of living and are developing the Cynnal child payment pilot as part of a suite of measures.', 'https://record.senedd.wales/Plenary/16264', '2026-09-29', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '2. Questions to the First Minister', '16264', 'http://www.senedd.tv/en/16264?startPos=3199&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-10-03T13:38:58.344153', 'https://record.senedd.wales/XMLExport/Download?meetingID=16264&xmlDownloadType=EnglishTranscript#772887', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('63e0903f13ea7b262784', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Diolch yn fawr. Thank you. Elfed.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=9531&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:52.019333', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774619', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('64186631e43b26390daf', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Thank you for all that information, and I''ve taken on board what was said in that last answer. But my biggest gripe is with regard to Welsh Water being, I think, roughly halfway up the UK table in terms of performance—it being a not-for-profit organisation, compared to companies that are nationally lambasted for the amount of capital that''s been taken out each and every year and paid to shareholders. For me, it makes it incredulous that Welsh Water can only be halfway up the table at a not-for-profit situation. Now, for me, that points directly to the quality of the governance, and the biggest problem I have, then, looking at trying to establish what''s happening in Welsh Water, is the fact that, with it not being a Government body, we can''t have freedom of information, and there''s obviously great difficulty in getting the information that''s needed to assess what they''re doing. All I can see, unless somebody else can tell me otherwise, is there are massive cracks in the pavement and that they''re falling down on a continuous basis that aren''t being picked by Ofwat. Now, if you''re going to analyse the performance of them, you need to analyse not necessarily just the outputs of what''s happening and targets, but you need to analyse a lot further in depth. I don''t know whether that is currently being done or whether that will be the case for the next body to do, because, without that, there is no point in doing anything.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'John Davies', '', '4650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=1749&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.951058', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773132', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6430c37cbf470f227cc0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'We had the carrot of grant money, didn''t we, for people who wanted to do work on a house to bring it back into use. We had the stick of having higher rates of council tax able to be charged. And then we had the big stick of compulsory purchase orders. Have the first two worked and have any of you ever used a compulsory purchase order?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4646&l=en', NULL, 207.0, 'Critical', 'immediate', 'taxation_of_property; local_government_enforcement; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; compulsory purchase; council tax; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.414815', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774775', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('64425de00315b978dca4', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I''m Wendy Dearden. I lead on the housing work at the Bevan Foundation. To declare, I''m also a former empty homes officer, so I kind of come with many different hats to this, I feel, today.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=14477&l=en', NULL, 172.5, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Sector bodies', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.528102', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775440', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('646b9b41f2c6bce5a2e3', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'I''m grateful for the question and the sentiment, and I couldn''t agree more. It was very humbling, back in May, to see different communities in their geographical location, in their diversity, turning to Plaid Cymru and putting their trust in us, and we have to repay that trust. That''s what it''s all about. On social justice, I say, ''Hear, hear.'' I hope that speaking loud and clear from this programme for government is the sense that this is about equity, it is about fairness, it is about equal opportunity, it is about social justice. We don''t want the national development agency to be there to make Wales rich for its own sake. We want it there to make us prosper in every sense, where everybody feels a part of a flourishing nation that I know we can be. The measures on education are very much geared to making sure that education opportunities are there for everybody.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6477f86f415dbc966e96', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'On legislation, I always think about how comprehensive education was initially brought in following a Department for Education and Science circular by Anthony Crosland—no legislation. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('648487d6ca241620cae8', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Taking 20 posts out of the establishment, not making them redundant, because we''re managing them through fixed-term contracts, which we are tapering down as we clear the backlog.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Kevin Thomas', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2018&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.120759', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774231', NULL, NULL, NULL, NULL);
