INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('697075cf0810e7ee66bd', 'plenary_transcript', 'Plenary', '3. Business Statement and Announcement', 'I''m raising this as an MS for Carmarthenshire, but I need to declare that I am also the Chair of the Local Government, Housing and Planning Committee. Trefnydd, can I ask for a statement from the Welsh Government on nutrient neutrality and its impact on housing delivery in west Wales?
