INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6b39ff4c844e4cf459f7', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I''m Mark Squire. I joined Ofwat in February from NRW. My role within Ofwat is to assess the performance of the company, but also to look at the environmental aspects of the PR29 programme—so, building on where we''ve come from the massive investment in PR24, ensuring that that performance and that investment in the environment is correct for Wales and builds on the previous price reviews.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Mark Squire', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=345&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.788802', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773185', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6b4faac11a125820d53b', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Okay, thank you. I''ll bring Sera in to wrap things up. Sera.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=3420&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.423288', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774297', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6b5530431d99673f3409', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Diolch. Minister, most communities in my constituency are already stretched to the limit. It''s already hard to get a GP appointment, seeing an NHS dentist is almost impossible, and schools already have too many children in the classroom without the right support, yet more homes are being approved without the infrastructure there to support them.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6b5b6566cfe371141b58', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Yes, I''m more than happy to come in on this. On the point of data, I think, certainly from an empty homes officers'' point of view, we can only go with what we''ve got or what we have access to. The data that council tax provides gives us 95 per cent to 99 per cent of all the information we need and what we''re looking at. The other 1 per cent is made up from complaints, referrals from councillors, from members, from the public. By simply driving around and going to visit other empty homes, you might see a case that you''d not picked up on before. So, yes, we''d love to have more data, we''d love to have more access to other sources of information and other complaints and referrals of empty homes, but we have to go with what we''ve got, and that data is, essentially, mostly council tax.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6b76cb9f5008a47a6997', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'Thank you, Minister.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Kerry Ferguson', 'Deputy Presiding Officer', '12177', '', '', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', '16260', 'http://www.senedd.tv/en/16260?startPos=11395&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:26.283560', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769237', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6baff26ed07425ffe0fc', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Just to give you some context, when we''re talking about the statute book, it is important to bear in mind that the Senedd has inherited that law. So, when the Senedd was created and when decisions were made on what areas were within the Senedd''s competence, when that happened, to all intents and purposes, the statute book in those areas was transferred to be your responsibility or ours. That is important to consider, because just a handful of Wales-only legislation existed. So, there''s a very different history in Wales compared with Scotland, for example, where there was quite a bit more Scottish legislation that had been passed by the UK Parliament.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6bcce0aa5e3a4a9cc35c', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you. Cabinet Minister, I was delighted to hear your announcement two weeks ago, including the launch of the Wales interim measures alarm grant and your commitment to holding negligent developers to account. Two weeks ago, I met with Swansea Point Owners and Residents Association, an incredibly inspiring Swansea residents association, who are fighting tooth and nail to get justice for those living in fire-unsafe buildings. Holding negligent developers to account is a tough battle. We expect them to delay, defend and deny at every opportunity possible. What makes this tougher again is, from my understanding, an inadequate fire safety legal landscape that we''ve inherited from the previous Labour Government—one full of loopholes, exceptions and edge cases, making it easier for developers to evade justice. Cabinet Minister, would you please state how you''re going to make sure that developers do not evade accountability and that the victims of fire-unsafe buildings get the justice they deserve as soon as possible?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'John Davies', '', '4650', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=5191&l=en', NULL, 71.5, 'Medium', 'digest', 'building_safety_and_leasehold', 'Property & energy', 'Housing minister', '', 'fire safety', 0, '2026-10-10T14:39:12.488647', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776700', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6be15dde8f3283ee293d', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Of course.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15991&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.789593', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775484', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6be9c2d9e8ec377292c8', 'committee_transcript', 'Economy, Energy and Connectivity Committee', '2. General Ministerial Scrutiny: Transport', 'Let''s deal with the first question, about the Railways Bill. We are still in negotiations with the Department for Transport over the Railways Bill and how that best suits the interests of Wales. I think those negotiations can be characterised as being positive and constructive. When I''ve met the rail Minister in the UK, we''ve both left those conversations feeling like we''re making some significant progress. Those conversations have also been attended by the Secretary of State for Wales. The person did change in two of them, as you may be aware, but they were actively supported as well. You''ve got to take things as I see them, and my reflection is that we are dealing with things that are quite complex. As they first stood, I wouldn''t have recommended that the Senedd agree to the legislative consent motion, but we are moving, I think, in a way that will, hopefully, get us to a point where I would like to be able to recommend it. We''re still some way off, but we are moving.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c457c929caa5b56b160', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'My question is that we were told earlier there is no difficulty in enforcing against somebody living in prison: do you find that there''s no problem enforcing against somebody living in prison? Are there any problems enforcing against somebody who lives abroad and where the property is registered in, let''s say, the British Virgin Islands?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6270&l=en', NULL, 184.0, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.683285', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775510', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c48213f7e3aaf578f3e', 'research', 'Senedd Research', 'Air Quality and Public Health', 'Air Quality and Public Health
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c4a38137855c57984cc', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'On that question of the errors, I know that Mr Fox raised this in the committee as well, and he was quite right to do so. It isn''t a good story to tell. There have been errors made in the past, but we should also say that some of the differences relate to individual interpretation. But there were also straight errors. So, all I can say is that I and the team will be looking very, very carefully at things from now on to make sure that things like that don''t happen again. You and Mr Fox are quite right to raise this point. It isn''t good enough, and I don''t think that anyone is going to sit here and say, ''It''s all okay.'' It''s not. There have been errors made in the past. We have to deal with those now and we have to ensure that that doesn''t happen in the future, because, at the end of the day, it affects the reputation of this place as a bilingual Parliament that is boasted about in Canada and a lot of other places, but failing to get consistency isn''t good enough. So, it is an issue that we''re looking at. Each week, going forwards, now, we will be looking at that and making sure, as best we can, that it doesn''t happen to that extent ever again.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4870&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.966977', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770617', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c5646705d3e4b301600', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Okay. Well, in terms of what we''re asking of the committee this year in our estimate, it''s for a cash increase of 2.2 per cent in our budget—£153,000. So, that is, we feel, a modest amount, bearing in mind where inflation is, and also that we''re projecting that the pay increase for next year will actually be 3 per cent.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c65972ac28f1e984507', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'A very quick point in terms of community asset transfer. As to the circumstances you''ve mentioned, about volunteers running these things being quite difficult, I find that the enthusiasm is there at the start but then wanes off when life gets in the way, things get more complicated, processes are drawn out. Is there anything that we can do here in terms of empty properties that can kind of allay that?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=3555&l=en', NULL, 207.0, 'Critical', 'immediate', 'taxation_of_property; social_housing; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; community asset; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.321025', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775332', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c66de8bf250aae9d5cb', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'A year-round tourism economy is something that I definitely want to see, both for the constituency that we both represent, but also for Wales generally. I think we''ve seen significant progress on that over the last few years, but there is more to do still on that. We have our investment priorities, and looking at how we can attract tourists for an extended period of the year is part of the criteria in how we invest in that. Also, we need to make sure that the business rates system that we have, and other taxation aspects, are also ensuring that those businesses that support the hospitality sector are able to be all year round. There''s no point having businesses that are only open for a particular part of the year. We need businesses that are open all year long, so that they can provide the opportunity for tourists to benefit, but also, what benefits tourists also benefits the communities they serve. So, I''m particularly hopeful that the positive sign that the Government was able to give yesterday for such a wide array of businesses that do support the tourism sector, of a 30 per cent reduction in business rates from next April, is a positive sign for the tourism sector generally that this Government backs it.', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Elin Jones', '', '162', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=3662&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-19T12:39:17.011283', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769553', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c9b434855a4f7fc63f8', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'I want to start by celebrating the huge contribution that tourism makes to Wales and my constituency in Ceredigion Penfro. Ceredigion Penfro is one of the most beautiful places in the world, shown by the millions who visit each year. In Ceredigion Penfro, you can travel from sandy beach to rolling hill to ancient woodland—and sometimes find all three in one place. From the only coastal national park in the UK in Pembrokeshire, to the remote wilderness of Ceredigion''s Cambrian mountains. From Tenby to Trefdraeth and from Aberaeron to Arberth, it''s no wonder that people across Wales and around the world want to visit Ceredigion Penfro.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6cfd8297a52c17151ef4', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'So is there a capacity issue on the other side as well as drafting?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=830&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.181467', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770402', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d06b513c5d050f33f2a', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'So, obviously, where you can save time, you can focus your attention on other areas, can''t you?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Adrian Mason', '', '12181', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5125&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.014579', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770513', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d264111375704304db4', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Yes. Are there any other—? Does anybody want to add anything else on additional challenges?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=4218&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.215800', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769931', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d3cbe250aeef6799e5a', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'I think general awareness was up. I think strong awareness was slightly changed. I think it comes back to this: we want people to know our work and so on. Does everybody need to know the public audit body? It''s a question. But as we sit as part of this kind of fabric of trust amongst the Welsh public about public services and the role of public audit within that, I think it is important. It''s certainly something that we''re thinking about. ''Are we as well known in Wales as the National Audit Office is?'' is more generally a question, and ''Do we want that?'' is another question. So, it is something we''re working through, but we are quite conscious of it, and for me, with my auditor general hat on, I think the public having confidence that I''m looking at the things that they care about is important, and how that is reflected is what matters to me.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Catherine Mealing-Jones', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=3473&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.435138', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774313', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d3d8a7e9c2c8c44a823', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Yes, indeed. So, just to add to the context, the Commission was taking decisions around the refurbishment of Tŷ Hywel in advance of the 2026 election in 2023-24, and those works were delivered in 2024-25. So, it was a long way before we were at the point we are now with Bay 32. There was a clear risk in terms of the spend that you''re referring to, but no assumptions could be made about which direction, at that very early point, Bay 32 was going to go. So, the office works were done in 2024-25 to allow the Siambr project to then be delivered in 2025-26. There was careful management of the projects, as we went through. We have now engaged our preferred bidder, which is the current landlord of Tŷ Hywel, and we''re refurbishing Tŷ Hywel as our preferred way forward. There is a major emphasis on reusing materials. We don''t have precise figures, but we are keeping a very close eye on all the investment we''ve made, not just to the Member offices areas. We''re very proud of the maintenance of the asset over time, as we have been responsible fully for that, under the lease, and we have got a very close eye on reusing all the materials and minimising cost, going forward.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Ed Williams', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2901&l=en', NULL, 132.2, 'Critical', 'immediate', 'private_rented_sector; fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system; Private rented sector', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session; landlord', 0, '2026-10-09T13:34:37.365256', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777494', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d4a19710fa254d82778', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Yes, staying in this area, staff composition specifically, over half your employees are female, but only 20 per cent of your senior leadership are female, and likewise I think the board is currently two thirds male. I appreciate, Catherine, with you coming in, you will have changed those leadership figures slightly, but it''s still a significant differential. What''s your assessment of the organisation''s ability to support women to progress through their careers to the very top of the organisation?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2592&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.249878', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774559', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d599bec974ac596c600', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=855&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.813079', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769795', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d76c5de73ada25c0414', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'So, before we look forward a little bit—Chair''s prerogative—a few more little questions. I''m interested, on the KPIs, there''s a particular KPI around social media, which is an interesting thought, and you measure trying to achieve a certain amount of engagement. I guess the problem with social media is that, if you really want to get lots of engagement, you could say something absolutely outrageous and then you would smash that target every year, but I guess that''s not the usual behaviour of auditors. So, I wondered whether you''ve reflected on how, as an organisation, you engage with social media and how helpful or healthy it is from time to time, and whether there''s consideration as to how that might change in the future, as the world of social media changes, and whether—. As I say, I appreciate why you may have put a target in there; you''ve got to measure it somehow and justify why you do things on social media. But, as I say, if you want to hit a target, you can just say something absolutely ridiculous and you''ll hit that target in one day, probably. So, any thoughts, perhaps as a new auditor general, on how that works.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=3202&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.389051', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774578', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d7cb73ae64560a563c1', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Yes, unless—. I think it''s down to the fact that one of our internal audit reports came out as reasonable assurance. That was in relation to financial controls and management. But I really want to emphasise it''s not in relation to any problems with our financial management. What the audit looked at was some issues in relation to our employment contracts, whether they were signed off on the day when somebody started. So, there were a couple of recommendations in that report that we''ve complied with. But we aim to have substantial assurance on all our internal audit, which probably sets the bar quite high for us, but is right, I think. But absolutely, our accounts were unqualified.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Katrin Shaw', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=10191&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.188981', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777645', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d8d0dfbe9733bdfe6ab', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'No, if they''ve got dual nationality—.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Francesca O''Brien', '', '12190', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=14803&l=en', NULL, 82.5, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', 'Opposition housing leads', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.278524', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776924', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6dc8c5bc6204c847fb4c', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'No, it''s not—', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4868&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.941078', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771791', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6dc9c161aa76cf4d1e42', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'We can get those details back to the committee, though, yes?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2575&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.307907', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777296', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6dfc970ccbf082d733d8', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Okay, thank you. So, a significant part of your report is in relation to key performance indicators, the KPIs; I know colleagues have some questions around those. Elfed, do you want to come in first on that?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=323&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.758726', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774351', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6e06da575013fb67969b', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Yes, it is a concern to us. Obviously, we want to have higher satisfaction levels than that. I think the first thing to say is that we''ve talked about case load and the pressures there are. We had just over 4,500 complaints last year. We don''t investigate and take forward every complaint—we couldn''t. But, actually, it''s not proportionate to take forward every complaint; it wouldn''t be a good use of public money. So, we focus on those complaints where we see the most serious personal harm and injustice. That means some people don''t get their complaints taken forward, and, clearly, they''re dissatisfied with that. When we investigate complaints then, we do that independently and impartially. We will not always agree with the complaint and we will not always uphold their complaint. We might say, ''Actually, this public body''s done a good job of this complaint—we don''t see that we can add anything further to this.'' Those people will be dissatisfied. So, I suppose what I''m trying to say is it''s inevitable in our line of work that some people, sadly, will remain dissatisfied, because we have to keep on that independent and impartial line.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6e0d8b953787529881e4', 'written_statement', 'Welsh Government — Oral Statement', 'Oral Statement: Rebalancing the non-domestic rates system', 'Oral Statement: Rebalancing the non-domestic rates system', 'https://www.gov.wales/oral-statement-rebalancing-non-domestic-rates-system?utm_source=rss-announcements&utm_medium=rss-feed&utm_campaign=announcements-Oral+Statement%3A+Rebalancing+the+non-domestic+rates+system', '2026-09-16', '', '', '', '', '', 'Welsh Government', '', '', '', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'non-domestic rates', 0, '2026-09-16T11:57:17.835264', 'https://www.gov.wales/announcements/rss', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6e41cd48405233e11172', 'committee_transcript', 'Culture, Communications, Cymraeg and Sport Committee', '2. Ministerial scrutiny session: Cabinet Minister for Education and the Welsh Language', 'Thank you very much. I want to start with an opening question and then I''ll invite Members to follow. The programme for government published last week states that the Government''s commitment to a thriving language underpins everything that you do. How will we assess whether you''ve achieved that ambition by the end of the Senedd term?', 'https://record.senedd.wales/Committee/16239', '2026-09-28', 'Lis McLean', '', '12149', '', '', 'Culture, Communications, Cymraeg and Sport Committee', '2. Ministerial scrutiny session: Cabinet Minister for Education and the Welsh Language', '16239', 'http://www.senedd.tv/en/16239?startPos=662&l=en', NULL, 17.2, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-09-29T13:11:13.864099', 'https://record.senedd.wales/XMLExport/Download?meetingID=16239&xmlDownloadType=EnglishTranscript#772305', NULL, NULL, NULL, NULL);
