INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('711dfdf04c198d45f56a', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you so much, Deputy Presiding Officer. Minister, I listened to your response to the Reform Member, and before I go into my questioning, if you want to divert your attention for surgical hubs to the Royal Gwent in Newport, you will not hear any complaints from me.
