INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7583d718346e1c9210ac', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Sorry, I missed the last part of your question.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4341&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.994483', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771297', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('758d7a66e92dd4f191ed', 'committee_transcript', 'Legislation Committee', '1. Motion to elect a temporary Chair under Standing Order 17.22 for this meeting', 'May I propose Peredur Owen Griffiths, please?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Huw Thomas', '', '12156', '', '', 'Legislation Committee', '1. Motion to elect a temporary Chair under Standing Order 17.22 for this meeting', '16254', 'http://www.senedd.tv/en/16254?startPos=36&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.041670', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770418', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('759a89659ba3c43f0e5b', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Quickly on that, I''d just like to know if there''s any consideration of the attendance of Ministers and the effectiveness of TSPCs. And maybe it''s something you want to come back to in future, Minister, but I''d like to ask whether there''s been any assessment of the previous Welsh Government strategy on volunteering, and whether you''ve considered any link between the increased pressures in terms of the cost of living and the decrease in volunteering. Thank you.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=7523&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.363685', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771314', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('75db8acb92fffafa3192', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Just to add some further context there, a lot of that increase in defence investment funding is being financed by reductions in other areas of capital spending by the UK Government. Where that''s being financed by reductions in devolved spending—for example, transport is taking quite a big hit in England—that then feeds through into a consequential reduction in our capital budget. We''ll have further details of that in the UK budget on 28 October.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Andrew Jeffreys', '', '', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=8690&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.888650', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774265', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('75e27fb512204f9fdac0', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '8. What action is the Cabinet Minister taking to speed up the processing of planning applications by local authorities? OQ64640', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'David Hughes', '', '12159', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', '', NULL, 93.5, 'High', 'digest', 'planning_system', 'Planning & place', 'Housing minister; LGHP Committee members', '', 'planning applications', 0, '2026-10-10T14:39:12.754317', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776789', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('760558420a0605d9db63', 'plenary_transcript', 'Plenary', '9. Voting Time', 'As the Senedd has not agreed the motion without amendment and has not agreed the amendment tabled to the motion, the motion is, therefore, not agreed.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('763819bf9bc7af297244', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'During our meeting with the previous Chair, it was raised very firmly that past experience has not been very good in terms of what you''ve just said about the backlog suddenly coming along and inundating the committee with work, which possibly couldn''t be done. And so we are mindful of that and we are concentrating on the timing, as my colleague says. The timing is vitally important to us, but it''s crucial for you if you''re going to do your work properly, which you—. And if this committee is unable to scrutinise, then the whole thing falls down. So, we are mindful of what you say and we are mindful of the need not to overload this committee, but there is one caveat—and this is just repeating what my colleague said—and that is that we cannot control what comes from Westminster. With the best will in the world, that can''t be done. But, other than that, all the other matters within our control, we will deal with in a manner compatible with the best interests of your committee.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1112&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.229729', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770355', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('764041cda098f70f655b', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'It''s £85,000 for next year.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1648&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.145930', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777268', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76490b49c76314f2de69', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'One of the solutions is the roll-out of smart meters in both Wales and England. Record levels of investment are rolling out around 10 million smart meters—the biggest roll-out of smart meters ever. What the evidence suggests is that when people get smart meters installed, especially when they start being billed on the basis of that smart meter, sometimes people are surprised about how much water they''re using. That helps them alter their behaviours, helps them identify the fact that there might be leaks that they didn''t know about that are customer side, as I put it, and not company side.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=1709&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.944891', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773170', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('764e3704e53f5a73990c', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Obviously, we''ve discussed that you''re expecting the complaints to go up and you''re estimating that to go up. There is a risk that the incidence of absence due to stress will increase. What is the impact of the increased case load on staff well-being so far this year and what mitigations has the ombudsman put in place to reduce the risk of staff absence due to stress?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lyn Ackerman', '', '4967', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=11128&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.326980', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777728', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76517abeff94e11eeeb0', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch, Gadeirydd. Community cohesion is something that''s all our responsibility, but, obviously, Government has to take a lead as well. The previous Government did seek to strengthen community cohesion through its community cohesion programme. I know that you, in your priority statement, have committed to progressing the recent community cohesion expert group''s recommendations. So, I''m just wondering if you could tell us a little bit more about that work, how it''s likely to be measured, and how, as a committee, we can keep up to date with the work of the recommendations group.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jayne Bryant', '', '5038', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5884&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.174024', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771303', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7678163508fce03fa049', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Mike Connolly, deputy director of the community safety division. Good morning.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Mike Conolly', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=89&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.560415', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771142', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('768ddbd8c1d807af0ccc', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I''ll probably mention quite a few times today the work that''s been going on in Scotland and the Scottish Empty Homes Partnership, which gets funding from the Scottish Government. One of their roles—and Shelter Scotland get that money—is in terms of just raising awareness amongst the public. So, we''ll talk about the limited capacity of local authority officers to just do the job, but, that ''report an empty home'' type of thing, what do we do with this wasted resource? It''s that sort of messaging to communities to actually realise that there''s something they could be doing to help from a promotion point of view—so, not data in itself, but more reporting of concerns.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=14961&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.616129', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775401', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76a182de440ea156cce0', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'I think I''ve spoken of the discipline that''s required of Ministers, and it''s required of Ministers in any Government, but in this particular year, with a new Government, a programme for government that''s new and a challenging financial settlement, bringing all of that together is a particular discipline for Ministers now to be able to present a budget that is affordable but also meets the priorities. Ensuring that that budget is able to reach the outcomes that it wants to, and then in terms of the partners that receive that money to deliver on those outcomes, is extremely important in making sure that every pound works as hard as it possibly can for the public purse. In terms of how that happens, there are regular—. I do leave it to Ministers to primarily lead on this in their portfolios, to make sure that that is part of their work and their own challenge—for the health Minister with his discussions with the health boards, for example. And productivity within the NHS is something that we are aware, as a Government, needs to be a focus for our and his work.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elin Jones', '', '162', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=8743&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget; programme for government', 0, '2026-10-02T12:57:51.898910', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774267', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76ae2d808e17ef77c4cc', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Diolch, Lywydd. May I begin by thanking all Members across the Chamber who have contributed to a lively debate? Let me focus immediately on the people at the heart of this debate: those whose interests Reform believe are in urgent need of our support, the Welsh people.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76b45b22a60f2db8093b', 'plenary_transcript', 'Plenary', '2. Questions to the First Minister', 'Diolch. Although conversations with UK Prime Minister Andy Burnham have so far been positive in terms of devolution, it''s clear that we need to reiterate to Westminster that we are a country and not a county. Devolution to the devolved nations is clearly not the same as devolution to the English regions. As Chair of the Constitution, Justice and External Affairs Committee, I wrote last week to Andy Burnham to invite him to give evidence to our committee to explain his priorities for devolution in Cymru.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76b8395788b2bd4535d5', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'And this was something that came through very strongly in the Cabinet when we were discussing this. Of course, my role is to ensure that that awareness, understanding and responsibility are shared. So, that, for instance, those opportunities through relationships and sexuality education, was essentially important and core to that.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5856&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.167354', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771296', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76da81c13509f3c99f4d', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Welcome back, everyone, to the committee. So, we''re on to item 4, the scrutiny session with the Cabinet Minister for Local Government, Housing and Planning in relation to the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026. So, the purpose of this item is to take evidence from the Cabinet Minister on the regulations, and this follows the evidence sessions with electoral stakeholders on 17 September.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('76fc5e4371a029c8ace1', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', 'Delivering meaningful change for people in Pen-y-bont Bro Morgannwg, and across Wales, is at the heart of this Government''s approach. That starts with our first 100 days plan, on which I''m working collaboratively with Cabinet colleagues to deliver. The programme for government will build on this foundation, with improved cross-Government working and a clear focus on delivery.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Dafydd Trystan Davies', '', '12140', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', '16085', 'http://www.senedd.tv/en/16085?startPos=4705&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-08-04T14:03:08.620795', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767664', NULL, NULL, NULL, NULL);
