INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('77172d00d98ce85d9b85', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Sera, I will come back to you, and then I will come back to you in a moment, Lyn, okay?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2033&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.127692', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774233', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7760becde4ea823d5a20', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thanks, Cabinet Minister. Before Lyn comes back in, Huw Thomas has a question.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=8207&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.803057', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774195', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7761d1c2f5039b8a6247', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I''ll finish with this—it''s the last thing. There are lots of chapels and lots of pubs, not only in town centre areas, that have been a lifestyle choice by people. Chapels have far fewer people going to them now, pubs have far fewer people going to them now, and you have these buildings that get left. Do you have any suggestions for what we ought to be looking to do to bring those back into useful use? I know some of them get sold, they get sold again and they get sold again, and a planning application, which you know is never going to succeed, is put in, then it gets sold on, and there''s another planning application, which you''re just looking at and you think, ''You''ll never get that many flats in there, and if you do, you''ve got no parking for them''. This is something that most people who''ve sat on councils have dealt with lots of times. Do you have any suggestions for what we can do to bring some of these into purposeful use, as opposed to letting them be moved from developer to developer without much happening?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15465&l=en', NULL, 212.7, 'Critical', 'immediate', 'taxation_of_property; planning_system; committee_scrutiny', 'Housing system; Planning & place; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry; planning application', 0, '2026-10-07T06:31:26.695471', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775518', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('776ea128f27c9d3b085b', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Would you?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Chris Bailey', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17107&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.988119', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775525', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('777ff188f0a3caa8ab4d', 'plenary_transcript', 'Plenary', '2. Questions to the First Minister', 'It''s very important that local authorities are able to make their own decisions on local taxation. I know I have never met a local councillor or a leader of a council who wants to raise council tax in a way that impacts their constituents more than is absolutely necessary. We made a decision around the deal on the budget with the previous Government that absolutely reflected the need to minimise council tax increases, in making sure that we were able to negotiate an agreement that made sure that there was a minimum 4 per cent uplift in order to limit council tax increases. Those decisions are best left for local representatives. That''s an important principle.', 'https://record.senedd.wales/Plenary/16264', '2026-09-29', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '2. Questions to the First Minister', '16264', 'http://www.senedd.tv/en/16264?startPos=847&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'council tax', 0, '2026-10-03T13:38:58.044832', 'https://record.senedd.wales/XMLExport/Download?meetingID=16264&xmlDownloadType=EnglishTranscript#772836', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7780fe7ce26bbf8f8d15', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much. I just have one other brief question, if that''s okay. You talked about the steps and the milestones, in your mind, do you have an idea of when we''ll be in a situation when we will know what those look like? And I hope I know the answer to this: are you in touch with other Governments, such as the Scottish Government—and we have also heard from Finland and other places—and are you looking at what they''ve done and how to keep an eye on countries such as ours, which are small, for example?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jane Dodds', '', '4983', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=633&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.620787', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771149', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('77914157454d093dd6a4', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thank you. I''ve got some other questions, but I''m going to write to you, if that''s okay, with the questions on future evaluation of AVR. Obviously, I''ll share the questions with the committee members, and the subsequent response. But right now, I''d just like to thank you for giving evidence and providing us with a bit more clarity around the process. We will send you the minutes, if you like, of the meeting this morning, just to ensure that we''ve captured the accuracy of what we''ve been discussing. But, again, many thanks from the committee.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2819&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.124399', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769933', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('77f41be79d0510187a41', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes. Thank you. I''m now unmuted. I certainly do. Can you expand on the rationale for reducing the required number of automatic voter registration exercises from four to one and the potential effect on areas with higher levels of mobility—i.e. areas like the ones I represent, with lots of houses in multiple occupation and lots of students, where you have substantial movement during the year?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1608&l=en', NULL, 138.0, 'Critical', 'immediate', 'hmos_and_standards; committee_scrutiny', 'Housing system; Private rented sector', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session; houses in multiple occupation; multiple occupation', 0, '2026-09-18T11:33:48.934744', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769834', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7808274312ab81cc7380', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Diolch yn fawr, Peredur. Lyn, you''ve got a couple of questions.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=943&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.037952', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777214', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('783c592316ddd61fef1f', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I''m Dafydd Trystan Davies and I''m the Cabinet Minister for Government Effectiveness and the Constitution. So, as a team from Government legal services, we are very pleased to be here, Chair.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', 'Cabinet Minister for Government Effectiveness and the Constitution', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=203&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.060862', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770348', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('784afce22548b85b1522', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'I was going to go back to the satisfaction quickly, so I don''t know if you—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Benjamin Hodge Mckenna', '', '12142', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=9019&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.005447', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777676', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('785ae297fbe9ac2747db', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you. Planning policy sets out that local planning authorities should support the provision of all types of infrastructure required to meet the needs of communities when new housing developments are considered.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=7790&l=en', NULL, 60.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'planning authorities; planning policy', 0, '2026-10-10T14:39:12.721405', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776793', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('785b40699718d45ec595', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Two point seven.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4091&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.541814', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777448', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('78721796e14b226fa7c5', 'plenary_transcript', 'Plenary', '5. Statement by the Cabinet Minister for Local Government, Housing and Planning: The Revision of the National Development Framework and National Conversation', 'Thank you very much, Dirprwy Lywydd. Today, I''m pleased to inform Members that I''ve launched a national conversation about the future of Wales through the creation of a new national development framework. The national development framework sits at the heart of the planning system in Wales, providing the strategic direction for regional and local development plans, and the framework for planning and development decisions across Wales. As Wales continues to respond to significant challenges, including climate change, nature recovery, housing need, economic growth and infrastructure delivery, it''s essential that our national planning framework is fit for purpose and capable of supporting our nation''s ambitions for the future.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('789e79ab383e1b829c71', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Obviously, as I was saying, I will be taking— . The Cabinet will soon be committing, as a Government—. We''ll be discussing this over the next few weeks for that exact reason. We, as a Government, need to define our relationship with the third sector. Of course, I do engage every day with members of the third sector, and with organisations such as the WCVA and so on. So, as a Minister, I am fully aware and have stated on the record that I acknowledge the importance of this sector, and so I would hope to make sure that that relationship is an effective one. I don''t know if there''s anything else specific that needs to be added on engagement with the third sector.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=7439&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.350775', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771298', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('78ad95aa2f7b813b5591', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Absolutely.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5538&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.562073', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775531', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('78ba24d43720e9a853cd', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '[ Inaudible. ]—of Aberystwyth University, I fully support what he said.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4685&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.921329', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770605', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('78be10b34aca71ceab8e', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Policy on data centres and how they use water is, obviously, a matter for the Welsh Government and for the UK Government. In our price review, the last price review, we introduced some mechanisms to reopen allowances to support economic growth. Companies have come forward with some suggestions, which we scrutinised with exactly the same rigour as we did for PR24, to allow a small number of companies to increase investment to support housing growth in particular.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('78c6ffc258f2d1ca4a6e', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Well, I think it''s just, generally, how are you going to—? What steps are you going to take to improve meeting these targets?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=454&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.785826', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774363', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('78e397f670cec50d7d66', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I have a good example of that, actually, from my colleagues in Cardiff. They entered what they believed was an empty property under housing legislation. According to council tax, it was being lived in by a single person. They entered the property under warrant, confirmed that it was, in fact, vacant. As a result, evidence in terms of statements and photographs were provided to their council tax department. The owner was subsequently brought in and interviewed under caution. It was also found out that he was connected to another person, and they were claiming single person council tax benefits, so the end result was that they were ordered to repay the costs. It was quite a process to get to that point, but they''ve recovered the difference, so it does pay off to feed back any information to the council tax department.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Georgina Wayman', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6110&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; empty properties; empty property; evidence session; inquiry', 0, '2026-10-07T06:31:25.655218', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775480', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('78f30a6c908f188e29f9', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Yes, Chair, I''ll take that. Just to preface to the committee, obviously I''m new into the role, so colleagues might need to come in with some supplementary information if that''s needed. Yes, you''re right, we do now have a digital data and technology strategy, and it''s about helping us to respond to the growing demand in cases in a practical and affordable way. We''re not investing in technology for its own sake. We''re focusing on improvements that make services easier to access, but also help our staff work more effectively and deliver value for money. We''re taking a phased approach, testing ideas first, and only investing further where there is clear evidence of benefit.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7908c036acae24a4b8fd', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Minister, this is a minority Government and, over the last few weeks, this Senedd has demonstrated that Plaid cannot simply assume that others will just fall into line and vote with them. If the Government wants to secure the support of this Chamber, it must be prepared to build the consensus across political divides and to listen to those who represent different viewpoints. Every one of us in this Chamber has been elected to represent our constituents and to honour the mandate they have given us. Our responsibility is not to make life easier for the Government, but to ensure that the voices of the people we represent are heard in this place.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79097ed16c83a43d4a37', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Thank you.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=14476&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.526565', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775439', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7911adcda1d05050c23a', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Thank you so much, and thank you for all your time with us this morning; it''s very much appreciated.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=3768&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.485127', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774402', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79142c6ae54a3bcd1f7c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'The gathering of data is really important for local authorities. Our experience across local authorities is that you have more proactive and less proactive empty homes teams and empty homes officers. If there''s a point of contact where the community can engage with a person or a department at each local authority, hopefully that would give support and that data can come through as well.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Trystan Jones', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15029&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.627167', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775366', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('792aa3b1930e923a30d9', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'The work that advocates do—Llais is a key one, but there are other organisations—is critical. It''s really helpful to us, because our job is to deal with the complaints that are brought to us and do that independently and objectively. We''re not there to advocate on behalf of or to support a complainant''s view, nor are we there to protect the reputation of a public body. We''re there to look at the evidence, investigate and make the right decision, come to the right conclusions.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7994a3b9053db8a77ddf', 'legislation', 'Welsh Statutory Instruments 2025', 'The Visitor Accommodation (Register and Levy) Etc. (Wales) Act 2025 (Commencement) Order 2025', 'The Visitor Accommodation (Register and Levy) Etc. (Wales) Act 2025 (Commencement) Order 2025', 'https://www.legislation.gov.uk/wsi/2025/1305/made/data.xml', '2025-12-16', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 84.5, 'Medium', 'digest', 'second_homes_and_short_term_lets; named_welsh_legislation', 'Context; Planning & place', '', '', 'Visitor Accommodation (Register and Levy); visitor accommodation', 0, '2026-08-04T14:04:15.224560', 'https://www.legislation.gov.uk/wsi/2025/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79a0743dce6839c20602', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Diolch. So, I completely agree that prevention is better than cure. Keep it out, that is the way forward, and there are different tools and technology. I think a crucial piece here, and it also speaks to the question you raised, Chair, earlier, is about vets and farmers working closely together to look at the individual herd and flock and the health status and the diseases and conditions of concern, whether those are conditions that are already present in a herd or flock or those that might be coming towards. And to look at that, with vet and farmer in partnership, to assess, on the one hand, biosecurity, as you''re rightly asking, John, keeping disease out, prevention, and using different tools to assist that conversation, but also then to take action to ensure that that health planning, if you will—that animal health and welfare planning—translates into an improvement cycle. And, going back to your specific point, James, that is the animal health improvement cycle in universal action 12 of the sustainable farming scheme in a nutshell. Diolch.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Richard Irvine', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6776&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.224803', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772120', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79ab0f34a492cc69a208', 'committee_transcript', 'Petitions Committee', '2. New Petitions', 'Okay. This petition calls for the pausing or withdrawing of Welsh Government climate change policies on the basis that they are damaging people''s lives. Climate and nature-related petitions have been discussed by the committee on numerous occasions. In November 2024, the sixth Senedd Petitions Committee considered a petition calling for net zero to be scrapped. The petition was closed on the basis that there was nothing more the committee could do about the issue, noting the clear difference of opinion between the petitioner and Welsh Government at the time. In 2019, the Welsh Government declared a climate emergency, and then, also in 2021, the Senedd declared a nature emergency. The Cabinet Minister''s letter explains the steps taken by the Welsh Government to assess the impacts of the new climate-based policies on nature.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79b8e7123afa4021dddf', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'In terms of the board, I can answer now or pick it up in the next question, if you like, as you wish.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Dr Ian Rees', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2687&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.276057', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774160', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79ba49e3ee25e7d1e0e8', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much. This Government, as you know, has ambitions in terms of the devolution of a number of powers over welfare. So, I have already, through correspondence and also through meetings, had several meetings with Ministers in the UK Government, namely the Secretary of State for Work and Pensions and also the Parliamentary Under-Secretary of State (Minister for Transformation). So, I''ve set out, in those meetings, our ambitions in terms of receiving additional powers over devolution, so that we can create a system that is more fit for purpose in terms of the kind of support that we want to provide for our families and communities here. So, of course, ensuring that we can be enabled to pilot Cynnal is part of those discussions. That is part of our powers under the Government of Wales Act 2006, but, of course, as I mentioned earlier, we do need support to do that in terms of the Treasury, to ensure that no family or child that receives those payments is worse off as a result.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79c4a89e3b048cd5841c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'It''s a bit of a leading question. But I''m curious, because it''s not often that there are pots of money in local government these days, and the fact that 90 per cent of it is unallocated suggests there''s a problem, and whether that''s a lack of EPOs, lack of engagement with landlords—. How can we spend that money?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5600&l=en', NULL, 235.7, 'Critical', 'immediate', 'private_rented_sector; taxation_of_property; committee_scrutiny', 'Housing system; Private rented sector; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry; landlords', 0, '2026-10-07T06:31:25.575075', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775486', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79ccf2d816184f003d8c', 'oral_question', 'Oral Question (tabled)', 'OQ64627', 'What is the Government''s approach to ensuring co-operation across portfolios to deliver the Programme for Government?', 'https://record.senedd.wales/OrderPaper/OralQuestions/06-10-2026/', '2026-09-29', 'Beca Brown', '', '', '', 'Gwynedd Maldwyn', 'Plenary', 'To the Cabinet Minister for Government Effectiveness & the Constitution', '', '', '2026-10-06', 15.0, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-09-30T06:33:48.533224', 'orderpaper:2026-10-06:OQ64627', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79db2ed167a74718e0f4', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Small businesses are the backbone of our local economy in Bangor Conwy Môn. A clear example of this in Bangor is Antoniazzi''s cafe, which has been a prominent presence on the high street for 92 years now. In recent conversations with a number of businesses recently, the same request often rose, namely a fair deal on business rates, and I look forward to hearing the finance Minister''s statement later on this afternoon about that. But does the First Minister agree with me', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Mair Rowlands', '', '5084', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=571&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-16T11:53:07.097271', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768989', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79f3419a541db9cb2283', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'There is—', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15620&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.723459', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775574', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79f67b18b7dab6e73bc6', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'In terms of the overall underspend on resource, around £650,000 is related to underspend on staffing costs, and the balance related to non-pay costs. A lot of the underspend related to issues within the audit delivery team, where, as you know, we are doing an awful lot of work to catch up with the backlog that came around during the COVID crisis. We''re now in a position where we expect to have met or addressed that backlog during the current financial year.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('79feda279b333a968beb', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Just in terms of an update on the work, the expert group reported in March, published its recommendations, so we''re currently considering those recommendations as part of the ongoing work with the Deputy First Minister, and we''ll be making, I''m sure, a response to that report in due course. But, over the course of that expert group, we also worked with the expert group to define and set out a set of cohesion principles, which are on the website, and that describes what cohesion looks like in Wales and how these principles would help organisations and Government understand what it looks like. So, that work is in train. There are a number of recommendations that have already been delivered, but there''s work to be done on what the full response is.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Andrew Charles', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6093&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.193950', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771248', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a01af04c06f279a264b', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '[ Inaudible .]—but I think also I mentioned earlier about looking at the legislation in terms of the regulations, in the Representation of the People (England and Wales) Regulations 2001, which are used as the basis for accessing information, and reflecting what UK Government has done to help remove those barriers, and also looking at the nature of some data sets as they are formed from national data sets—so, housing benefit would use DWP data—and then that''s acted as a barrier as well to obtaining a really good data source potentially that could be used for that. So, again, just looking at the framework that sits around the legislation to allow greater access as well.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Clare Sim', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=6042&l=en', NULL, 92.0, 'High', 'digest', 'welfare_and_support; committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session; housing benefit', 0, '2026-09-18T11:33:49.526823', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769954', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a264f988b28f22d7d38', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'There may be some elements that we might need to make provisions for once contracts are signed, but at the moment there''s nothing included.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=578&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.984016', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777385', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a6b498ea31acae028fd', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'So, item 3 this morning is the general scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution. It''s good to see you here. It''s good to see that you found your way to this meeting room. It is nice to have you here. Would you be able to introduce yourselves and your staff and officials for the record, please? I will begin with Elfyn. Thank you.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=139&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.048196', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770345', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a6b94299c9087eefc3f', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Yeah, I take that point and I agree with it. As I was saying earlier, many of the powers that we could use to regulate how this misinformation is spread are not available to us. But, as I said, I do think that there are things that we can do to make communities more resilient to be able to withstand that misinformation. Obviously, we work very closely with partners who see the impact of this through the third sector and the voluntary sector, who could share with us their ideas and ensure that we are able to support them in the work that they''re doing in terms of trying to tackle this. In terms of the new agency, I would certainly be interested to engage with that.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6197&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.207934', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771263', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a6f7c1d7df0dba4245a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Okay. Does anybody have any further questions for the Cabinet Minister or her team? Okay.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a7a5ea8de53f81c21e9', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'We''re fully engaging with the Welsh Government at an official level, and I know that the chief executive is speaking to senior officials within the Welsh Government to make sure that they''re fully apprised of what''s going on. With any decant strategy, that comes into effect as well, because everybody moves out of the building if that''s the case. So, again, managing what Ministers and the Government want, as our sub-tenants, if you like, is something that happens. So, the Welsh Government, as a key tenant, would be an operational stakeholder. So, a Welsh Government official sits on the Bay 32 project, so there''s one member there, obviously, because they''re a significant stakeholder in that. And then, through the joint assurance board, they co-ordinate the dependencies and escalate any issues that they might see. Obviously, from an accountability point of view, it''s close stakeholder engagement, so we have to manage that, as you''d expect.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2682&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session; stakeholder engagement', 0, '2026-10-09T13:34:37.336785', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777477', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7a96e1eb50cc7275de0a', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'It might well have been a priority for the last Government. I doubt whether it''s a priority for your party right now because you voted against the supplementary budget, which offered £145 million to develop diagnostic hubs and elective care hubs across Wales. But, yes, it is a priority.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16086', 'http://www.senedd.tv/en/16086?startPos=1651&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:04.845058', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768058', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7aa07efb51b40c649321', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'We believe in our nation, and we will take every step possible to unlock its potential and build a stronger, fairer and more resilient Wales. We will continue to make the case to the UK Government for the funding, the investment and the powers that Wales needs to thrive. As such, I look forward to meeting with the Prime Minister at the National Economic Council next month.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=8885&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:19.729337', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#770988', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7aba4be6ad7c27af3575', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'What are you going to be doing until then? Because obviously that''s 2032, is it? Am I right in thinking that''s the year that, obviously, Ofwat’s going to be—I don''t know if ‘dismantled’ is the right word, but we''ve got the new regulator set up. Obviously, there are quite a few years until then, so from that report that highlighted all these issues that came with Ofwat, what are you doing until then? Because obviously we know, hopefully with the set-up of the new one, that''s where the biggest significant change can happen, but that''s still six years away. So, what''s going to happen then, so that year on year we''re not in this same situation again until we can see that new regulator set up?', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=2824&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.097937', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773220', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7b13d9fd94f3f28535fa', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Actually, Wendy, you answered my question about the Welsh housing quality standard, because we discussed that this morning, about how RSLs can''t purchase or can''t buy those properties because they''re not up to the WHQS. That seems to me something that the Welsh Government needs to look at, because the gold plating, while admirable, if it means that kids are staying in temporary accommodation, that''s not right. This is a question about the strategic approach, and the joined-up thinking seems to be, at the moment, ''Let''s give this fund to councils, let''s hope they employ an empty property officer, but if they don''t, they don''t''. As Casey will know from our work together in Wrexham, we don''t have an EPO in Wrexham, and that means that all the well-meaning, good work and the funds that are available don''t reach the people who need them. For me, one of the great failings is that we''ve got a pot of money that isn''t being spent, and I''ll come to that as a separate issue. I suppose the strategic approach is: how do we ensure that community groups have more of a say in this and are linked in with the councils? We did an inquiry seven years ago, or the previous Government did an inquiry seven years ago. We''re doing an inquiry now. I don''t want to come back in seven years and say, ''Actually, we''ve still got this problem—we haven''t got an EPO in Wrexham.'' We have to be more proactive in engaging with the community. You''ve made some really positive suggestions, but how do we make sure that the Welsh Government actually does this?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16153&l=en', NULL, 276.0, 'Critical', 'immediate', 'energy_efficiency; taxation_of_property; homelessness; social_housing; committee_scrutiny', 'Housing system; Property & energy; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; RSLs; WHQS; Welsh housing quality standard; empty properties; empty property; evidence session; inquiry; temporary accommodation', 0, '2026-10-07T06:31:26.823861', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775390', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7b265adf563719e143e0', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'May I make one comment?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5240&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.044365', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770565', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7b2d87a63a7ebdf4e6a3', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you, Chair. Yes, my question is specifically on carbon budget 3. As we know, it''s quite a big step, but, obviously, a really important step as well. I just wanted to touch on the fact that, if I''m right from what I''ve been reading, 60 per cent of the emissions reductions required come from policy areas that are reserved or partially devolved. So, I was just wondering what your relationship is looking like with the UK Government, and are you getting those kind of assurances that you need from them as well that the policies and actions needed in those areas—along with, obviously, actions from the Welsh Government as well—will be in place to ensure that we meet our goals with that budget?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4286&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.846448', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771793', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7b7669849680b34b263a', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'The Cynnal payment has the potential to make a real difference to families facing the sharpest end of child poverty, particularly in communities like Afan Ogwr Rhondda, where levels of deprivation are among the highest in Wales and household budgets are already under enormous pressure. But, for it to work, families need clarity and confidence that this support will reach them directly. We know there are clear precedents for additional payments being disregarded within the benefits system, including the Scottish child payment and local welfare provision. But the Welsh NHS and social care bonus show that without Department for Work and Pensions protection, the value of a Government payment can be reduced through the universal credit system as it''s then classed as earnings. If the DWP is unwilling to provide that protection for an anti-poverty payment aimed at children, does the Dirprwy Brif Weinidog agree that this underlines exactly why decisions affecting poverty in Cymru should be made in Cymru by a Government that understands and prioritises communities in Cymru? And will she set out what discussions the Government is having to ensure that the Cynnal payment is simple to access and protected in full?', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Elyn Stephens', '', '12164', '', '', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', '16084', 'http://www.senedd.tv/en/16084?startPos=710&l=en', NULL, 77.0, 'Medium', 'digest', 'welfare_and_support', 'Housing system', 'First Minister / Cabinet; LGHP Committee members', '', 'universal credit', 0, '2026-08-04T14:03:15.519129', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#766807', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7b7e2bbfa8fcf3a3b5df', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'I''ll turn to Welsh. You mentioned, Ann-Marie, the local government bodies, but are there problems with parish and town councils? I have a concern about those as well and how they submit accounts to you as auditors.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=746&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.851159', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774452', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7bb9a44f569f55163995', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thank you, Cabinet Minister—', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=6775&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.562399', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774296', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7bfac7d1c1bb5d384849', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Can I respond to that? I think it''s that idea of where the strategy sits, so where the strategic approach is, and I think, linking on to that point from Adam about flexibility, local authorities know their areas, they know the reasons why local properties might become empty, and I think if we have that sort of blanket approach, we might continue with some of the issues with them not being addressed. I think this idea of intelligence sharing, best practice sharing, empowerment for local authorities to be able to tackle those issues in the right way in their places is really important.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7c23dfd6f6a0b5b3b852', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'I now call on the Cabinet Minister for Local Government, Housing and Planning, Siân Gwenllian.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=17226&l=en', NULL, 88.0, 'High', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', 'Housing minister', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.515816', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776971', NULL, NULL, NULL, NULL);
