INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7c6b5080e7938dfe91e0', 'plenary_transcript', 'Plenary', '3. Questions to the Senedd Commission', 'Diolch, Joe. Bay 32 is the Commission’s project to secure fit-for-purpose accommodation beyond the expiry of the Tŷ Hywel lease, which happens in 2032. A competitive procurement concluded that the best value option is a major refurbishment and renewal of Tŷ Hywel, with the potential for Commission ownership. Equitix is the preferred bidder and its proposal includes more than £50 million of landlord investment—landlord investment—in the building. This is planned to include increasing the amount of useable space in Tŷ Hywel by 25 per cent. The project is now in detailed design during a pre-development phase with capped costs to the Commission. Because the building must remain operational during major works, temporary accommodation will be needed for Members, staff and for services. So, the Commission will consider options for managing any relocation, before considering the full business case later this year. The works are currently expected to begin from early summer 2027 and last for up to three years.', 'https://record.senedd.wales/Plenary/16263', '2026-09-23', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '3. Questions to the Senedd Commission', '16263', 'http://www.senedd.tv/en/16263?startPos=6471&l=en', NULL, 71.5, 'Medium', 'digest', 'private_rented_sector; homelessness', 'Housing system; Private rented sector', '', '', 'landlord; temporary accommodation', 0, '2026-09-26T13:20:12.160296', 'https://record.senedd.wales/XMLExport/Download?meetingID=16263&xmlDownloadType=EnglishTranscript#771551', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7c7ddc97e563a84df84e', 'oral_question', 'Question not reached in Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', 'What assessment has the Cabinet Minister made of the impact of housing and planning policy on the ability of local authorities to deliver enough affordable homes for local people in Flintshire and Wrexham?', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Nigel Williams', '', '5113', '', '', 'Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 55.0, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'planning policy', 0, '2026-08-04T14:03:06.987962', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
