INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7fdf5893a09118210fcc', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Yes, I''m sure there is.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2653&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.328847', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777470', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('7fe9ab2270a7f93faa4e', 'committee_transcript', 'Health and Social Care Committee', '2. General scrutiny session with the Cabinet Minister for Health and Care, the Deputy Minister for Public and Preventative Health and the Deputy Minister for Social Care, Mental Health and Women’s Health', 'Great. Thank you very much, and thank you to the committee for the opportunity to be here today. As Mabon mentioned, clearly, our work has focused in the first 100 days on realising the ambitions we set out. We are now, of course, steering the programme for government, which will be based on the manifesto. But, in terms of that preventative health element that I''m responsible for, you''ll be aware that it''s the first time we''ve had that kind of role in Government, so it''s incredibly important to set out the foundations in terms of how we''re going to take action across this term.', 'https://record.senedd.wales/Committee/16251', '2026-09-17', 'Nerys Evans', 'Deputy Minister for Public and Preventative Health', '261', '', '', 'Health and Social Care Committee', '2. General scrutiny session with the Cabinet Minister for Health and Care, the Deputy Minister for Public and Preventative Health and the Deputy Minister for Social Care, Mental Health and Women’s Health', '16251', 'http://www.senedd.tv/en/16251?startPos=480&l=en', NULL, 17.2, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-09-19T12:39:13.860766', 'https://record.senedd.wales/XMLExport/Download?meetingID=16251&xmlDownloadType=EnglishTranscript#769870', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('80302a6729725a7a88e5', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '1. What lessons has the Cabinet Minister learnt since failing to pass the first supplementary budget for 2026-27, and how will this inform the Welsh Government''s approach to future budgets? OQ64442', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Andrew R.T. Davies', '', '143', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', '', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-09-19T12:39:16.900089', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769513', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8037d5a8a9efdcd934a2', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Well, the figures will become clear in the forthcoming draft budget, and you will be able to scrutinise that, and the committees will be able to scrutinise that, and, of course, questions can be asked here of Ministers around their spending plans. 
