INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('837ebbf907a121cbd13f', 'plenary_transcript', 'Plenary', '5. Statement by the Deputy Minister for Social Care, Mental Health and Women’s Health: Stronger Safeguarding for a Safer Wales', 'Thank you, Dirprwy Lywydd. Safeguarding is one of the most fundamentally important responsibilities of any government. It''s about ensuring that all children, young people and adults who are at risk have the right to live their lives safe from abuse, neglect, exploitation or harm. That is why safeguarding remains a key priority for this Government, and that is why strengthening safeguarding arrangements is central to our programme for government.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('83b011dcd46ea81a8f53', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Me neither, but it wouldn''t stop the process of enforcement taking place. If a property is in a dangerous condition, of course measures will be taken to secure it.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Osian Jones', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6329&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.695110', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775517', NULL, NULL, NULL, NULL);
