INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('861635ded673ea9945d9', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''ve not seen the outcome of any work as yet in terms of any results from it, but I do know that there is work being undertaken in relation to looking at the effects on habitat through bodies like Natural Resources Wales.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Rhodri Asby', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1992&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.562107', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772027', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('86462613e5fcc666acaa', 'research', 'Senedd Research', 'FMQs this week – 06/10/2026', 'FMQs this week – 06/10/2026
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('864f726029f04c85283d', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'So, it''s not my portfolio, but I think that principle is absolutely right. I''ve always said we have at the minute a hub-and-spoke model when it comes to energy, where you have large, centralised, big energy-generating hubs. That''s then distributed to the ends of the earth very ineffectively and inefficiently through transmission loss et cetera, which isn''t, I think, the best way necessarily to do it. We need to move to more of a spider-web situation, which is much more resilient, where you generate locally, you use locally, and if one of those hubs goes down, then there are other networks nearby that can kick in. The risk is that, if you are on a hub-and-spoke model, if one of those big generators glitches, then it''s a huge problem for half the country. There''s an ongoing discussion around that. I know local grids and things are being trialled. I would want more of that to happen here in Wales, but I''m definitely now straying into other portfolio areas, but there''s a strong case to be made for doing more of that.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4991&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.965728', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771813', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('86594e636a2af18c639a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Thank you.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4288&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.350535', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775180', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('865e2874151685d3dc1d', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Well, I was chair of the cross-party group on human rights in the previous Senedd, and we held an inquiry and published a report on how, currently, people aren''t either aware of their rights or aren''t able to see those rights being deployed in their daily lives. So, we heard evidence from disabled people, we heard evidence from people and organisations looking at women''s rights; we looked at people from minority ethnic backgrounds. There were a number of stakeholders who participated, and they were able to provide specific examples of where things weren''t operating as they should. We heard very powerful evidence about the Stolen Lives campaign, for example. This was an example where there were people who had learning disabilities being kept, in contravention of their human rights, in hospitals that weren''t appropriate for them. Because there wasn''t provision for them to live independently, they were being placed, and locked, indeed, in institutions that didn''t respect their human rights.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('865fb4848929c6d9d7ba', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Yes, of course. The idea behind this is thinking about a new way of looking at crime prevention. We know that crime in a number of different ways—. Although we don''t have powers over criminal justice and policing, people in Wales do feel the impact, clearly, of offending and crime. So, what we want to do by working in partnership is look at how Wales can prevent that harm that is experienced by communities, by bringing together evidence and expertise from a number of public sectors.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('866d6cfb15e58efd2dd8', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'You say staffing accounts for 70 per cent of your costs. How have you sought to reduce the growth in your staffing numbers?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lyn Ackerman', '', '4967', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1253&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.073288', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777474', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8670765527b26c3499fb', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Just to add that we are now looking at refreshing the official languages scheme and we will respond to that when the results of that are known. We are aware of the technological advances, and our translation team has been very prominent in maximising the use of machine translation in order to make their work more efficient over the years. We are now assessing some of the new AI options. AI can''t interpret to a sufficient standard at the moment, but there are ways that we could be using the latest technology to assist. But, in essence, there is a commitment that has just been re-confirmed by the Commission to maintain high-quality services as a default, so that people can use their language of choice in undertaking their work in the Senedd.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Manon Bonner', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4784&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.642594', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777519', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('8686197fbedc393f8b84', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Thank you. Well, it''s been quite an eye-opening morning for us. I''d like to personally thank Marc for raising it before recess as something that we would wish to pursue. I''d like to take the opportunity to thank all the witnesses who''ve attended. Thank you so much for your time. I hope you don''t mind, but if we do have any additional questions after this, when we''re having a chat, we will send them to you. But you have my and the committee''s thanks for presenting yourselves today. Trystan, thank you so much for your appearance. Thank you very much. We will send a transcript out to you to check for factual accuracy, and that will be with you quite shortly. Thank you very much.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17791&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:27.113481', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775429', NULL, NULL, NULL, NULL);
