INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9377c560e7e901109ffe', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Okay, we may come on to that a bit further on, on some of the AI points. But just going back to the broader increase in complaints being reported, a significant proportion of that is in health-related complaints. Do you think health boards have taken enough notice of that significant increase in complaints to you?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=7071&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:37.710706', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777517', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('938e10f0606afa05fe2b', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'No, I haven''t, but I think that that pragmatic approach to circumstances is one that the UK Government should consider. And now that you''ve raised it, I''m sure it''s something that I can do.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2687&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.681480', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771875', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('93916a87f0c62aa5c810', 'calendar', 'Senedd forward look', 'Equality, Human Rights and Social Justice Committee — 14 October 2026, 09.25', 'Equality, Human Rights and Social Justice Committee is scheduled to meet on 14 October 2026 at 09.25.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('93c5335a50e440d68482', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Okay, so welcome back. We''re into item 3, the follow-up inquiry into empty properties, and this is evidence session 2. This is the committee''s second evidence session to inform its inquiry into empty properties, and in this session the committee will hear from local authorities'' representatives. So, first of all, I''d like to welcome everyone on the Zoom call and in person to the meeting. Could I ask if you could introduce yourselves one by one? Shall we start with who''s in the room first, with Georgina?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4247&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.342295', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775168', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('93d318f4f513c5d01bfc', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'That''s where the roles of returning officers, chief executives, sitting with that dual hat and viewing elections as an important role to be done across a range of areas of the council, are really critical. Obviously, that''s why the complementary work of the AEA and the electoral management board, bringing returning officers together with electoral administrators so that that co-ordination happens effectively and in a high-quality way is really, really critical. As an EMB, we''re only 15 months in, but I think what you''ll see is that best practice rolled out as a result of that effective co-ordination. I think that''s some of the findings from the Electoral Commission''s report on the Senedd elections, that you''re starting to see stronger and more effective co-ordination.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Ian Bancroft', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5822&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.491828', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769960', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('93e12eaf89e16b4f33ed', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'First Minister, you call tackling child poverty the defining mission of this Government, but a defining mission surely requires something to be defined. In July, when I challenged your Deputy First Minister over Cynnal, I said that what she presented was a plan to plan, not a plan. She told me that she was baffled by my question. Well, I have now read your programme for government, and the bafflement should be on your benches. Four years of Government, and on your defining mission, you promise to develop another plan that will then set the targets, benchmarks and milestones. Cynnal itself remains something you merely seek to pilot. This is not a four-year delivery programme; it is a promise to work out later what success should look like.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('94155fb4608dbfe70809', 'oral_question', 'Question not reached in Plenary', 'Questions to the Deputy First Minister and Cabinet Minister for Social Justice and Equality', '<p>We are committed to advancing equality across Wales. Our priorities are set out in our programme for government, published last week.</p>', 'https://record.senedd.wales/Plenary/16265', '2026-09-30', '', 'Deputy First Minister and Cabinet Minister for Social Justice and Equality', '', '', '', 'Plenary', 'Questions to the Deputy First Minister and Cabinet Minister for Social Justice and Equality', '16265', '', NULL, 35.0, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-10-01T13:39:20.027025', 'https://record.senedd.wales/XMLExport/Download?meetingID=16265&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('94181c9c0ab288c59b85', 'plenary_transcript', 'Plenary', '5. Statement by the Cabinet Minister for Local Government, Housing and Planning: The Revision of the National Development Framework and National Conversation', 'Thank you very much for those comments, and thank you in particular for the ideas that you put forward at the end of your contribution—those ideas on practical steps that could be taken. That''s the exact purpose of this consultation: to invite people like you, like all of us in this Chamber, to give serious consideration to how we can improve the planning system so that it can respond more quickly to planning applications when problems arise with the issues that you mentioned in your contribution. So, there are a few ideas there that are worth looking into, and I would encourage some of you who are interested in this area—many of us have been county councillors and are highly aware that the planning system can sometimes hold back housing development. That is exactly why we are carrying out this consultation.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('943144ed36a0627f0680', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I think you''ll be a regular visitor to our committee, Cabinet Minister.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=7127&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.277177', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772089', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('944daa95fb567946b43d', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you. Dirprwy Lywydd, the Member makes an important point there in terms of the role of integrated care closer to home, and of course, that''s what we''re trying to do at the moment. We have delivered on the commitment that we made during our first 100 days in order to get the health boards to develop plans to shift resources into the community—0.5 per cent of that annual funding is the requirement, and they are bringing plans before me soon. I have made it clear that the expectation is that they should do that soon.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9452115f584e42039931', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Ben may want to correct me or speak further, but the Elections and Elected Bodies (Wales) Act 2024, which allows automatic registration, which was passed by the Senedd in 2024, doesn''t allow regulations to be made in relation to national insurance numbers, for example, to data held by UK authorities. That was obviously in the context of 2024. There may be a different—. Now that the UK Government is more interested in this, there may be an opportunity to revisit that in the future. At the moment, the regulations relate to local data sources, because that''s what is within the powers of the overarching Act. Ben.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Michael Kay', '', '', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9924&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.261691', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774399', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('945bd39a89ae63797917', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Sera.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2341&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.267728', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777257', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9461ffc08890ade4e7c8', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'We have to bring in—. Because we''re very reliant on our loan scheme, the empty housing to homes loan scheme, our legal team focus on that, so we can''t ask them to prioritise more time doing enforced sales. We have to bring in external legal assistance to oversee the enforced sales. That money obviously gets repaid from the sale of the property, so it doesn''t come out of the council budget, but we could do with, maybe, the usual—clerking officer time, and maybe assistance with more and more admin time, legal time. A bit more assistance, and we could probably do more each year.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'James Bolton', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5200&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.509469', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775228', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('948ebe2a9e80a7e7a32f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Thank you, Trystan. Wendy, do you want to continue? Then Dave will have the next question.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15740&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.743235', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775585', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('94a42d2ce1ea12e0f034', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I think we know the answer now. We''ve had it from everybody, so I won''t ask you to confirm that there''s a lack of capacity.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16489&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.872584', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775524', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('94e05d2a01966368df6b', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think, as we said, in terms of delivering this, to not have a knock-on consequence in terms of local government elections, you need to have anybody who needs to be added to the register guaranteed to be on the notice of alteration that is published in March, to allow people to know how many electors are in each ward and the ballot paper requirements, and not introduce the risk that exists there. So, it''s knowing that everything that falls back from that, that you can send notification letters out by this point and that the software is ready to do the data matching that allows you to do that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('94ec981265786bee928c', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, common land does bring a different kind of challenge, doesn''t it? It always does, it always has done, because of, as you say, the large numbers of interested parties, and it is a challenge, sometimes, to bring them together in order to bring schemes or bring opportunities forward, but we are keen, again, to be flexible in that space, and optional schemes are ones that we want to encourage those particular kinds of farmers to be involved in. I don''t know if you want to add about the habitat.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1497&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.479226', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771812', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9531135527293b2fbd23', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thanks for that. And I just want to explore some of those, because I think there are several bodies related to the whole election process who can acknowledge that a reduction in that time frame might be advantageous in some ways, but then there are serious concerns being voiced by the same people about those who might be more vulnerable, disabled, in circumstances where they''re threatened by domestic abuse, and they don''t want their data being put out. And so there are some real issues around safeguards around this, and some anxiety from One Voice Wales, for instance, and our local authorities, who can see both sides of the coin. And we know that the Electoral Reform Society also believes that, whilst we might need some change, we need really strong safeguards around that. So, where are you on that? And what engagement has been had with those harder-to-reach communities on the ones that are taxing people a little with regard to safeguarding?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=859&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.818723', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769797', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('955ab5950c95b3b1f18d', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Thanks, Katrin. I expect, Elfed, most of your—. Yes? That''s fine, thank you. I''m going to bring Huw in in just a moment. I know there''s a lot to get through, but if we could try and keep responses a little tighter, just so we can get through everything we need to, that would be appreciated. Huw.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=9897&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.131647', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777592', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('955db7332d1c7fe0da0c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'In terms of the CPO, it was very paperwork heavy, so, lots of stages throughout the process and lots of documents that needed to be served—you''re talking bundles at times—so, I think cutting down on the number of steps in the process would be useful.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9562936540bd2d8c83ec', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'No, no, absolutely.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Francesca O''Brien', '', '12190', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=11035&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; Opposition housing leads', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.494147', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775031', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9581d219d1d2c656c240', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Diolch, Lywydd. The issue of parking at the Maelor hospital in Wrexham is raised with us time and time again, and some residents have told us that they''ve arrived sometimes up to three hours before an appointment just to find a parking space. And that will be contributing to the 27,000 missed appointments at the Maelor last year. We''ve raised that repeatedly with the health board, alongside other local Members as well, the council and residents, too, yet there are still no concrete plans to tackle the problem. My own mother is currently undergoing cancer treatment, so I''ve seen first-hand the extra stress that that causes for people who are already worried about their health. I welcome the Government''s commitment in the supplementary budget to boost funding for the NHS, and I also hope that this budget passes to allow that support to happen. First Minister, do you agree that accessing healthcare should begin at the hospital entrance and not with a queue for a parking space? And what discussions is the Welsh Government having with Betsi Cadwaladr to ensure that this long-running problem is finally treated as a priority?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Carrie Harper', '', '278', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=657&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.241740', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767466', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9597179f7ab60716c534', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Okay. Thanks.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=3395&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.291820', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775313', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('95a3faebf8714bb4bd91', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Yes, thank you, Chair. Just to make it clear, it wasn''t a criticism about how you have been engaging and the work that''s been going on. I''ve had excellent experience of that, just to give you that feedback. But it just didn''t feel very measurable, and I just wanted a bit more meat on the bone there in terms of the £309,000, as the Chair mentioned.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('95b6dafbb33d90d93022', 'press_release', 'Welsh Government — Announcement', 'Statement from the Deputy First Minister: Visit with the Prime Minister', 'Statement from the Deputy First Minister: Visit with the Prime Minister
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('95b6e5169c59ad45cd99', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Well, we do legislate bilingually, of course, and the resources are available to ensure that people know that the Welsh language version is at the same level as the English version, and that they''re available. Probably the most important thing is that we go public with all of this to ensure that people—. We don''t have to spend a great deal of money to do it, but that we take every opportunity to say, ''Well, look, this legislation is bilingual. If you want to turn to the Welsh language, do so, you''re more than welcome to do so; there''s the same authority behind the Welsh version as the English version and they''re equal.'' That''s an important message because even to this day, I know that people believe, for some reason, that there isn''t the same authority behind the Welsh version as there is for the English version. It''s hard to believe, but that''s what people think. So, it''s up to us, at every opportunity, to explain, ''Well, we are a bilingual legislature, the two languages have equal status and so, if you wish to use the Welsh language, please do so.'' In the same way, the use of the Welsh language in the courts, that''s part of my role as well. Sorry—', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4486&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.876197', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770580', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('95d44d8a32c4db7a0138', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Good morning—oh, good afternoon. We''ve heard a lot about capacity already, so I won''t dwell too much on it, but it''s fundamental for us to get underneath the capacity question, really. So, I would like to know how the Government is preparing to meet that capacity shortfall, if you like, because there seems to be a bit of ambiguity about capacity—we might have enough, we''re going to look for more, you know. So, what firm steps are you taking to firm up capacity, and do you believe, then, that you will have the capacity to deliver against your key priorities that are coming forward in legislation?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peter Fox', '', '4787', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=2358&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.483409', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770446', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('95dd70fa388ba9ca1bd8', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Just while we''re focusing on some of the numbers, Chair, if it''s okay, can you explain the increases over the next three years in the depreciation charges, which grow very significantly over three years?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=594&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.990211', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777389', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9605ba4205ad975efb02', 'committee_transcript', 'Public Accounts and Public Administration Committee', '2. Scrutiny of Accounts - Senedd Commission 2025-26: evidence session', 'I think, just from a process point of view, if you were to give the money back into—. This is the thinking behind—. From memory, the Finance Committee would have thought that if the money goes back to the consolidated fund then there''d be a potential overspend in the Chamber, then you''d have to have a supplementary budget to bring that back out of the consolidated fund back into the Senedd Commission budget. It creates more time, and with timing of budgets it was more prudent to be able to move things within the year to make sure that it happened, rather than to go through a process that is rather convoluted, whereas you get to the same place as you would have in the first place.', 'https://record.senedd.wales/Committee/16319', '2026-10-05', 'Peredur Owen Griffiths', '', '8579', '', '', 'Public Accounts and Public Administration Committee', '2. Scrutiny of Accounts - Senedd Commission 2025-26: evidence session', '16319', 'http://www.senedd.tv/en/16319?startPos=3405&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session; supplementary budget', 0, '2026-10-07T13:41:43.108565', 'https://record.senedd.wales/XMLExport/Download?meetingID=16319&xmlDownloadType=EnglishTranscript#775755', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('96309d2d43082b6240ca', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Bore da. My name''s Osian Jones, I''m the empty homes officer for the Isle of Anglesey County Council.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Osian Jones', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4290&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.352066', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775183', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('96531ecb56dd7dafaaa1', 'plenary_transcript', 'Plenary', '3. Business Statement and Announcement', 'Trefnydd, can I request a statement from the Cabinet Minister for Local Government, Housing and Planning on the extent of houses in multiple occupancy in Bangor Aberconwy Môn being used by Government-contracted organisations to house people via Home Office schemes? And what assessment has been made of the effect on local housing costs and supply for constituents on waiting lists, some of whom have been waiting for over a year?', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'John Clark', '', '12169', '', '', 'Plenary', '3. Business Statement and Announcement', '16262', 'http://www.senedd.tv/en/16262?startPos=8045&l=en', NULL, 93.5, 'High', 'digest', 'hmos_and_standards', 'Private rented sector', 'Housing minister; First Minister / Cabinet', '', 'houses in multiple occupancy; multiple occupancy', 0, '2026-09-26T13:20:19.600635', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#770980', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('965392fc1f511d96ed51', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Could I just come back on that? As a Finance Committee, we''d like to see what the economic benefit is, and when could we, as a committee, see that?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=9837&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:52.057857', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774424', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('96cb010b8bb410c17bfb', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you, Cabinet Minister. I welcome the Welsh Government''s commitment regarding warm homes and energy efficiency. We know that a warm, safe and affordable home is fundamental to a healthy and happy life, yet fuel poverty remains a significant challenge in communities throughout Pontypridd Cynon Merthyr. Rhondda Cynon Taf council has noted that around 65 per cent of homes are energy inefficient, which reflects the area''s older housing stock, while fuel poverty continues to disproportionately affect low-income families, disabled people and older residents. How will the Welsh Government''s plans benefit residents in Pontypridd Cynon Merthyr? And what action is being taken to ensure that work to improve energy efficiency will help to reduce bills, improve people''s health and well-being and ensure a permanent reduction in fuel poverty? Thank you.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sara Crowley', '', '12150', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=5662&l=en', NULL, 71.5, 'Medium', 'digest', 'energy_efficiency', 'Property & energy', 'Housing minister', '', 'Warm Homes; fuel poverty', 0, '2026-10-10T14:39:12.526776', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776693', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('970309428a96b4f62972', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '''Planning Policy Wales''', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', '', '', '', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 60.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'Planning Policy Wales; planning policy', 0, '2026-08-04T14:03:05.156856', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768140', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('971208620eb103de5884', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'Thank you. I welcome the Cabinet Minister''s announcement of a 30 per cent cut to business rates for hospitality and leisure businesses. This will be a vital lifeline to small hospitality and leisure businesses and has already been welcomed by businesses in Ceredigion Penfro. These small businesses play essential roles in our rural and coastal communities, protecting local jobs, strengthening local economies and building lasting prosperity. I''m happy to see that this announcement extends beyond just pubs, clubs and live music venues, like in England, to support visitor accommodation and leisure businesses like hotels, cinemas, theatres, museums and gyms. With this in mind, can the Minister explain what she anticipates now will be the practical impact of these measures for towns and high streets across Wales, as well as in our constituency of Ceredigion Penfro?', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Anna Nicholl', '', '12178', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=5515&l=en', NULL, 99.0, 'High', 'digest', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', 'First Minister / Cabinet', '', 'business rates; visitor accommodation', 0, '2026-09-19T12:39:17.221935', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769623', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97214416c8e384252aec', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Yes, just to update. The volunteering policy existed in 2015. In the last couple of years, there was a voluntary sector cross-sector leadership group that looked at that volunteering policy. It concluded that it needed to be updated, and so, last year, ''A new approach to volunteering'' was published. The conversation we''re having now is around what does that look like over this Senedd term, given the Ministers'' and the Government''s commitments. And as the Deputy First Minister has said, that conversation is happening with Cabinet shortly and with officials. But I just want to put on the record the recognition of that work.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97365d97e68e6ad99e65', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I think—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1681&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.158944', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777277', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97504ee4f4c01ecdcedb', 'oral_question', 'Oral Question (tabled)', 'OQ64597', 'What assessment has the Cabinet Minister made of how the rights of children are protected when families are placed in temporary accommodation?', 'https://record.senedd.wales/OrderPaper/OralQuestions/30-09-2026/', '2026-09-23', 'Lyn Ackerman', '', '', '', 'Casnewydd Islwyn', 'Plenary', 'To the Deputy First Minister and Cabinet Minister for Social Justice and Equality', '', '', '2026-09-30', 45.0, 'Low', 'dashboard', 'homelessness', 'Housing system', 'First Minister / Cabinet', '', 'temporary accommodation', 0, '2026-09-24T06:33:44.167231', 'orderpaper:2026-09-30:OQ64597', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97520a327c8825f75c5d', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'As my colleague Huw Thomas said, the Labour Members will be voting against the supplementary budget today. I want to be clear that I take absolutely no pleasure in this situation. This has always been and will always be about getting more funding for children and young people with ALN in Wales.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97a575195032da7786be', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes, I think we''re pleased that the Welsh Government are addressing all these issues. They have a working group that they have set up and they are taking feedback and information from electoral registration officers. They''re responding to those concerns. I think the primary driver for the concern is around the timescales for the legislation and then the delivery of the changes to the electoral management software systems. So, I think if there were to be any delay to the regulations, then I think that''s where the most significant challenge to delivery for the May 2027 elections would come.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=440&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session; working group', 0, '2026-09-18T11:33:48.740692', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769825', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97a65ac953be1259ba3e', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Yes, you''ve got to give me time.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', '', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26310&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.844239', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#768000', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97a7c3b450eab015b29c', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'It''s a change to be on this side of the table, Chair.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', 'Cabinet Minister for Rural Resilience and Sustainability', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=61&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.274279', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771837', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97b06da7d113d08f0967', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think that, in terms of the benefits, if this is to be rolled out before the local government elections next year, you have to have a 28-day period. You''ve run out of time to have a 60-day period without it impacting detrimentally on the delivery of the local government elections next year. With a 60-day window, the earliest we''re looking at notification letters going out—. Given that we haven''t got legislation in place yet, the EMS suppliers haven''t got what they need, the Electoral Commission have had to produce guidance before the legislation has come out, again, we''re in a position where January, early January is the absolute earliest we can look at notification letters going out. A 60-day window would then push you into those people being added to the register during the notice of election period. So, you wouldn''t have poll cards for those people until later, which, again, if we''re introducing people to a democratic process and then putting barriers in their way or sort of not giving them a good first experience is detrimental there. So, having a 28-day window in this case to allow you to have those people on the register by the 1 March notice of alteration is crucial to make sure that they''re included in the data that electoral administrators will send to printers to administer that election.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97c6bc6ae902eb9c3804', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Thank you. One instance I''ve got is homes for older people and care homes. What I found in the local election was, I looked in one of the care homes—and my mother was in that care home, and she actually voted. Now, my mother had dementia. My mother didn''t even know me, and I asked the question, ''Well, how did my mother vote?'' Everybody in that care home had voted, and 50 per cent of that care home were people with dementia. So, I asked the question—and there was a police investigation into it—and the answer I got was, ''Your mother had a moment of lucidity.'' Now, my mother didn''t know me for two years. Now, I don''t know what lucidity she had and who she voted for, because, obviously, that''s private. But what safeguards are in place for that not to happen? Because, obviously, if everybody''s going to be able to vote, which I don''t not agree with, but, if everybody can vote, what safeguards have we got in place that people aren''t abusing the system for care homes and for situations like that?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8395&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.940133', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774434', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('97d2e45206ddfce07d2e', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Yes. Only because that''s just come out this morning. So, not to put you on the spot, but it just—', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Francesca O''Brien', '', '12190', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8318&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; Opposition housing leads', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.903926', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774450', NULL, NULL, NULL, NULL);
