INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9a90dd8d855e8871d683', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'Whilst I''m grateful to the Government for the advance notice of these legislative priorities issued via the media this morning, surely Government announcements, especially when they relate to Bills to be introduced in this place, should be first made in this place, out of respect for all Members of this Parliament. I would encourage the Government to reflect on that and treat this place with the respect that it deserves.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9a9ee822f6370515fbb3', 'plenary_transcript', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', 'Thank you very much for your question. Just to be clear, we are not asking taxpayers to pay for remediation work; we are asking the developers to proceed with that remediation work.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', '16262', 'http://www.senedd.tv/en/16262?startPos=18861&l=en', NULL, 71.5, 'Medium', 'digest', 'building_safety_and_leasehold', 'Property & energy', 'Housing minister', '', 'building safety', 0, '2026-09-26T13:20:21.065015', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#771086', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9aa36fb49a49dc0f5c12', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Sorry, go on, Peredur.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1681&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.160331', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777278', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9af045fbfbe0b8740e80', 'oral_question', 'Oral Question', 'Oral Question - OQ64420', 'What action is the Welsh Government taking to meet its social housing targets?', 'https://record.senedd.wales/OralQuestion/64420', '2026-07-08', 'Laura Anne Jones', '', '4562', '', 'Sir Fynwy Torfaen', 'Senedd (tabled business)', 'Tabled on 08/07/2026', '', '', NULL, 40.0, 'Low', 'dashboard', 'housing_supply; social_housing', 'Housing system; Planning & place', '', '', 'housing targets; social housing', 0, '2026-08-04T14:03:42.308411', 'record_search:type=oral_question:query=housing', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9b00ca225b686741cf82', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Diolch. Perhaps one last question, unless anyone else has anything they wanted to pick up at all. I''m conscious that, in terms of the pressures being faced, you''ve generally referred to general inflation and the impact of real-terms cuts. Are there any specific demand-led pressures that are on your horizon that you think will have a particular impact on your budget planning for next year, whether it be parts of social care services, or parts of the health service, perhaps, that are causing you concern, which then you''re having to adjust your budgetary assumptions for at all?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=10439&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:52.146172', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774359', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9b1e081fc7f8fc71a9ff', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Bethan, yes. So, my final question—.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2777&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.299283', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774177', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9b467eeb251857166257', 'plenary_transcript', 'Plenary', '1. Questions to the Deputy First Minister and Cabinet Minister for Social Justice', 'Minister, the focus in this Chamber thus far has been on the cost of childcare plans, rather than on recognising childcare as a critical lever for reducing both poverty and inequality. Childcare is a complicated issue—just ask any parent attempting to fill out an eligibility form—but it''s essential economic and social infrastructure. And this is where we, across the political spectrum, must scrutinise your work. This policy will reduce child poverty and support women who''ve been forced out of the workplace by the motherhood penalty, which impacts everything from your pay packet to your pension. We saw on the doorstep how many people cared about this issue, which is why they voted for Plaid Cymru in their droves.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9b566bdd90539ea39d29', 'plenary_transcript', 'Plenary', '2. Questions to the First Minister', 'I shall share with the Member a copy of our programme for government again, which emphasises the way that my Government is dealing every day with the issues that we face on health, on education, on housing, on child poverty, on helping the Welsh family farm. That is the focus of this Government, whilst at the same time focusing on an ambition that we have for Wales. There''s an obsession on the Reform benches with talking Wales down. My discussions with Andy Burnham have all been about talking Wales up and how we can seek co-operation to make sure that we grow the Welsh economy to bring real prosperity to all parts of Wales, something that Reform are clearly not interested in.', 'https://record.senedd.wales/Plenary/16264', '2026-09-29', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '2. Questions to the First Minister', '16264', 'http://www.senedd.tv/en/16264?startPos=1104&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-10-03T13:38:58.082367', 'https://record.senedd.wales/XMLExport/Download?meetingID=16264&xmlDownloadType=EnglishTranscript#772854', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9b913565f4c6f2a6baa5', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'Cabinet Minister, thank you for your statement today. I do share some of the concerns raised by our Reform colleague in terms of the way in which this information has been disseminated to Members of the Senedd. I think it is right and proper that in the vast majority of instances, information is shared in this Chamber first before being released to the press, just to show some respect to the Chamber itself and the Members within it.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9bc1bee415ae9542d9dd', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'May I come in on a couple of those points? Just to follow on, I thoroughly agree with all of those points that Andrew has made around compulsory purchase. It''s slow, legally complex, costly, resource intensive and it needs very specific expertise. Often, because we don''t do so much of it, particularly compulsory purchase orders for housing need rather than for the Town and Country Planning Act 1990 and the development of an area, then the expertise in legal services and in individual local authorities diminishes. Those legal teams have other priorities, so having some continuity within those teams and those skills and a bit of confidence—there''s a lot of it that comes down to confidence—and having central support, such as the industry experts that we''ve got in Wales, greatly helps with easing some of those problems. But it''s something that''s used to target long-term, seriously poor properties that are eyesores and a real blight on the communities.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9be5237ef67e0589d589', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Yes.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=1304&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.967927', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774242', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9bf7d87a9eb3efad9802', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'So, you said earlier you''re an economic regulator, and I''m just trying to understand, you have this price review every five years, and how do—? Obviously, in my mind, that price review is about reviewing value for money for customers. How do the environmental objectives that you also have a responsibility for fit into that?', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Paul Rock', '', '12176', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=1950&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.975512', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773206', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c0a8322c3c801e9a7be', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'I''ve got a point to make about what you''ve just said, which is that we''re not supposed to be here as Members of parties, we''re supposed to be here to scrutinise the Minister. So, I''d respectfully just ask you to think about that and not refer to your political party or conferences. Thank you.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jane Dodds', '', '4983', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2023&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.781870', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771176', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c28b20f61b200e75b3d', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Yes. Just at the outset, just to explain the approach that we took, one of our independent members on our advisory panel is a former independent adjudicator for higher education complaints. She assisted us with this work, and we started by engaging with the Welsh Government, as the committee asked us to do. That has been helpful. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c2fcc66aaf420bc405f', 'consultation', 'Senedd — committee consultation', 'Priorities for the Local Government, Housing and Planning Committee', 'Priorities for the Local Government, Housing and Planning Committee
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c3138e42a7a39e69c1f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Thank you. We''ve probably covered some of the funding issues off. We''ve got three issues left. Do you want to ask a question, Marc?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16738&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.921825', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775560', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c33815d61de7f94d601', 'committee_transcript', 'Petitions Committee', '2. New Petitions', 'Thank you very much, Chair. So, I''m sure that all Members will be aware that red squirrels are in danger of extinction in Britain and that they''ve held that status for a number of years now. And while grey squirrels have developed some immunity to the squirrelpox virus, it remains fatal to red squirrels. This is not the first petition that the Senedd has received on this issue. There was a previous one in the sixth Senedd from the same petitioner, which gathered just over 11,000 signatures and was debated in Plenary in September 2023.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c405acc37d75dd6af70', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Thank you, Chair, and thank you, Peredur. Just very quickly, we''re at the point of developing the design to RIBA 3 status, so a fairly detailed design now that allows a cost plan to be developed, and that''s in the next few weeks. And we''re also developing our decant options, so we''ll have a decant strategy. All of that in the next month or so is going to be pulled together into a full business case, and our legal advisers are working on a draft development agreement. All of this is going to come together in December for presentation to the committee and, as has been said, we''re in the process of setting up briefings for all the groups on all of those elements, where we intend to show Members where we''ve got to on the design and where we''ve got to on decant, and take some feedback there. Obviously, there will be a debate on the budget as well because a large element of the Commission''s budget interest is around Bay 32. So, there will obviously be full engagement by the department there.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Ed Williams', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2283&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.259090', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777512', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c4175c8b3daeca06b7d', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you so much, Deputy Presiding Officer. Minister, I listened to your response to the Reform Member, and, before I go into my questioning, if you want to divert your attention for surgical hubs to the Royal Gwent in Newport, you will not hear any complaints from me.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c6b0c933c6049b606b9', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'In terms of the empty homes grant, we''ve been very, very successful in Caerphilly in the administration of it. One thing I would find as a barrier, which is touched upon in many of our other groups, is surrounding second homes. So, second homes are, obviously, predominantly very problematic, particularly in our borough. What we do find is, because a stipulation of the grant is that the property is unfurnished for 12 months and empty for 12 months—. What we find is that many properties that are either second homes or deceased estates, because these properties are furnished and, in many cases, furniture is removed at the very last minute at the point of sale, these properties are then purchased but are unable to access that funding through the empty homes grant service, which means that, obviously, support isn''t available for that person who''s actually bought a problematic empty property. And due to the cost-of-living crisis, with materials and labour actually increasing, that £25,000 now, which five years ago may have been sufficient, we''re finding is not enough to bring these most problematic empty properties back into beneficial use.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'James Wagenaar', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4836&l=en', NULL, 241.5, 'Critical', 'immediate', 'taxation_of_property; second_homes_and_short_term_lets; housing_supply; committee_scrutiny', 'Housing system; Planning & place; Tax & finance', 'Sector bodies', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty homes grant; empty properties; empty property; evidence session; inquiry; second homes', 0, '2026-10-07T06:31:25.446972', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775036', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c6d238f462a0fd308cc', 'calendar', 'Senedd diary (senedd.tv)', 'Climate Change, Environment, Sustainability and Rural Affairs Committee — 30 September 2026, 09.30', 'Climate Change, Environment, Sustainability and Rural Affairs Committee meets on 30 September 2026 at 09.30 in Committee Room 4.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9c8732353c5961a797c3', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Yes. I think there''s a lot, because, under the legislation, prevention is one of the key requirements for setting a new strategy. So, a lot of the conversations we''re having now—. The importance of prevention came up quite strongly in the review conversations back in July, so that''s going to be feeding into the new strategy. But a lot of the conversations we''re having now are across Government. We''re starting to talk to colleagues around what they can do to tackle this agenda and what role they can play. But prevention is a really key part both of the commitment in the programme for government and also a key part in the legislation. As the Deputy First Minister said, that strong theme around supporting men and boys, and the Sound campaign, is a really important part of that approach.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Andrew Charles', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5797&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee; programme for government', 0, '2026-09-25T06:30:36.157787', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771292', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9ca47421dd3ab063a155', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. The final topic we''ll be going on to is the voluntary sector. Just to check now, would you be able to stay just a couple more minutes?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6787&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.272674', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771250', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9cf0ff5ea7c065b4ed89', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Not directly, no.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2701&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.685735', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771877', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9cf5f739eb30f59f16b7', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Sorry, Chair, I have more questions on data.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2321&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.044348', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769867', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d06a259d687c2998ef8', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I can only speak on Morriston, where I live, in great detail, and Swansea in much less detail, but there are chapels all over the place. The one thing that south Wales has got, and I''m sure north Wales as well, is lots of chapels. Their congregations have collapsed and these buildings are now left. And there are different people taking them on for different uses, but do you support housing associations and others when they come to do it? It can be expensive to change a chapel around, much less so a pub, which is, effectively, especially the smaller pubs, really just a big house.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6698&l=en', NULL, 201.2, 'Critical', 'immediate', 'taxation_of_property; social_housing; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; housing associations; inquiry', 0, '2026-10-07T06:31:25.748378', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775465', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d1179e6ee637d037c12', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'I''ll come back on that. So, normally, with the probate issue, that comes under class F of council tax. So, the Welsh Government has made recent changes on council tax to remedy that. So, it used to be that, once a person died, council tax liability stopped until probate was granted and then for six months—it expired after that. So, the Welsh Government has made changes to it so that council tax becomes payable, I think, over 12 months from the point that probate has been granted. It''s a fairly small number within local authorities overall on the number of empty properties.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Andrew Lavender', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=1600&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.008714', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775345', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d12b6e1f1bc6b248980', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: Wales and the United Kingdom', 'So, that is not an argument that Wales could not trade with England if it became independent, clearly it could, but it does demonstrate the sheer scale of the economic relationship that already exists in the United Kingdom. And that relationship operates with a common currency, a common monetary system and no exchange rate between Wales and England. We use sterling. Monetary policy is set through the Bank of England of the United Kingdom as a whole. A business, say, in Tenby buying goods from Birmingham does not have to think about currency conversions. A worker living in Powys and earning a salary across the border doesn''t have to think about exchange rates. A pension does not change currency when somebody moves from Colwyn Bay to Chester. These things are easily taken for granted precisely because they happen every day.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d13e9a61851004a45dd', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'We''ll reflect on that in the wash-up.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=10008&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.149406', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777601', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d2159718b1d62082ab2', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I''m sorry to interrupt you in full flow.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5247&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.050581', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770548', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d242ac49de82d581434', 'other', 'Statement of Opinion', 'Statement of Opinion - OPIN-2026-0528', 'This Senedd: 1. Notes the efforts of successive governments to tackle fuel poverty and improve household energy efficiency, ...', 'https://record.senedd.wales/StatementOfOpinion/528', '2026-06-16', 'Vikki Howells', '', '5107', '', 'Pontypridd Cynon Merthyr', 'Senedd (tabled business)', 'Tabled on 16/06/2026', '', '', NULL, 35.0, 'Low', 'dashboard', 'energy_efficiency', 'Property & energy', '', '', 'fuel poverty', 0, '2026-08-04T14:04:11.001818', 'record_search:type=other:query=energy efficiency', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d3a872af1c494a1f9a8', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Well, it''s something that we haven''t actually addressed firmly yet; we''ve thought a fair bit about it. There is nowadays, of course, a tendency to use secondary legislation frequently in every legislature. That''s just the way things are. As for the balance, well, secondary legislation is vital in order to get the nuts and bolts in place for things to work. And so we are mindful of the need, again, not to overload that particular sector so that it impinges upon your work. Having said that, it is a fact today that modern legislation means that there will be a considerable amount of statutory instruments and secondary legislation coming through, and that is something that one cannot prevent in a way; it''s a necessity. I don''t know if—.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1197&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.246517', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770357', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d63e4ab0560cf32daf7', 'calendar', 'Senedd diary (senedd.tv)', 'Legislation Committee — 5 October 2026, 13.30', 'Legislation Committee meets on 5 October 2026 at 13.30 in Committee Room 1.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d6e5b8ca6784ae9be50', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''d be interested, if you wouldn''t mind keeping us up to date, in the conversations you''re having with those other Cabinet Secretaries. This area that we focus on, obviously other committees across the Senedd do as well, so it would be quite useful if you could keep the wider Senedd updated on that discussion as it goes on. I''ll bring Vikki and Andrew in, and then I''ll come to you. Thank you.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4733&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.918345', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771780', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d79d21e05038b29e717', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think that will vary between local authorities. Council tax is the obvious one. We use housing tenants records, but, for some local authorities, that won''t be possible because they''re outsourced. So, there are going to be some difficulties. We used adult social care data, which was very good in Powys, because we''re a large rural area and take up quite a large portion of Wales. Employee data was very good, because quite a lot of our staff work within the county. That won''t be as useful for others in the small urban areas. Sometimes, I think they''re going to need to start those discussions and find out what—. I''m not sure if I can recommend, because I don''t know the quality of some data sets in other local authorities. But looking at the standard that came across from the pilots, we all used two or three core sets, as I said, like council tax, education records, and it''s then looking at what else might be strong within your council, because the EROs have to have faith that the data that they receive is of good enough quality.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Sandra Matthews', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=6863&l=en', NULL, 109.2, 'High', 'digest', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; evidence session', 0, '2026-09-18T11:33:49.677730', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769963', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d98a6bc748191e637b4', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Thank you.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=1564&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.002481', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775600', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9dade9bd53e3592531fa', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thank you. I can take this question. I think one of the things that I think the Welsh Government have flagged in their correspondence with the committee and in their explanatory memorandum for the regulations is, firstly, about the benefit of reducing that minimum time period—sorry, the minimum frequency—for this first year of implementation, which is aimed, they''ve said—and we agree; this is important—at reducing some of the administrative challenges in this first year for EROs.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e011a2506749f715bf5', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'The Welsh Government will be held to account by the regulator in the same way as the bodies that are in Wales are held to account by the EHRC. It is not for the Welsh Government to issue that guidance.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=3357&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.933434', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771193', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e2f0fc183b392cb9eef', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Yes. So, there are a couple of things there. First is complaint handling. I think it is a frustration to us that we continue to see—and this, I think, is probably true particularly in health—we continue to see complaints coming through to us that we have to deal with where the health body has not dealt with that complaint properly in the first place. Now, that is entirely avoidable. They should be able to deal with those complaints properly, do proper, objective investigations and come up with robust answers for the complainants. Now, if they''re not doing that, we have to redo that work. So, I think complaint handling and improving the standard of complaint handling across all health boards is definitely needed because that would avoid a significant number of complaints that come through to us. And because they''re not well investigated in the first place, we have to reinvestigate. So, that''s public resources being used twice, and that is entirely avoidable.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e2f79e27ff0b0ead2d6', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch yn fawr. Thank you.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=7704&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.390107', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771764', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e43921e03efbe3ae332', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Just to follow up, would you be able to provide a bit more detail on the discussions you''re having with your UK counterparts around this as well? Are they constructive conversations? Because, obviously, like you said, it''s a really big challenge, and the UK Government have a big role to play in that as well as us. I was just wondering how that dynamic is working in those conversations.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4409&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.867178', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771855', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e4ba3086b5b78ae6e4f', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I don''t know off the top of my head. I think it''s roughly £1 million included for each additional accommodation at the moment.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2567&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.305638', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777295', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e601c965f9e44f9b5a7', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'Can you confirm that you understand that the money raised from the visitor levy is ring-fenced for visitor purposes, not to pay debt or anything else?', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Huw Thomas', '', '12156', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=13207&l=en', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'visitor levy', 0, '2026-08-04T14:03:16.895860', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767093', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e60a7e0fb9c9c8c1db0', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'You said you''re meeting the planning Minister next week. In the UK, the UK Government some years ago changed the planning system in England to have a presumption on permitted development rights for redundant buildings to be converted into housing, or office space, as such, to create economic activity and to meet some of that pent-up housing demand in rural areas. Are you supportive of such a change here in Wales? I appreciate it''s not your portfolio—', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4842&l=en', NULL, 63.2, 'Medium', 'digest', 'planning_system; committee_scrutiny', 'Housing system; Planning & place', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; permitted development; planning system', 0, '2026-09-25T06:30:34.936747', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771790', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e8157f17470c22e5d0b', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Yes, certainly. Obviously, as we''ve discussed in this committee in the past, there are differences in terms of powers. We know, for example, that one of the most powerful levers that would be able to lift families out of poverty is the welfare system. We know that the welfare system as it currently stands isn''t fit for purpose, but we don''t have those powers. But, we do think that, within the powers that we currently have, there are things that we can do. So, there are levers that are within our powers. We are certainly going to look at the international picture to see what works. Cynnal is a perfect example, where, of course, we''ve seen how that has made a difference in Scotland. We don''t have the power to roll that out in the same way as has been done in Scotland, but we hope that, through the pilot that we''ll be holding and then by ensuring that we evaluate the impact that that has made, that that will be able to show the way forward for us in terms of how we can tackle poverty and how the targets could reflect the kinds of actions that we can take. But, certainly, officials are engaging with other nations and regions.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=672&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.625714', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771173', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e89dcdc566cada7a8d8', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'I''m just going to stray slightly off what I''m doing. What I''m getting when I''m speaking to people and generally just being out in communities and talking with organisations is that they would benefit from a three-year plan of having secure money, because it would help them budget better. In this preventative agenda, would that be something that you would be looking to consider? Is it viable in any way, so people can feel a bit more assured that, down the track, their businesses or their organisations that are helping preventative and different things are much more secure and they can organise better and maybe get better outcomes?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Lyn Ackerman', '', '4967', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=8439&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.840866', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774295', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9eafae6c7892e4a591e7', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'Diolch yn fawr. I remind the Member that she voted against a supplementary budget that was proposing to roll out matters like childcare that were really important to her.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9eb022d5bee177f28674', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Would you like me to take that?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3980&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.514457', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777684', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9eb238eb4fafa0fb7e91', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'At its heart, the aim of this programme is building a better future for Wales. Guided by the principles of the Well-being of Future Generations (Wales) Act 2015, we have brought together our well-being objectives and our programme for government into one single framework—a framework that sets out the future that we want to build and the actions that we will take to deliver it.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9eb2981cecb717f2e885', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'We''ll be done in time—', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6799&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.276856', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771252', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9eb65a41852c9b97dc97', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I think there''s always a balancing act in terms of developing a legislative programme, and what you''ve got here is a series of pieces of legislation. Some of those pieces of legislation have been a topic of some work already, and there have been discussions in the previous Senedd on some of these topics. There''s also a recognition that—and this maybe comes on, in part, to our approach to legislating in certain areas—more focused, shorter Bills are of of clear benefit, and would allow prompt action in areas. So, for example, you will be familiar with the Plaid Cymru manifesto on a range of areas around housing and planning. There may well be the case that there would be further housing legislation during the four-year time, but we begin with a short, focused Bill around renting. So, that''s the approach we''re trying to take.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=395&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Legislation Committee; legislative programme', 0, '2026-09-22T11:55:09.106257', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770370', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9ebda596b4ec9efa46d7', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I''d be happy to. Lia has described how we''ve upped our presence and raised our game in Wales. I know you''ve had conversations with others around the performance of Welsh water companies and what we are doing to hold them to account.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9ecca57a48c20265b84c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Marc, you''ve got a question.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1287&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.880445', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769865', NULL, NULL, NULL, NULL);
