INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a460ae97d9bc3bfca6a8', 'committee_transcript', 'Public Accounts and Public Administration Committee', '2. Scrutiny of Accounts - Senedd Commission 2025-26: evidence session', 'I think, going forward, one of the things, as Chair of the Finance Committee in the last Senedd, was setting and scrutinising the budget of the Electoral Commission and the Welsh element of that, and part of the scrutiny in doing and setting that budget was around this aspect of, ''How do we explain to people what the system looks like and that it is, effectively, the same as the regional system as was before?'' But people didn''t quite understand that, even though it had been around for 25 years. But as part of the joint working, I suppose, between the different organisations—and you''ve got to remember what the Commission is responsible for and what the Electoral Commission, as well as others, are responsible for—the Electoral Commission did send out a booklet to every single household to explain—', 'https://record.senedd.wales/Committee/16319', '2026-10-05', 'Peredur Owen Griffiths', '', '8579', '', '', 'Public Accounts and Public Administration Committee', '2. Scrutiny of Accounts - Senedd Commission 2025-26: evidence session', '16319', 'http://www.senedd.tv/en/16319?startPos=908&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-07T13:41:42.747109', 'https://record.senedd.wales/XMLExport/Download?meetingID=16319&xmlDownloadType=EnglishTranscript#775619', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a46da4e63cc7b4019480', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Adrian, did you want to come in?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1825&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.351632', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770386', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4baa4d45cb7da187ada', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I assumed Niamh was directing the question at me.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Richard Irvine', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6326&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.152622', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772122', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4bd0524ae4ee81a5277', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Great, thank you. And then just on staffing, just obviously because it''s such a big part of the budget—it''s 70 per cent of the Commission''s operating revenue expenditure, which is a lot—could we ask for more details in the budget? So, I know that the public accounts committee asked for a breakdown by department. Can we ask for that in this budget we''re reviewing as well?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Cai Parry-Jones', '', '12174', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1572&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.125347', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777249', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4d2bdbbeacdcaefe3d8', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I think the question, ''How did we get here?'' is not just a question for Dŵr Cymru—it''s a question for our economic regulation of the sector as a whole. It was exactly one of the questions that the Independent Water Commission was tasked with looking at. Its report in July of last year pointed out, quite painfully I think, the gaps, overlaps and inconsistencies in the fragmented regulation that we have in Wales and England. It recommended wholesale changes and reform to correct that, including devolution of independent economic regulation to Wales and Wales-specific national system planning. The solution to the problem is tied up in the reform process. But I think the legitimacy of the reform process also depends on the public seeing what they''re getting for their money. Improvements have to be delivered alongside the reform so that there is, collectively, public consent for the changes that we need to make. That''s our twin approach for the next couple of years.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=1330&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.903889', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773194', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4d563ae93a60d5ce32b', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'I''ll take the first part. Thank you for the question. The former executive director left to move on to different things in her life—and we wish her well—but it became evident at the time that the modernisation agenda was becoming more important, and also innovation within the sector. It was important for us, as Audit Wales, that we looked at how to innovate.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4e97d15e521c221bddc', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'For any company, the remuneration decisions for its executives are a matter for the remuneration committee of its board. In this case, that would be Glas Cymru, yes.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3463&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.195643', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773304', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4e9f3ac156284282463', 'plenary_transcript', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', 'I appreciate the update and that this Government is taking this work seriously to better support impacted residents. For years now, residents have been afraid in their own homes and have felt that this issue has not been given the attention it deserves. Despite receiving assurances that their property was safe when they moved in, one resident in Cardiff has shared that they face a £3,000 cost for a waking watch, which costs £15,000 a week between 96 flats, and the management company are having to find £150,000 to install fire-detecting equipment. Without the necessary improvements, residents have faced the possibility of being made homeless as their homes aren''t safe to live in. I welcome the Minister introducing financial support as an interim measure while remediation works are carried out. How will the Minister make sure tenants don''t have to pay out of pocket for remediation work again? Diolch.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Nick Carter', '', '12173', '', '', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', '16262', 'http://www.senedd.tv/en/16262?startPos=18662&l=en', NULL, 99.0, 'High', 'digest', 'building_safety_and_leasehold; homelessness', 'Housing system; Property & energy', 'Housing minister', '', 'building safety; homeless', 0, '2026-09-26T13:20:21.035889', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#771083', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4edb171563b5ae923a2', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much for that question and for an opportunity to explain some of what was contained within the written statement issued on Monday. You''re exactly right, we want that target of 20,000 to include vacant properties above shops on our high streets, and this will be part of the work of the town centre taskforce, of course, and how we accelerate the process to allow more vacant properties to come into our housing stock.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5203a41cbf11140581f', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'And just to add to what Chris said there, there''s a significant programme of joint working happening at both a UK level and a Welsh level as well. The previous Minister in Wales, Huw Irranca, was very clear, when they launched their Green Paper, that we shouldn''t wait for transformation, that change can happen now. We''ve taken that very seriously. Where we can make changes before legislation, we are and we will. And we talk routinely with DWI, NRW, Welsh Government. We''ve got a lot of joint working arrangements to look at the areas that can change soon, where we don''t need to wait and we don''t need to wait for legislation.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Lia Murphy', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=597&l=en', NULL, 74.8, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Legislative commitment', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; Green Paper', 0, '2026-10-01T06:30:21.816323', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773121', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a52ae18afd577f30c3a2', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'But it might not be part of that NFI underspend money.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sera Evans', '', '330', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2215&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.163021', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774372', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a52ae88087a156b61429', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'How confident are you that there''s no duplication? Because, obviously, when a person''s registered, say, in Powys, and they go off to university in Pontypridd, they register there and they register in Powys. How can you tell if they register in two places so that they''re able to vote in two places?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5419&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.421720', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769998', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5355ecd63707d7ffde3', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'We set that target because we feel that''s where we should be, and that''s what we''re trying to work towards. We didn''t achieve it last year, but we''re not going to drop that target. We still feel we should be able to improve satisfaction. I did indicate in my answer some of the ways that we''re doing that, through working with our staff, trying to make sure we communicate clearly to people why we''ve taken the decision we''ve taken and trying to explain our rationale. It would be easier, I suppose, to drop the target, but we''re not going to do that. We''re going to try and improve that and continue to improve it. I''m just trying to explain to the committee that it''s a really tricky area when people are dissatisfied with the outcome of their complaint.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Michelle Morris', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=8309&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:37.911532', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777630', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5432111c334fd57c03a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Okay. Thank you, Michael. I''m going to go off on a tangent here slightly, because obviously you just mentioned software. Whenever somebody talks software to me, I always get worried. How confident are we that we can land the software itself? I''m 62 years old. I''m old enough to have seen some catastrophes when councils have tried to land software. So, how comfortable and confident are we, given the tight deadlines we''re working to, that a third-party provider, or a software provider, can land this right first time?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8833&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.013289', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774371', NULL, NULL, NULL, NULL);
