INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5601d52918c38b289d0', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Thank you. Elfed, you can carry on.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=9645&l=en', NULL, 80.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.099949', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777718', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a581c697a61c10056575', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Get the ball rolling.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=113&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:24.792185', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775599', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a59776dad1e077af742b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much. There is significant interest in this today. Our planning system must operate in a timely fashion, but it must also, of course, make robust decisions to deliver our ambitions for Wales, especially in terms of the economy and communities. That is why our programme for government has committed us to reform the planning system.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=8110&l=en', NULL, 77.0, 'Medium', 'digest', 'planning_system; fiscal_and_legislative_context', 'Context; Planning & place', 'Housing minister', '', 'planning system; programme for government', 0, '2026-10-10T14:39:12.755925', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776790', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a59d80dff5d28da2aeb3', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Andrew Charles, deputy director of the cohesive communities division.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Andrew Charles', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=93&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.562421', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771143', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5a2b169df92062dd694', 'plenary_transcript', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', 'Thank you very much, Peter, for those questions. Of course, I agree entirely with you: we do have to see action. That is what is important here, and that is why I held that meeting with the developers last week, in order to emphasise that very clear message that we do expect to see progress, and progress at pace, for the benefit of the people living with this ongoing concern and anxiety, because they are constantly reminded of what happened at Grenfell. And I do think it is important—. Thank you for mentioning that. It is important that we remember why we are doing this work. It does all go back to that tragedy seven years ago now. So, that was my message to the developers. I am accountable to leaseholders. I am not accountable to the developers. It is the leaseholders who are at the forefront of my thoughts, and through you in the Senedd I am also accountable to them, and that is why I will bring progress reports to you in this place.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5c74391fe628d4a12a2', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you for the question from the Member. As the Member said, in the supplementary budget yesterday, as far as health is concerned, we had a focus on outcomes, on improving people''s health and well-being by introducing more funding into tackling the waiting lists, and it was extremely disappointing, to say the least, to see people who have said that they wanted to support such a policy vote against it. We want to improve people''s outcomes and make sure that the impact on patients is better. So, we have made sure that NHS Wales Performance and Improvement are now involved. They have agreed an intervention approach in the Aneurin Bevan University Health Board to support them. Their improvement plan focuses on supporting frail and older people in the community—exactly answering the points that the Member raised—increasing the front-door capacity for people with complex needs and ensuring timely discharge. We have also allocated an additional £3 million this year to enable the delivery of the improvement plan.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16086', 'http://www.senedd.tv/en/16086?startPos=194&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:04.684752', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768029', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5e0ef61dc818316eafe', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch. I''m sure we''ll want to keep up to date on that as well. Diolch, Gadeirydd.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jayne Bryant', '', '5038', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6544&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.238950', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771310', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5e0f6c8e2a2821ac2c5', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'As someone who was a county councillor until recently, I can attest to how important it is to pass this supplementary budget today in order to address the challenges facing local government. Labour has made much over the last few weeks of the need to see urgent investment in ALN services, and everyone recognises that. It is therefore strange to hear today that they intend to vote against the budget, despite the fact that there is more money for ALN services in this budget than they themselves had originally called for. I''m sure that the families, teachers and pupils, who are calling for the same investment, will find that strange and frustrating too.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5ff7c4f0e93c5749051', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I think ''acknowledged'' is probably the best term. Let''s see how far we can progress those discussions now. But an acknowledgement is the beginning of a conversation, at least.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4160&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.821244', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770473', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a60cd69d5764819eed88', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Diolch, Lywydd. I''m pleased to speak in this debate today on behalf of the Finance Committee. We had the privilege of scrutinising the first supplementary budget on 9 July and our report makes 22 recommendations. Today, I will focus on some of our key recommendations. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a61543814a7dd6a7e46a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes, I agree on that as a risk. So, our evaluation noted that one of the sort of drawbacks, I suppose, of the shorter notification period would be, (1), adding an elector to the register when they don''t want to be added. So, this is obviously the concern you''re talking about, and the principle behind it is less time to receive the letter and have sight of it and then contact the ERO. And then, a kind of secondary risk, I suppose, of adding an elector to the register incorrectly, where perhaps the letter goes to a house where the intended recipient no longer lives, or never lived, so, again, it''s less time for existing residents to be able to contact the ERO. In terms of potential mitigations to this, and just trying to find that right balance between deliverability and meeting some of those concerns, there''s the fact that the open version of the register for devolved elections in Wales will have been abolished. That''s the change that the Welsh Government will be bringing in from October, as part of the preparation and the groundwork for these regulations. That''s something we''ve welcomed and previously recommended, and it will mean that, for people who are added to the register via any process now for the devolved version in Wales, businesses et cetera won''t be able to purchase a copy of that open register.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a62e8f33c223215587ef', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'That is something that we do encourage under these regulations. The schools will have data, for example—those that reach the age of 16, for example. I think that the ability to gather that data and then give young people the opportunity to register is important, because, as you know, in Wales, young people who are aged 16 or 17 can vote, but perhaps many families aren''t aware of that and therefore don''t add those names automatically. But this creates an opportunity. So, schools are one aspect. There are other departments where we encourage that, Michael.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=10420&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.364975', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774519', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a63176440300f9f55859', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Empty homes have emotion attached to them. However, we did a report that was referenced this morning into church-based assets. There are commercial assets and church-based assets and different organisations that don''t have that emotion, but quite often get picked up in the market by private developers, and they then face the funding and planning permission, and all that sort of thing. So, if there are the easier hits without the emotion and all the other things, then perhaps if you had a strategy, you''d be starting to look at those sorts of ones as a starting point, alongside the individual action against individual owners.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15373&l=en', NULL, 184.0, 'Critical', 'immediate', 'taxation_of_property; planning_system; committee_scrutiny', 'Housing system; Planning & place; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry; planning permission', 0, '2026-10-07T06:31:26.680825', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775512', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a648968463020fc7b33c', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I''m going to look to Lisa.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2560&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.304032', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777294', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a6ac6a178f09e4350241', 'committee_transcript', 'Public Accounts and Public Administration Committee', '4. Audit Wales brief: Welsh Government arrangements for funding local government', 'Thanks, Tim. The overall and the key finding is the way that the Welsh Government allocates funding to councils does not always help councils to get the value for money from that funding, particularly over the longer term. There are two aspects of that. One element of that is the settlement, the annual process of using a formula to allocate local government funding within the Welsh Government''s budget. That, since the pandemic, has been announced generally later in the year, which squeezes the window between the legal deadline for councils to set their council tax and their confirmation of the amount they''re going to receive, which we''ve noted can have some challenges around consulting the public and also in terms of the capacity for officers to make adjustments if their assumptions and their planning have been off course, I suppose, based on the mood music beforehand. There are some challenges around that. We do also highlight in the report that there are things that councils can do to mitigate the impact of that. That is a theme in the local reports that Tim touched on that we''ve made to councils themselves on multiple occasions.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a6ea2c607b83f6cac74d', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'You do make money out of it, so—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Cai Parry-Jones', '', '12174', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1694&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.164257', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777281', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a6ecf2dcc6b71da8d2cf', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I believe Cardiff may have been one of those authorities, but I''ve been informed recently that that may have changed now. So, I don''t know if they are one of the four, but, in terms of the Vale and Bridgend, we are very much using those grants.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Georgina Wayman', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5020&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.474055', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775087', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a74c0c63ede1e9b83876', 'press_release', 'Welsh Government — Announcement', 'Welsh Finance Minister to press UK Government for fairer funding at Cardiff summit', 'Welsh Finance Minister to press UK Government for fairer funding at Cardiff summit
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a771375e40a85404df41', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Yes, and particularly around health, that''s quite a way off. We''ve talked a bit about health already. That shouldn''t be there. We should, given our complaints standards work, you''re right, be seeing fewer coming through from health boards and indeed local authorities as well.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a77c462654f9d68794d9', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'We''ve reviewed our whole own-initiative process, and the recommendations we had from the committee on our own-initiative investigations were really helpful. I think it''s fair to say, when the Act took effect, this was obviously a new power—it''s only Northern Ireland that have this power alongside us in Wales—and I think the committee''s recommendations that we needed to perhaps think about how we could be braver, if you like, and be more flexible in our approach gave us confidence to review and look at how we can really target that power effectively.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a77dd66c1c2658559fa4', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I think performance, certainly in the last four or five years, has not been where we wanted it to be. We publish every year for all companies in England and Wales what we call a water company performance report. The most recent report is for 2025. We typically publish it each year, in October, so there will be a report forthcoming. There''s information in that that''s incredibly commercially sensitive, so you will understand that there is a limit to the preview of forthcoming attractions that I can give.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a782b9b9760689f0a7c9', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Yes, welcome and thanks for attending. This is something I feel very passionately about. That''s why I wanted it on the agenda. And when you look at the figures—and I want to start with the figures, really, because there doesn''t seem to be an accepted figure of how many empty properties there are in Wales. And I find that a difficult thing to comprehend. Buildings don''t disappear and appear. Where do you think we''re sitting? There are figures ranging from 22,000 all the way up to far more than that. Where do you think we are realistically?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=115&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:24.793801', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775132', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a786b3b0e6b78d1d75ab', 'plenary_transcript', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', 'In terms of your point that there''s a link between this work and the supply of social housing, I don''t really see that there is a link there. This work must happen. These buildings must be made safe. The legislation states so. The work to increase the supply of social housing is something that will happen gradually over a period of time. There is a good pipeline of projects in place in that system. So, I don''t really see a link between the two things. Thank you.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', '16262', 'http://www.senedd.tv/en/16262?startPos=18908&l=en', NULL, 88.0, 'High', 'digest', 'building_safety_and_leasehold; social_housing', 'Housing system; Property & energy', 'Housing minister', '', 'building safety; social housing', 0, '2026-09-26T13:20:21.074291', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#771098', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a78854c1f92cc68fccd6', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I imagine we''d be consulted. I described earlier the pipeline of 30 major projects worth £50 billion over the next 15 to 25 years. A number of those are water desalination and water reuse. And those proposals that were put to us I think had one eye on using non-potable water, for example, for data centres. But our job was to scrutinise those proposals, rather than design them. But, yes, I expect that we would be part of a conversation about how data centres could be cooled, potentially using non-potable water in the future. The UK, as I understand it, is one of the few countries that has a regime that is permissive towards using potable water for cooling data centres. But this is very far from my area of expertise.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=2561&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.062739', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773243', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a79bff7f9e47a4afe1a7', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. And I have a number of other things, as I''m sure lots of others do as well, but I did want to touch on agricultural pollution. We talked a lot at the beginning of the meeting about the drought and hot weather, et cetera, so I wanted to welcome the announcement that''s come this morning that you will now relook and be more flexible on when slurry can be sprayed, essentially. I think I''ve heard a lot of people welcoming that already. With this point, there''s a careful balance to make between agricultural needs and also the environment, and I was happy to see that you''re looking at that in this announcement. And, potentially, it''s a kind of win-win example, maybe. So, I just wanted to hear more about what you were thinking through, I suppose, on that particular issue.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Anna Nicholl', '', '12178', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6865&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.238337', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772059', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a7a919855dc8a889e7ea', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Thank you, Jamie.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4658&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.405548', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774768', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a7db23ff87b4038ac49b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', '8. What is the Government''s approach to ensuring co-operation across portfolios to deliver the Programme for Government? OQ64627', 'https://record.senedd.wales/Plenary/16313', '2026-10-06', 'Beca Brown', '', '12186', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', '16313', '', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government', 0, '2026-10-09T13:35:09.990577', 'https://record.senedd.wales/XMLExport/Download?meetingID=16313&xmlDownloadType=EnglishTranscript#776035', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a7ed59abae969f581a71', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'So, dealing with core audit work, but outside of that and looking further ahead, I can see a situation where we would need to use fixed-term contracts for specific skill sets, so, again, back in the digital and AI space, sustainability reporting, natural capital reporting, et cetera. There are going to be fundamental changes to the types of work that we''re going to be getting into, and I think those might lend themselves to injections of fixed-term contracts to bring expertise or skill us up in a particular area, and so on. So, I think we need to distinguish between our core skills and then thinking more about the skills of the future and so on. That''s much less defined, though, but I wouldn''t want to leave the committee with an impression that we wouldn''t do that, and I think that is a possibility.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Catherine Mealing-Jones', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2471&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.224333', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774542', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a7f25fe3ca389520a2ab', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Good morning, everybody. So, as Chris said, over the last few years, we''ve really strengthened our presence in Wales. We''ve got an office in Cardiff; we''ve got a dedicated Wales team and much stronger relationships with Welsh Government, with NRW and other Welsh stakeholders. And that stronger presence means that Welsh priorities, Welsh evidence and Welsh voices are much better reflected in the decisions that we make on a day-to-day basis. Welsh stakeholders helped to shape our latest price review, which provides £6.3 billion, as we said, for investment in Wales over the next five years.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a8004f5cd4b5817c7c2b', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'There are a couple of other areas to delve into. On key performance indicators, first of all, just a comment: I don''t wish to sound ungenerous, but on your KPI measures, you say that if it''s within 10 per cent, you rate it as green, if it''s between 70 and 90 per cent, you rate it as amber, and only below 70 per cent is it red. That feels quite generous, I think—that would be my personal view. I''d probably say if you''re achieving it, you''re green, if you''re within 10 per cent, you''re amber, and if you''re below 90 per cent, maybe you''re red. That would be my suggestion, perhaps, for you to reflect on.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a809150a7043cf7ce068', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Well, the budget is predicated at this point on a gross domestic product deflator that was announced in March of this year of 1.94 per cent, and that''s where the figure of a 0.7 per cent real-terms cut is derived from then. But we''re expecting that figure to be revised and announced in the next few weeks in anticipation of the UK Government budget. I think we can all collectively agree that that is likely to be increasing. The inflationary pressures that you''ve alluded to are very real. We see them in our petrol pumps and we know how they are affecting people in their everyday lives, as well as how the Bank of England will be reflecting on that, with changes to the interest rate, possibly, as well.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elin Jones', '', '162', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=6599&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.538243', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774288', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a8291e49c1978cd31da7', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thanks. Just before I bring Sera in, just one last point from me on this, then. So, whilst there may not be anything concrete ahead of the Chancellor''s budget at the end of this month, I''d be interested in any mood music that you may be hearing as to what that might mean—I appreciate if there''s not much there. And I suspect the other—in response to, Andrew, your point—challenging message might be that there may be a higher settlement than expected, but, if inflation is higher than the proportion of the increase in the settlement, I guess that might be a challenging message to manage, because people may see us receiving a higher settlement, but the costs of delivering everything is even higher. Is that something you''ve considered, in how you might try and manage that?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=6846&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.579867', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774336', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a83df74ada03ca20247d', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'We''re coming to the end. We''ve got five minutes left and there are a number of areas we haven''t yet touched on. Is there anybody who wants to ask anything further on animal health and welfare before I move on? Because I know a couple of Members want to ask a few questions about agricultural pollution. I don''t know if there''s any closing questions in the last five minutes to the Minister. Is there anything on animal health and welfare? Gareth, do you want to ask—? No. You''re just nodding your head in agreement. Lovely. I know, Anna, you wanted to ask something on agricultural pollution.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6834&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.233006', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772054', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a872fcb295ead30f0371', 'oral_question', 'Question not reached in Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', 'What discussions has the Cabinet Minister had with Wrexham Council regarding its new local development plan?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Carrie Harper', '', '278', '', '', 'Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', '', NULL, 55.0, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'local development plan', 0, '2026-10-10T14:39:13.892846', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a8bedda614807ae397bc', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I think that putting it at a strategic level is really important, and I think that the Welsh Government needs to have a plan not just for empty homes, but for affordable homes and all kinds of homes in general. There needs to be a national housing plan for Wales that encompasses delivery from an RSL perspective and bringing empty homes back into use. Of course, I would love to see community-led housing being part of that mix, because I think we are putting plasters over bullet wounds in some cases. If there is a plan in place so that everybody knows their role, everybody knows what we''re working towards and what we want to achieve, then I think it''s more likely to happen than just having interventions here, there and everywhere, essentially.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Casey Edwards', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16272&l=en', NULL, 172.5, 'Critical', 'immediate', 'taxation_of_property; social_housing; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; RSL; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.837104', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775408', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a8ca969dfdf8c9dd4a7d', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Thank you. Trystan, did you want to come in?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=14805&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.586962', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775394', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a8ce2170ed7876e78b77', 'plenary_transcript', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', 'We will now move on to the final item on today''s agenda, a statement by the Cabinet Minister for Local Government, Housing and Planning, building safety programme update. I call on the Cabinet Minister for Local Government, Housing and Planning, Siân Gwenllian.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Kerry Ferguson', 'Deputy Presiding Officer', '12177', '', '', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', '16262', 'http://www.senedd.tv/en/16262?startPos=16412&l=en', NULL, 71.5, 'Medium', 'digest', 'building_safety_and_leasehold', 'Property & energy', 'Housing minister', '', 'building safety', 0, '2026-09-26T13:20:20.760771', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#771122', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a8dd01d7096c53c999e2', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'No. I think, Chair, it''s one for us to discuss and perhaps formulate a recommendation following the evidence that Katrin has very thoroughly provided to us.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sera Evans', '', '330', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=9007&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.000182', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777674', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a921a838cbad53979a70', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Going on from what Clare''s just mentioned, from our experience, I think 28 days would be enough. I think that we were the only local authority within those 60 days to send a reminder out. So, we had three communications: the initial notification of registration; then about 25 days later we sent a reminder, a prompt—''You still have until the end of August to opt out of the automatic registration, but obviously the chance to register fully''; and then the final notification. With regard to the phone calls and the opt-outs, the early opt-outs with regard to concern about safety and safeguarding were all in the first tranche of phone calls. Anyone who wanted to explore or needed to consider anonymous registration all rang us within the first two weeks of receiving that communication. Any parents who felt strongly that their child should not be on the register at that age rang and wanted to opt them out at that point.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a925bc10d687f9494d19', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Trystan, I noticed you had your hand up.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17742&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:27.104269', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775423', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a9867f701767491f7cc4', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''ve already raised, in the inter-ministerial mechanisms that we have, concerns around ensuring that farmers in Wales have a level playing field when it comes to some of those international agreements and arrangements that are in place. There is a risk that we find ourselves undermining a lot of the good work that''s happening in Wales around antimicrobial resistance, for example, public health as well, as well as the economic piece in terms of maybe a two-tier market here if we allow some of this to come in. Richard, are you keen to come in?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5269&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.004396', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771864', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a99ed561d9e2f267512b', 'plenary_transcript', 'Plenary', '6. Member Debate under Standing Order 11.21(iv): Family Drug and Alcohol Courts', 'I rise today in support of this motion, because, at its heart, this debate is about one thing and one thing only: children. Quite rightly, we have heard a great deal about court processes, social services, addiction, public spending. But behind every statistic is a child whose future may be shaped by the decisions we make in this Chamber today. When a child enters care, it''s often because adults around them are struggling with complex problems: substance misuse, poor mental health, trauma, domestic instability. None of those challenges should ever be minimised. But neither should we forget that, wherever it is safe and possible, most children want the same thing: they want love, they want stability, and they want the chance to remain connected to their family.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a9a87c74dccdefa727f4', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'I''ll bring forward the regulations required to implement the changes to the differential multipliers in the coming weeks. The regulations will specify the properties that will be subject to the lower multiplier, and amend the value used to calculate the higher multiplier relative to the standard multiplier for any given year. Subject to the approval of this Senedd, the changes will take place on 1 April 2027.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a9b42c4b2619bc4ccb7c', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'I think I responded to that question earlier, in response to Jane Dodds. Early next year is when we’ll be taking the strategy out for consultation.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1328&l=en', NULL, 132.2, 'Critical', 'immediate', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', 'Consultation open', 'Equality, Human Rights and Social Justice Committee; consultation', 0, '2026-09-25T06:30:35.704545', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771204', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aa0b2fc9655316b41ed4', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I was wondering if you could provide the intended timeline for the introduction of legislation, if possible.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Kiera Marshall', '', '12166', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=276&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.078259', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770359', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aa2e9dbfd90d13590a82', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Well, if you''re living next to one in a terrible state and the family are doing nothing about it, then I think the local authority does have measures it could use, and maybe those need to be a bit chivvied up.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Chris Bailey', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=15226&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.658109', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775373', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aa366edfe3cd9f96a1a1', 'consultation', 'Senedd — Committee work', 'Forward work programme – Finance Committee', 'Forward work programme – Finance Committee
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aa635ccb32f810611fb6', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Ofwat was at the tip of the spear I''ve just described. So, our job continues to be to scrutinise proposals that are made to us. The system that gets us to that point is fragmented. So, we are an important part of a systemic failure. I think I would accept that, yes. But I had no choice but to accept that: you can read the Independent Water Commission report, which comes to exactly the same conclusion.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3198&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.162082', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773279', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aa6de4a6002bd0cf4d1f', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Sera Evans, as Chair of the Early Years, Children, Young People and Education Committee. Sera.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=25385&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.744603', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767962', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aa9e591dc697e21393bd', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I welcome this timely question from the Member, on the same day my Government publishes plans to cut business rates by 30 per cent for pubs, restaurants, cafes, bars, licensed clubs, hotels, gyms and cinemas. More broadly, through Business Wales, we provide advice and growth support to businesses. Targeted investment in local infrastructure and funding is helping to revitalise Bangor city centre specifically. We have also established that town centre taskforce we promised we would as part of our 100-day commitment to drive investment, increase footfall and support local businesses to grow.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=437&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-16T11:53:07.082272', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768977', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aaa0a0490e74641d9010', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'We''ll rebalance resources towards the prevention of ill health, better access to services and improved social care. We want a future where preventing ill health is given the same priority as treating illness, where services are designed around people and communities, and where every part of Government works together to improve health and well-being. And as the cost-of-living crisis continues to bite and global headwinds threaten further volatility in coming months, my Government will help households make ends meet.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aaa72182b0ce6da0eb40', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'But is that a ‘yes’, Minister? ''We accept the principle that legislation needs to be properly funded.''', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Huw Thomas', '', '12156', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=2208&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.447801', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770389', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aaac50ce7e3f1ac12cbd', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Yes, I''ve got a couple. Thank you for coming in today, I really appreciate it. You mentioned this a couple of times, actually, in your opening speech, but one of the main duties of Ofwat is to ensure that we have that good-quality service and that that''s provided to customers. Do you think that that duty is being fulfilled fully here in Wales?', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=799&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.843009', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773163', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aaca52d4a4f0ce7c3f8b', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'That is a reduction in the pension contributions that we will be required to make as an employer. So, obviously, we make pension contributions on behalf of our staff. There is going to be a reduction in the contributions. There''s a national agreement to reduce contributions, so there is a benefit to our budget of that. And as we''ve set out in the estimate, we want to be able to use that to reinvest in some of our pressures, offset some of our pressures, but also to reinvest in or invest in technology to help us with some of the work I''ve described earlier.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Michelle Morris', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=10847&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.288340', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777648', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aad20207a76aa5ea7a05', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you, Jayne. Laura Anne Jones.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6549&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.240889', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771311', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aadd0a094f9e4453390f', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. Just a really quick final question before we finish. Sarah Rees.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=7519&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.361802', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771313', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aae6684abdb27e79426c', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Yes, I''d be happy to. We think this is a generational opportunity to shape regulation around Welsh priorities. We have been supporting, and will continue to support, Welsh Government to do that while we continue to regulate effectively.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aaf59dd3ab28b9a40662', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Yes. So, the community facilities programme is a rolling capital programme that we''ve had for a number of years, and it provides capital grants to community groups to bring back buildings into use, improve facilities, but also to extend their use. And a lot of this actually is to do with some of the challenges that community groups face in terms of income generation, because some of these facilities can allow them to generate more income. There''s quite a widespread criteria that we have for those facilities programmes, but they are delivered across the whole of Wales in communities. And the one thing that''s really obvious from the programmes that we''re seeing is that they are able to get match funding from other organisations, including generating their own funds, which shows you the kind of level of commitment that communities have in that programme. We currently have a £10 million programme. It''s a rolling programme for facilities, and we publish all the relevant projects on the Government website, as and when they are agreed.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Andrew Charles', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6713&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.262419', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771247', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ab1945205eadd4ccec22', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. At the moment, we''ve still got the Habitat Wales Scheme for commons, which is very much designed to try and bring graziers on commons together to deliver outcomes. We are conscious that that scheme needs to evolve, in effect, into an optional action. As I mentioned earlier to the Chair, we have three priority areas and that is one of the priority areas now, working with our stakeholders to look at what support we can give to graziers on commons. We are more than aware that there are, as the Cabinet Minister said, challenges on some commons, either because the graziers are unable to come together or because only some actually graze the land. So, those are the sorts of questions that we''re trying to get into as we look to see what the optional support might be for common land graziers.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Gian Marco Currado', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1527&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.483589', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771816', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ab1e6af7e803b04760ef', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes. Yes, certainly. I''ll bring Huw in afterwards.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1360&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.275932', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770475', NULL, NULL, NULL, NULL);
