INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ab866b517d387b7e61a5', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'Finally, my Government will be unwavering and unapologetic in standing up for Wales and demanding fairness from Westminster at every turn.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=8873&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:19.725883', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#770986', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('abbcdb01c223932da656', 'plenary_transcript', 'Plenary', '3. Business Statement and Announcement', 'Thank you. So the Member will be aware, the Cabinet Minister for Social Justice and Equality is the relevant Member; you asked at the start of your question who the relevant Minister was, so just to give you that assurance.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('abd92075d9b43fbf4060', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Anna, I know you''re on my list, but Gareth hasn''t spoken yet. We''ve got the Minister until 11:00 and we''re going to take a break in between—unless he wants to stay longer, and it would be very pleasing if he would—so I''ll bring Gareth in now and then I''ll come back to you.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2297&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.621995', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772055', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('abea764a12c3eae82e95', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Yes, thank you very much—diolch yn fawr. Just to come to the KPIs, I''ve noted that only nine out of the 18 KPIs were met. If I just point out a couple of them that stood out: KPI No. 1, 94 per cent of principal accounts audit opinions were delivered, this is 5 per cent down from the previous year; KPI No. 6, 70 per cent believe that the work of Audit Wales has led to improvements, this is 10 per cent below the target. I used to run a charity organisation before coming here; I would have been hauled over the coals for only meeting half my KPIs. I''m sure that there''s a good reason, but what steps are you taking to improve your KPIs, targets, meeting those KPIs?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=335&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.763206', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774355', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('abfdfee27391d62092d2', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'So, I think the evidence available suggests that inflation next year is going to be significantly higher than we thought it was going to be back in March and, certainly, even more recently than that. Expectations keep on ratcheting up a bit. The bit that we''ll find out more about, in addition to what the Office for Budget Responsibility''s forecasts are in the UK budget, is whether the UK Government is increasing expenditure in devolved areas in England as a result of that and, obviously, whether that follows through, then, into consequentials for us. It makes a big difference, obviously, if that kind of higher than expected inflation leads to additional public expenditure or whether public expenditure stays at the same level whilst we''re dealing with higher inflationary pressures. So, that''s something else to look out for in the UK budget—not just the OBR''s forecast, but whether the UK Government''s increasing expenditure to sort of compensate for that, if that''s the right way of putting it. We don''t know that yet.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Andrew Jeffreys', '', '', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=6778&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.568501', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774302', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ac17a8203eeb7af457f5', 'plenary_transcript', 'Plenary', '6. Member Debate under Standing Order 11.21(iv): Family Drug and Alcohol Courts', 'These figures are alarming, but they are not just numbers; they''re human beings whose lives can be seriously impacted by their experience. Young people with care experience told the previous Senedd that, for example, some school teachers made it really obvious that they were in care, meaning that they never had a break from their experience of the care system. They told the previous Senedd that they had very little support to help them move on from foster placements and that they lacked the basic skills needed to live independently. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ac55ab3457cc1dcdceb8', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'It is a call that I have made in the past. What I would say is that we have to engage in what the UK Government could do and balance that against other things that the UK Government could do, because it''s the outcome that''s important, isn''t it? It''s not what the measure is, it''s how it helps. What I have to do is to look at what I have in my toolkit, and one of the things that we do have are the powers over non-domestic rates. We said that we would use those powers, and we''ve moved very, very quickly to make sure that we do, with this permanent change, this real vote of confidence in leisure and hospitality—pubs, cafes, things that really bring vibrancy to the high street. So, the UK Government needs to look at its house and see what it can do. We''ll put pressure on them to act in a whole host of different ways. We''re acting using the powers that we have.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=743&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:24.932435', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768988', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ac5e6f8ea954fdc7e9cf', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. We had a vote in the Senedd Chamber about dealing with TB, and I''d just like to ask where the Government and the Cabinet Minister are and where we all are with that.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Gareth Beer', '', '8650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6077&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.107442', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772133', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ac621ecfbef26f1a9055', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Yes. We are frequently under threat in terms of ICT, and there are many bad actors out there who want to threaten companies and institutions like ours. What steps are you taking to ensure that this Senedd is protected from that?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4578&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.615343', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777355', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ac89041ff6392d011ea2', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'And as somebody who represents an area that is very rural, I understand exactly that point. Of course, you can register online, but you''re thinking of receiving the letter late perhaps, yes? I think that this balance between 28 and 60—. I think 28 days is sufficient time, even in a situation like that. I do understand the point, but I think it is a matter of striking a balance in this context. In the context of legislation on electoral registration, 28 days isn''t unusual. It is more generous than some other statutory deadlines. For example, people usually have 14 days to appeal against a registration decision, and individuals will have perhaps 14 or 28 days to respond to a civil penalty notice. So, there are examples where the period of time is shorter than 28 days.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Sian Gwenllian', '', '4981', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9097&l=en', NULL, 92.0, 'High', 'digest', 'local_government_enforcement; committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee; civil penalty', 0, '2026-10-07T06:31:26.067930', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774342', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ac9bc841f33152950463', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'It is supplementary to the budget that was presented and passed by the previous Labour Government. It was the deliberate decision of this Government to honour the spending commitments made by the previous Government, not to make changes to funding decisions made by Labour. In that context, I understand what the Conservatives have told me, that not changing the Labour budget makes it impossible for them to vote in favour of this supplementary budget today. I fully understand that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('acbe18c7408c5d54af1c', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Can I just add as well that partnership working is one of Wales''s greatest strengths? I think this committee also has a role in helping us to scrutinise the performance of the company and help to hold it to account, and we''d be grateful for your support in that as well.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Lia Murphy', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=1175&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:21.882755', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773144', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('acc2b293440c6c16f94d', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Thank you, that''s very useful. Can you give us the percentages for each reason for empty properties? You said that that was a very small number. Can you tell us what the bigger numbers are?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=1638&l=en', NULL, 184.0, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.014726', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775350', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('acd5b8c84c64fcc88a2a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Thank you very much. Diolch.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Rebeca Phillips', '', '12172', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=6470&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.603304', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769973', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ad1d31e2abee07315310', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Thank you. Talking about funding, I think that brings us on to the next question. Marc, it''s you again, on funding.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=2131&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.105208', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775271', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ad2b0c4c23d4c5e16c3a', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Homes are the foundations of our entire lives, from health and well-being to education and jobs. This motion is divisive and misleading, and it''s important to put the facts front and centre of this debate.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ad4b7b4a99de1162e4a7', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much. You are entirely right. We know that we have to take an intersectional approach in this regard. We know that we need to understand and keep at the forefront of our minds, with the development of this new strategy, how other characteristics such as poverty, such as race and ethnic background, such as age, such as disability and so on, how they—. People don''t experience abuse in the same way, and we need to reflect that in our strategy, and ensure that the appropriate kinds of help and support are available to those different people. So, I recognise that entirely.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ad5710a6bb1b52e10316', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Sure, okay. Any other questions in this area? Marc.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=5042&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.479536', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775092', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('adb18d349b0ecb65c165', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Obviously, the Welsh Government has funded us at Cwmpas as the community-led housing hub for over 10 years now, and we''ve been lucky enough to access grants from trusts and foundations like the Nationwide Foundation. We''ve never had a stand-alone fund for community-led housing as they have in England, which I think has been a challenge. It''s helped our community groups to be very inventive in terms of where they get their funding from, but it is a jigsaw puzzle on every project to be able to get that funding in place. So, like I mentioned earlier, we''ve put together a business proposal for a revolving loan fund, which would be a mix of grants from Welsh Government and grants from social investors, but also loans from social investors to be able to grow the community-led housing sector. I think it''s really needed. Again, like I mentioned earlier, community-led housing groups are currently reliant on community lending, philanthropic lenders, and then a few banks and building societies that actually lend to this sector. So, I do think there needs to be a conversation about how we can increase the funding for community-led housing.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('adbe5ef798648dbbf614', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Thank you. The second part of that question—.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8091&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.856612', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774421', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('adcb577478136050a825', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'And it just becomes another layer of management.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Gareth Beer', '', '8650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3053&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.133212', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773473', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('add3ee90426454593b18', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. Thank you, Chair, and I think it''s fair to say that, having just published the programme for government, a lot of those particular priorities are articulated there.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ade6d074bb8b9fbc5e5a', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Thank you for that question. On the fiscal aspect of this work, the fiscal framework has been in place for a decade now, and therefore this is an opportunity to review that framework. The Government''s wish is that we do review the fiscal framework and include aspects of work on borrowing and on needs within that discussion.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('adf150520fa87a47c2f9', 'plenary_transcript', 'Plenary', '6. Member Debate under Standing Order 11.21(iv): Young people and employment', 'Thank you. So, I represent Bangor Conwy Môn, one of the largest towns is Llandudno, and we have the largest bed space, really, across Wales for the tourism industry. We are not suffering from immigration, I can assure you. We''re suffering from too high business rates and all the things I''ve mentioned in my speech. I can honestly tell you we are not suffering from immigration. Immigrants are not taking people''s jobs.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Janet Finch-Saunders', '', '212', '', '', 'Plenary', '6. Member Debate under Standing Order 11.21(iv): Young people and employment', '16086', 'http://www.senedd.tv/en/16086?startPos=10733&l=en', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'business rates', 0, '2026-08-04T14:03:05.757463', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768295', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('adf26c2b92afea36fcaa', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Back to Beca. Thank you.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4689&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.924479', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770606', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ae2d8a97ccb53ca0e310', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Protecting Renters', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', '', '', '', '', '', 'Plenary', '1. Questions to the First Minister', '16260', '', NULL, 66.0, 'Medium', 'digest', 'private_rented_sector', 'Private rented sector', 'First Minister / Cabinet', '', 'renters', 0, '2026-09-16T11:53:07.200599', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768999', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ae44779eb7e47dd3a41d', 'oral_question', 'Question not reached in Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '<p>The town-centre taskforce will address the structural challenges facing town centres, including business rates and planning reform, by working collaboratively with partners and maintaining a strong focus on delivery to help town centres adapt, attract investment and activity, and thrive in the years ahead.</p>', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', '', 'Cabinet Minister for Local Government, Housing and Planning', '', '', '', 'Plenary', 'Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 90.0, 'High', 'digest', 'taxation_of_property; planning_system', 'Planning & place; Tax & finance', 'Housing minister', '', 'business rates; planning reform', 0, '2026-08-04T14:03:06.997721', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=QNR', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ae686c2f00ae3943fff2', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'Thank you for asking me to speak on this really important legislative consent motion this afternoon in relation to the UK Labour Government''s steel nationalisation Bill. As a Labour member, as a trade unionist, support for our steel workers is very much in my DNA. My colleagues here today and my predecessors in the Senedd have always strongly supported steel workers in Wales, and we will continue to do so, whatever it takes to stand up for steel and protect thousands of steel-making jobs and communities in Wales. Steel is, of course, as many have said, one of the most important industries in Wales, whether in Port Talbot, known as ''steeltown'', or in Llanwern in Newport, where generations of families have built their lives around the steel industry.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ae786946c04ffa644ed2', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'This Bill is critical to supporting such a key asset. Primary steel plays a critical role in so many parts of our economy, and maintaining the ability to produce it underpins so many key sectors. My constituents know this more than most, with generations of experience and knowledge in this industry. While this Bill is welcome, and I support the Gweinidog''s recommendation to grant consent, I have to say, given the importance of steel to the Welsh economy and given our recent experience, it''s extremely disappointing to see how little time both the Senedd and the Welsh Government has had in terms of genuine dialogue with the UK Government on the implications of this Bill and the role the Welsh Government would play in the event that this Bill would be used in a Welsh context. I welcome the concession won by the Gweinidog, and we may hear a bit more about that later. However, people in Port Talbot have been let down by the previous Conservative Government and the soon-to-be previous Labour UK Government under Starmer. 
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ae7cb7fda2efa350a9d1', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Well, I''m very happy to continue to speak—', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Vikki Howells', '', '5107', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1931&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.545140', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772014', NULL, NULL, NULL, NULL);
