INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aeb1ef092917f1450e82', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'No, I didn''t say it. I said put it into—', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Francesca O''Brien', '', '12190', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=14721&l=en', NULL, 82.5, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', 'Opposition housing leads', '', 'HMOs; social housing', 0, '2026-10-10T14:39:13.267554', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#777035', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aed5ad2b56d4e8798acf', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Thank you. I was just going to say that, for our authority, we recently joined the empty homes grant. We''ve only joined as of April and, since April, we''ve had 15 applications and 14 are currently going through to approval. So, I just wanted to show that level of interest and uptake. I think part of that, it is unique, obviously, it''s that owner moving into that property for a five-year period and that can be a barrier in terms of that commitment over such a long time.
