INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c71a701d11242cbcc4d7', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'I was speaking earlier with Gwyn, regretting the loss of Marks and Spencer in Swansea. Will there be more retailers of that kind that are likely to take decisions to close their stores in the middle of our cities?', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Huw Thomas', '', '12156', '', '', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', '16260', 'http://www.senedd.tv/en/16260?startPos=10158&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:26.108614', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769223', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c71a85873ccaa94674b5', 'committee_transcript', 'Health and Social Care Committee', '4. Legislative Consent: Health Bill - evidence session 3: Betsi Cadwaladr University Health Board and Powys Teaching Health Board', 'So, my final question—. I promise, Chair, this is my final one, because I am conscious of time. I''m asking most people who are coming today to give evidence this question. Obviously, the focal point today is the Health Bill. I appreciate, as a committee, we''re very fortunate; we''ve got quite a lot of advice being given to us. We''re being fed information from our colleagues who sit on the legislation committee. But, for yourselves, and from your own experience, how are you being guided through the Health Bill? As in, are you being given legal advice, have you been briefed by any particular health organisations coming via England as to how this is going to operate and how it''s going to affect you professionally?', 'https://record.senedd.wales/Committee/16298', '2026-10-01', 'Natasha Asghar', '', '336', '', '', 'Health and Social Care Committee', '4. Legislative Consent: Health Bill - evidence session 3: Betsi Cadwaladr University Health Board and Powys Teaching Health Board', '16298', 'http://www.senedd.tv/en/16298?startPos=8199&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Legislation Committee; evidence session', 0, '2026-10-05T15:05:44.697650', 'https://record.senedd.wales/XMLExport/Download?meetingID=16298&xmlDownloadType=EnglishTranscript#774920', NULL, NULL, NULL, NULL);
