INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cedfa4b1ca4dcc960f3e', 'consultation', 'Welsh Government — Consultation', 'Classification of self-catering properties for local tax purposes', 'Classification of self-catering properties for local tax purposes
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cee1b637d43b133d72b8', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Last but not least. I''m going to ask you a general question. When the First Minister gave his inaugural speech—gosh, it seems like a long time ago now, but I think it was in May, wasn''t it—he said that, ''Where possible, we won''t legislate. Where it''s possible, we will look at alternatives to legislation.'' Now, the trouble is that we, as politicians, love to legislate, don''t we? Whatever happens, we think, ''We can legislate. We''ll fix it by legislation.'' So, give me an assessment as to, potentially, at what sort of level or how in-depth would you follow the advice of your First Minister, whereby you as Welsh Ministers would look at alternatives before introducing further legislation? Because, after all, we have such a lot of legislation now. I know that consolidation is going to be an important part of the work of the Welsh Government. Essentially, I''m trying to get a feel for what your view is. You might have differing views, I don''t know, but where you believe, where it''s not necessary to legislate, you would not look at legislation.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Adrian Mason', '', '12181', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4957&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.987591', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770510', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cf0edb5132dc74336940', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Yes.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Wendy Dearden', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16553&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.887810', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775546', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cf22873644c93120ea99', 'plenary_transcript', 'Plenary', '5. Member’s Legislative Debate under Standing Order 11.21(iv): A Bill on corporate parenting', 'I understand that Government say the voluntary charter is better because it can reach private and third sector bodies that legislation cannot, but let us be honest about how private organisations behave. They follow the law not a leaflet, so the charter''s breadth is precisely its weakness—it reaches widely because it demands less. Keep it for the bodies we cannot compel, but for our health boards and NHS trusts, the bodies we can bind, a care leaver deserves the duty the law enforces, not a promise quietly set aside. We do not leave safeguarding to goodwill, so we should not leave corporate parenting to it either.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cf3531a78fc32b9f514d', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you, Jane. Do you have another one you wanted to rephrase, or—?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2039&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.786631', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771180', NULL, NULL, NULL, NULL);
