INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cf92a16d75a9e4d7bdea', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'Sorry, sorry. The point I''m trying to make, and I''ll try to make it succinctly, is that under this, if this passed, you would not be allowed to be in a HMO. Is that right, that you would not be allowed to live in a HMO?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Matthew Jones', '', '12151', '', '', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', '16314', 'http://www.senedd.tv/en/16314?startPos=16183&l=en', NULL, 55.0, 'Medium', 'digest', 'hmos_and_standards; social_housing', 'Housing system; Private rented sector', '', '', 'HMO; HMOs; social housing', 0, '2026-10-10T14:39:13.421222', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776977', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cfb73d2a0b302134f564', 'oral_question', 'Oral Question', 'Oral Question - OQ64666', 'What assessment has the Welsh Government made of the impact of development quality requirements on housing delivery?', 'https://record.senedd.wales/OralQuestion/64666', '2026-09-30', 'Sera Evans', '', '330', '', 'Afan Ogwr Rhondda', 'Senedd (tabled business)', 'Tabled on 30/09/2026', '', '', NULL, 25.0, 'Low', 'dashboard', 'housing_supply', 'Planning & place', '', '', 'housing delivery', 0, '2026-10-07T06:31:53.566144', 'record_search:type=oral_question:query=housing', NULL, NULL, NULL, NULL);
