INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dab5d541c7140bf6cf85', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Well, it''s important to say the accounts were unqualified—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Michelle Morris', '', '', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=10173&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:38.177650', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777640', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dac9de867b3d7a16d873', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'I wonder whether, Catherine, as the new auditor general, that''s something you''ve reflected on at all, in terms of how you quantify some of those savings and report on those more transparently. ''Transparently'' is the wrong word, sorry, but more readily, perhaps.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=1351&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Other committee chairs; Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.983734', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774247', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dacca32dee84ec561422', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'We could go back and forth now, but the main expenditure group sits within your brief for climate change. We''ll move on now to animal health and welfare. Andrew''s going to lead us on this part.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5212&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.996159', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771861', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dae443602c6e0ccf64b0', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'During the election campaign, the First Minister said that the election was not about independence and that it would not be a priority during this Senedd term. Then, last week, he signed a joint statement with Sinn Féin and the SNP saying that Westminster''s time was at an end. And now, today, in the programme for government that was published, it lists in the section of devolved powers the desire to pursue the devolved power to hold an independence referendum in Wales. Given the First Minister''s comments during the election and then his comments today about his determination for an honest politics, I''d like to ask: what''s changed between now and then?', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Benjamin Hodge Mckenna', '', '12142', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=10923&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:20.053264', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#771011', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dafd5e841f6d42cb88f7', 'calendar', 'Senedd forward look', 'Local Government, Housing and Planning Committee — 24 September 2026, 09.30', 'Local Government, Housing and Planning Committee is scheduled to meet on 24 September 2026 at 09.30.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('db0f0f0b4fbb8eb60a86', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Well, there are actually cases of this.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6295&l=en', NULL, 184.0, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'Opposition housing leads', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.688556', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775493', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('db132c5ae0cc9a9b0405', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I will be brief. I''ve got two questions. In terms of the class A and class C exemptions, I''d be interested to know what you make of them. Do you think they''re having an impact for the newly purchased empty properties? And, secondly, are there any changes you would like to see to the tax system that would better enable community groups and third sector organisations to purchase empty properties?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=16984&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.965361', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775591', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('db377d8c652dcb5ede9e', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. We''ll move on now to community cohesion and safety. Jayne Bryant.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5880&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.172141', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771302', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('db6e3bce59597e345771', 'consultation', 'Senedd — Committee work', 'Forward work programme – Equality, Human Rights and Social Justice Committee', 'Forward work programme – Equality, Human Rights and Social Justice Committee
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('db78ff660a9d03a48793', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'I think one of the things, when it comes to poverty, that is often invisible is time poverty. I know that people who are working multiple jobs just to pay their bills don''t have time, for example, to find or cook healthy food just on the fly. So, whilst you''ve said a lot about reducing food poverty and the food strategy, I''d be really interested to look at how we improve the availability and affordability of healthy food for families in poverty. Diolch.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1730&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.744994', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771152', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('db80c20002dc757ff7fc', 'plenary_transcript', 'Plenary', '5. Statement by the Cabinet Minister for Local Government, Housing and Planning: The Revision of the National Development Framework and National Conversation', 'I agree entirely with you, as one who represents an area in the very area that you''ve mentioned in the north-west of Wales, and having represented the area, and having had the privilege of doing so, for over 10 years now. So, you don''t need to tell me that communities in the north-west sometimes feel that they are forgotten. This Government won''t be forgetting those communities or any community across Wales. That is the vision, ultimately, that I hope can be developed as part of this new framework—that every part of Wales is important and that we need to distribute wealth and economic growth and opportunities across Wales so that we reach every part of the country.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dba7f90bb35036022c28', 'plenary_transcript', 'Plenary', '7. Statement by the Cabinet Minister for Local Government, Housing and Planning: Building Safety Programme Update', 'Can I thank you, Cabinet Minister, for your statement today? There are many sentiments within it that I align with, especially regarding the victims of Grenfell. Our hearts still go out to them and their families.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dbab5fb82eeeb72c3f94', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Four hundred thousand.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Michael Kay', '', '', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9812&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.225733', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775800', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dbf303b8756846c1160f', 'committee_transcript', 'Economy, Energy and Connectivity Committee', '2. General Ministerial Scrutiny: Enterprise, Connectivity and Energy', 'I think procurement is one of the levers that we do have, isn''t it? And it''s £11 billion, I think, of public sector procurement. That''s a significant component of the Welsh economy, isn''t it, as a whole? I think that Governments across the world, large and small, have woken up to the fact that procurement is one of the most potent levers of economic and industrial policy that are available to us.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dc15e73e77b8de7e1a7a', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'More concerning, however, is the continued failure to prioritise funding to areas of genuine need. Many in Cardiff will have heard the Trefnydd''s contemptuous dismissal of my question earlier today. We''ve heard claims from Plaid Cymru MSs in the past that the additional learning needs funding gap was less severe in Wales than elsewhere—comments that teaching unions quickly criticised as out of touch with the reality facing schools.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dc1b24e8d5f32dd5b012', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'So, I think the first thing—. I might pass on to Tom in a second, to talk a little bit about some of the work that we do with partner organisations to share information and get information out to particular groups. The first thing to say would be that, obviously, local authorities and EROs, working with their partners in those authority areas, are going to be best placed to know and understand exactly where those harder to reach groups are likely to be. What we can do is provide them with some more support, some resources, some expertise, and the best ways to communicate information with those groups. We''ll be doing that, I think, ahead of the local elections next year. We''ve done some of that work ahead of the Senedd elections earlier this year, and we can provide that information so that local authority EROs can help deliver those messages most effectively. Tom, I don''t know if you wanted to say anything about the groups that we do work with already.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2002&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.992537', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769857', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dc3ea14e12f9a304d780', 'committee_transcript', 'Constitution, Justice and External Affairs Committee', '2. Ministerial scrutiny session: Cabinet Minister for Government Effectiveness and the Constitution', 'Of course, that''s similar to what the Finance Committee did in the last Senedd, which was to establish a forum between the finance committees in Scotland, Northern Ireland and Wales, and to work across the Parliaments to seek to better scrutinise Governments and the UK Government in particular. Is there scope for more such collaboration in your view, for the different parliaments to work together, and to work across Parliaments to provide a kind of shadow committee to the work that you''re undertaking as Governments?', 'https://record.senedd.wales/Committee/16278', '2026-10-01', 'Peredur Owen Griffiths', '', '8579', '', '', 'Constitution, Justice and External Affairs Committee', '2. Ministerial scrutiny session: Cabinet Minister for Government Effectiveness and the Constitution', '16278', 'http://www.senedd.tv/en/16278?startPos=254&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Finance Committee', 0, '2026-10-05T15:05:42.647798', 'https://record.senedd.wales/XMLExport/Download?meetingID=16278&xmlDownloadType=EnglishTranscript#775043', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dc589c078935ac5cb2a0', 'consultation', 'Senedd — committee consultation', 'Priorities for the Climate Change, Environment, Sustainability and Rural Affairs Committee', 'Priorities for the Climate Change, Environment, Sustainability and Rural Affairs Committee
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dc626c3cd4a990c13103', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I suppose I have some anxieties that there''ll be some authorities that—. I''m thinking of my old authority, Monmouthshire: a very small election team, and you couldn''t pick a worse set of elections to get it prepared for. If it was preparing for a Senedd election or a general election, it would be so much easier, wouldn''t it? But you''ve got so many candidates to sort out, so many people to get on board, there''s a lot of pressure on those teams as well. I''m a bit anxious, for a start, about where the additional staff are coming from. What skills do they need? How long will it take for them to be trained? That''s probably quite quick, I would imagine, but I don''t know. But all of those things that we talked about in the challenges that you had in Powys, can we really gear up to do it? Or is there even an opportunity where you can partially do it? So, you''re doing some of it, and you''ve just got to accept you''re only going to get so far on it. So, you bring so many people on, but that''s better than none, and then you sort of build on it. I mean, is there a hybrid? Does it have to be that you do it or you don''t do it, or can it be organic?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=6475&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.614370', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769979', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dc85b2dea29037796709', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes. I think that was the point I was going to come back to, because we''d had some difficulties. I raised with Darren Jones, who was a one-time Cabinet Office Minister, matters of the lack of co-operation from UK Government Ministries with their counterparts in the Welsh Government, and some of the practical difficulties that had arisen because of that. He was clear that that wasn''t the intention of the UK Government and sought to respond constructively and co-operatively to make sure that that didn''t happen. We stand ready as a Government, as a responsible Government, to co-operate as and when necessary with the UK Government, particularly on their legislation. Where those matters are minor and technical provisions, I mean, where those matters are engaged by the principles, then let''s co-operate. To do that effectively, we need to be there right at the beginning of the process, as we have been in some of the environmental regulations, and that''s worked well. I mean, if it can work there, there''s no reason for it not to work in other areas too.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3565&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.703775', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770453', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dca838f7a61550b2ab2c', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you for that. You''re absolutely right, there is a responsibility on all of us to consider the multifaceted impacts that this kind of large infrastructure has. The environmental one is one in particular. You may be aware, of course, that planning policy reform, hopefully, is on its way, where the Government will be reviewing and updating national planning policy so that we can better enable some of these decisions to be done in a way that aligns all of these considerations that need to be taken on board when it comes to energy policy, the planning system, clearer spatial guidance, the environmental impact as well. So, it''s work in progress. It''s something we''re very mindful of and something we''re serious about addressing.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Llyr Gruffydd', '', '425', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Rural Resilience and Sustainability', '16084', 'http://www.senedd.tv/en/16084?startPos=3470&l=en', NULL, 27.5, 'Low', 'dashboard', 'planning_system', 'Planning & place', '', '', 'planning policy; planning system', 0, '2026-08-04T14:03:15.780720', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#766900', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dcbbae179d5861801e1b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'Thank you. You''ve spoken about cuts, but not taxes. However, actions speak louder than words. From April, the Welsh Government has introduced a higher business rates multiplier for larger premises. Is this the direction that you think this Government is going to go towards in dealing with the financial issues? Are you considering other tax rises, including income tax?', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Cai Parry-Jones', '', '12174', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=3964&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-19T12:39:17.048966', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769545', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dcd1d60db0df79012fc3', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'So, the overall staffing costs for 2026-27, when you add everything together—well, when you add all the operational costs before the ring fence—comes to £59,987, and then the draft budget this year shows a figure of £59,541 when you add them together. That''s where you get the reduction.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=428&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.953982', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777356', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dcd41b2ccc7495d7a20d', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I''m full of them. [ Laughter .]', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Lia Murphy', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=2383&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.036987', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773179', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dcdca0359958e6619e03', 'plenary_transcript', 'Plenary', '3. Business Statement and Announcement', 'Can I call for two statements today, please? The first is from the Cabinet Secretary for Enterprise, Connectivity and Energy in relation to the mobile network. Action has been taken in Scotland and England, and they''ve announced this week in Scotland a consultation on changing permitted development rights in order to address mobile black spots. Given the essential nature of a decent mobile signal now, Wales is falling behind with this important digital infrastructure. We clearly need some action here, and I would be grateful if we could have an update on what action the Welsh Government is taking.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dcee3901558b402a309f', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Do you want me to take the carbon one, and you do the audit one?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Kevin Thomas', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=463&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:50.789454', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774632', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dd3657adf9f154d165c5', 'calendar', 'Senedd forward look', 'Climate Change, Environment, Sustainability and Rural Affairs Committee — 16 September 2026, 09.00', 'Climate Change, Environment, Sustainability and Rural Affairs Committee is scheduled to meet on 16 September 2026 at 09.00.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dd57cadedfe369b92c2e', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'As I''ve said, this is a supplementary budget. It does exactly that: it supplements a budget. This Government has honoured the previous Government''s budget to the decimal point in order to provide continuity of delivery for our public sector and other partners. We added to that budget, but took nothing away. As the people of Wales would have expected of us in this supplementary budget, we have sought to allocate funding available to us on the priorities they voted for in May''s election—on reducing NHS waiting times, on increasing affordable childcare, on tackling child poverty, on transport initiatives, and on a capital programme to improve school and hospital buildings and build new homes. I understand that Members, during the scrutiny of this budget, have sought to pursue the allocation of £344 million consequential funding for the debt write-off to English local authorities as a result of ALN historical overspends in England. This Government has sought to engage constructively on that issue.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', '', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=23080&l=en', NULL, 66.0, 'Medium', 'digest', 'housing_supply; fiscal_and_legislative_context', 'Context; Planning & place', 'First Minister / Cabinet', '', 'new homes; supplementary budget', 0, '2026-08-04T14:03:10.479544', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767967', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dd7c9520c48eef613dff', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you for the question. Yes, that package—the cost-of-living support package for local authorities—is something that provides support to all kinds of interventions that can help to tackle the support that is needed. It was related to support involving food in particular. So, we''re talking here about foodbanks, community cafes, cookery skills, projects that provide healthy, nutritious food to families on low incomes. And by the same token, we''ve also ensured with that package that it takes a preventative approach. Advisory services, services with community organisations that would be able to provide support and signposting for people that they seek to support, were an important part of that to try to prevent crisis rather than meeting demand, because there''s always a balance to be struck there. We have to respond to crisis, but we also need to look at the longer term picture, that we don''t just pour money into the support side, although that''s very important, but we also try to prevent families from going into crisis in the first instance.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dd7e51fe75432ec645eb', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'How do we know? How can we know if they have?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9739&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.204122', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774251', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dd8084c811ded4362678', 'plenary_transcript', 'Plenary', '6. Statement by the Deputy Minister for Public and Preventative Health: Priorities for Public and Preventative Health', 'Thank you to the Deputy Minister for her statement today. As Welsh Labour''s spokesperson, I welcome the cross-Government approach to preventative health, but I''m interested in what outcomes will be delivered for people across Wales. You''ve mentioned today the designated preventative departmental expenditure line within the Welsh budget for 2027-28, but I''m sure you''d agree, Minister, that it isn''t just the creation of the budget line itself that we should be focused on, but rather how people''s overall health and well-being will improve. I, like many others, challenge the Government to go beyond the process. We want to know what exactly will change and how success will be measured during this Senedd term.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dd9100710bbe206bb872', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'There''s always learning and I think that coherence is important. It can be done across portfolios, certainly, because, obviously, there are bespoke responsibilities that have to come together when events happen. So, I don''t think we should presume that, because it''s more than one person, it can''t work. But there''s no harm at all in looking at that wider picture and sharpening it up where we think that''s appropriate. And again, that may well be a consequence of the summit that''ll be held on 22 October and a discussion I''m more than willing to have with my colleagues in the Cabinet.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2756&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.696110', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771978', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dd971170f830be2e61fa', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Regen teams are dealing with the town centres. You''ve got the town centre loan schemes. You''ve got other grant funding streams available for dealing with them. Empty properties tend to deal with the empty properties side, with empty property officers themselves. So, the regen and the empty property officers don''t really work co-operatively, if I can put it like that. They''re seen as two separate strands, and it''s very difficult to get them to work together and see that each party, with the funding and the skills, are cross-serving. So, it''s a slightly different approach for commercial properties.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Andrew Lavender', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=2083&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; empty property; evidence session; inquiry', 0, '2026-10-07T06:31:25.096420', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775260', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ddbc6c5a44bb088fde8f', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Strengthening tenants'' rights is a priority for this Government. Renters deserve a safe, warm, secure and affordable home, and they should feel confident challenging poor conditions. Positive change requires good law, and the first phase of our legislative programme will better protect tenants, tackle poor landlords and make renting more secure.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=7454&l=en', NULL, 93.5, 'High', 'digest', 'private_rented_sector; fiscal_and_legislative_context', 'Context; Private rented sector', 'Housing minister', '', 'landlords; legislative programme; renters', 0, '2026-10-10T14:39:12.686061', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776756', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('dde1220b9f0c26193a45', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'Please.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=14472&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.523158', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775434', NULL, NULL, NULL, NULL);
