INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('e1289bab1b7e016b7370', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'This is item 2, a follow-up inquiry into empty properties: evidence session. The purpose of this is that, at its first meeting on 9 July, the committee agreed to conduct a follow-up inquiry into empty properties, and so today the committee will take evidence from three panels, the first panel being two academics, a housing consultant and a representative of the Empty Homes Network. Papers have been circulated to all Members to digest. First of all, I''d like to welcome the witnesses to the meeting and ask if you could introduce yourselves to the Members and the public, please.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=48&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:24.775088', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775113', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('e168901b81865a954805', 'calendar', 'Senedd diary (senedd.tv)', 'Equality, Human Rights and Social Justice Committee — 14 October 2026, 09.25', 'Equality, Human Rights and Social Justice Committee meets on 14 October 2026 at 09.25 in Committee Room 2.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=983&MId=16292', '2026-10-14', '', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '', '16292', 'https://www.senedd.tv/Meeting/Index/18fe8bc1-6c7d-4a3f-8e9f-72e368643b57', '2026-10-14', 24.0, 'Noise', 'archive', 'committee_scrutiny', 'Housing system', '', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-10-08T06:34:33.212419', 'seneddtv:18fe8bc1-6c7d-4a3f-8e9f-72e368643b57', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('e19d26594dd0fb25eadd', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I''ll ask Ed to provide those details, but just to address why we need to decant to get the work done, the initial strategy was to remain in the building and to move people from one side to the other and back, but given the details of the structure of the building and the extent of the work that''s going to be done, it became evident that the disruption on Members was going to be very significant. So, one of the benefits of moving out and decanting is that the project will be completed a year sooner than previously thought, which saves money and saves costs as a result of the decant. That''s just to give you the context of why we need to do this.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2365&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.272532', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777263', NULL, NULL, NULL, NULL);
