INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ea68340ebdb8510327a8', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I''ll take that to start, and then I''ll bring Ed or Manon in afterwards. I think the extent of the works that are going to be carried out in our preferred bid is significant. In effect, it will probably look like a new building on the same site without knocking it down. So—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=3229&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.404560', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777509', NULL, NULL, NULL, NULL);
