INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec08c005788419843d0c', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'That is why the Cabinet Minister for Education and the Welsh Language has already published a new literacy and numeracy plan and has set clear national expectations to raise standards and help every learner to succeed.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=8782&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:19.708078', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#770970', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec13287d879c2b055286', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Thank you. First Minister, we know that immigration increases demand on housing, which, in turn, leads to increased rents. So, can the First Minister confirm that any planned changes to private and social renters'' protections will be prioritised for Welsh people over recent arrivals?', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'David Hughes', '', '12159', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=2199&l=en', NULL, 99.0, 'High', 'digest', 'private_rented_sector', 'Private rented sector', 'First Minister / Cabinet; LGHP Committee members', '', 'renters', 0, '2026-09-19T12:39:25.128030', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769004', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec2066f65ba3b0ccf87e', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'I''m happy to start, if that''s helpful. I completely think that there''s a role for community organisations and even community members to contribute to the data on empty properties and empty homes. A really practical example of community-led data collection is the Ynys Môn Public Map platform. So, they''ve trained a group of community researchers who have been able to map key assets on the island, but not only assets; they''ve actually been able to map where there are anti-social hotspots, for example. So, obviously, that key community insight is invaluable, isn''t it? They''re the people living and working in these communities, so they obviously know their areas best. So, I would really advocate for that kind of community-led and community-member data collection. And working with stakeholders and organisations like rural housing enablers as well, I think they can support that community collection of data as well.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Casey Edwards', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=14565&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:26.548186', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775459', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec28c2d293086a0da931', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I thought that the rent was going to be cheaper because of that deal that you cut with the—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Elfed Williams', '', '12165', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4114&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.550376', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777455', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec36fac35937fb61469f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'If I''m right, if you were a local authority purchasing it, you wouldn''t pay the land transaction tax.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Chris Bailey', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17102&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny; named_welsh_legislation', 'Context; Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Land Transaction Tax; Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry; land transaction tax', 0, '2026-10-07T06:31:26.984199', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775520', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec4987204d955b6f9856', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Just picking up on the question that James asked just now, actually, I''ve got constituents who are very concerned that, say, data centres are being considered to be essential national infrastructure. But I think that, actually, biodiversity habitats also should be considered as essential national infrastructure. But, of course, planning—. You talked about—. Well, the planning system should take care of that. I guess it''s incumbent on us, and perhaps you need to have a conversation with the Cabinet Minister for Local Government, Housing and Planning about the way that we see, for nature resilience and so on, but also for people''s well-being, that that natural environment, that biodiversity and those habitats are, in a sense, essential infrastructure as well.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Paul Rock', '', '12176', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3607&l=en', NULL, 132.2, 'Critical', 'immediate', 'planning_system; committee_scrutiny', 'Housing system; Planning & place', 'Housing minister; LGHP Committee members', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; planning system', 0, '2026-09-25T06:30:34.831063', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771820', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec4b21732c6e5fa537d2', 'calendar', 'Senedd forward look', 'Finance Committee — 22 October 2026, 09.30', 'Finance Committee is scheduled to meet on 22 October 2026 at 09.30.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec67752c9c83269a875f', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'Chair, just to stay in that area of board effectiveness, actually, I note the effectiveness review that you carried out and I commend you for undertaking that work. I wonder if you can just say a bit more about the findings, given that that identified you as operating in the second quartile of board excellence.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2782&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.301935', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774178', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec6888887b173e5b0673', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'It''s no problem with people in prison. I often go and actually pop in and have a visit and you can serve notices in that regard. So, that''s not an issue, from that point of view. I would say 95 per cent of properties can be dealt with through enforcement. It''s about political will and whether you''ve got the necessary skills and the finance to support it. So, you''ve got the finance, and a lot of authorities have got the skill, but, echoing Adam''s point about resources at the front end, it''s the empty property that starts the engine and gets the process in it.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec7fdff37ccaa07c3650', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Yes, it was something that the Electoral Commission were quite clear on in their evaluation of the pilots, that the 60-day period was too long and it should be reduced. So, we looked at 28 days because it seemed more in line with other processes for responding too, on the basis that 20 days, four weeks, if people are on holiday when the letter first comes in and they want to opt out, then the likelihood is that they will be able to respond in that period. I think Sandra from Powys spoke about the fact that most people responded in the first two to three weeks of receiving the letter if they were going to opt out. So, I think we''re fairly confident that 28 days seems appropriate.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Michael Kay', '', '', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=9014&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:26.049484', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774334', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ec9fecb4d59d26159f37', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Diolch, Cabinet Minister. I''d recommend you do look at that scheme because, as I said, the feedback from many was how effective it had been, particularly for reluctant landlords.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eca693236f605a2245d2', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Diolch. So, my first question is: obviously, we''ve got the establishment now of the Office of Environmental Governance Wales. I was just wondering how that progression is going and how you see it as fitting into your wider vision as a Government when it comes to biodiversity?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2821&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.706817', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771990', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ecfce716cf9239794625', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'But you failed.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3197&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.160771', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773278', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ed0b7e1413bfc19bdba2', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much. I''m not familiar with that specific example, but ''Planning Policy Wales'' does set out that local planning authorities should plan for the infrastructure needed to meet the needs of communities when new housing developments are considered. So, it is a requirement for local authorities to look at the infrastructure. Adequate and efficient infrastructure, including the types of things that you have mentioned, is crucial in providing new housing developments that meet the needs of current and future residents.', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=5441&l=en', NULL, 60.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'Planning Policy Wales; planning authorities; planning policy', 0, '2026-10-10T14:39:12.508383', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776761', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ed0caaa4c76e1efb094b', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Well, as I said earlier, the Government is accelerating the roll-out of 12.5 hours of funded childcare for all two-year-olds across Wales. The additional funding in the supplementary budget should enable local authorities to make progress on this first phase of the expansion. I am pleased that officials are having positive feedback from local authorities on the difference that the funding will make.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=3239&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.474763', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767561', NULL, NULL, NULL, NULL);
