INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ed88736e4d495c12509d', 'oral_question', 'Oral Question (tabled)', 'OQ64652', 'What action is the Welsh Government taking to support leaseholders with cladding issues?', 'https://record.senedd.wales/OrderPaper/OralQuestions/07-10-2026/', '2026-09-30', 'Joe Martin', '', '', '', 'Caerdydd Penarth', 'Plenary', 'To the Cabinet Minister for Local Government, Housing and Planning', '', '', '2026-10-07', 65.0, 'Medium', 'digest', 'building_safety_and_leasehold', 'Property & energy', 'Housing minister', '', 'cladding; leaseholders', 0, '2026-10-01T06:35:55.334135', 'orderpaper:2026-10-07:OQ64652', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('edbf0e7f50730db60093', 'committee_transcript', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', 'I think Ann-Marie may want to come in on this point as well. I think as we move back to that steady state that I mentioned before, I''d anticipate more people being on the traditional employment contracts with Audit Wales. In the past, we did always take on temporary staff, but that was very much for specific peaks in workload, when we have audit deadlines to meet—there are two or three specific ones during the course of the year. So, I would anticipate moving back more to that model, so there would be much shorter fixed-term contracts specifically to deal with those peaks, rather than a backlog of work where we''ve needed to take people on for 12, 18 months to give some continuity.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Kevin Thomas', '', '', '', '', 'Finance Committee', '3. Audit Wales - Scrutiny of Annual Report and Accounts 2025-26 and the Annual Plan 2026-27: Evidence Session 1', '16294', 'http://www.senedd.tv/en/16294?startPos=2425&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Delivery bodies', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-02T12:57:51.215464', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774490', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('edd08462cdaeb93c4587', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Mike.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=6612&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.735815', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775437', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee0fd1e5586574d15d39', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'That''s really interesting, and that''s reassuring as well. A final question on capacity in this way of actually reviewing and measuring improvement. How are you planning to review or measure the impacts of what''s flown from the review?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peter Fox', '', '4787', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3198&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.635699', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770412', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee13c234d6520277a7eb', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you for that question. The Member made an important point at the outset in talking about the importance of the supplementary budget yesterday, in providing £145 million in this financial year in order to address waiting lists, to improve infrastructure and to improve the provision that we have for waiting lists. It was incredibly disappointing to see Labour and Liberal Members siding with Reform to vote against policies and against funding that would tackle one of the most pressing issues that has faced us in health in Wales over a decade and more.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee2797707f8418902020', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Niamh.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2064&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.579103', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771982', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee35514ebe3deda01752', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I am aware of the changes that they are investigating in Scotland in terms of the compulsory purchase, and I think it touches on what I said earlier about trying to streamline the process, making it easier, quicker and more effective. I know they are looking at something called compulsory sales orders and compulsory leasing orders, and I can see the benefits of those systems, because as it stands at the moment, the property that we''ve compulsorily purchased in Bridgend is now in Bridgend council ownership, so we are liable for that property until it changes hands, and that''s not going to be until the sale has gone through and then the sale completes. So, with these two measures that they are proposing in Scotland, it would take away that risk, because they don''t ever take possession of it.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee492ab444f1f4b52390', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I think, in relation to the nature recovery action plan, it''s really clear, the relationship between that and section 6 of the Environment (Wales) Act 2016. In terms of the biodiversity duty, obviously, that does need a detailed plan to be able to discharge that requirement. But, as the Minister set out, in relation to the climate and nature action plan, that''s about bringing coherence and looking at the fact that, with regard to climate and nature, there are common root causes and being able to address them through integrated action, rather than action within each of the individual areas.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Rhodri Asby', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3385&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.798930', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771885', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee4ad02337d21bf99354', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you for the question. In our programme for government, you will see that there is a clear commitment there to reform the planning system, to make the planning system more accountable to communities, and also to see how we can accelerate the process of providing planning consents and removing some of the barriers from the system. So, planning is a key area, and we recognise that it has a key role in delivering many other policies, particularly in the field of housing.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee52aa0d0adbda29adb3', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Could I just ask one supplementary to that?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Marc Jones', '', '350', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=591&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:24.852507', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775242', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee747503eac12d230f2d', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Just on the preventative side, Minister, you and I have already discussed issues around health spending and the pressures within the NHS on an annual basis, and much of that spend inevitably goes towards not preventative but responsive care. I was reminded just yesterday that in Cardiff and Vale Health Board, for example, with a budget over a £1 billion, the public health budget is £4 million—a fraction. Are you thinking, in your forthcoming budget, of some concrete steps to try and shift that balance slightly?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=8210&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:51.805589', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774196', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee8604417d4ba2473dea', 'plenary_transcript', 'Plenary', '8. Reform UK Debate: Access to HMOs and social housing for foreign nationals', 'I will try and be brief because I fear that just like this isn''t the first time we''ve ended our day having this sort of debate, it won''t be the last time that we have to stand up at the end of the day and rebut this ugly, divisive and hateful rhetoric. I am ashamed that we have to keep having this discussion. Going back to something that was said earlier today by the Minister: everyone has the right to a safe and adequate home. Everyone. Without it, how can you begin to build a life? How can you begin to participate and contribute to society? How can you begin to choose to call Wales your home as so many of us have? I repeat: the right to safe and adequate housing for everyone is a key test for this Senedd.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ee8cf6b24dacba9ad568', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Okay, thank you. And then, going back to looking ahead, in terms of capital financing, I was reflecting on your comments about the current expectation of a 9 per cent real-terms cut to capital over a three-year period. Are you doing any particular work to understand if there are any more creative solutions to any issues that may cause and the role of local government and how they can be supported to make the most of any powers that they have as well?', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=10094&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:52.091965', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774618', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eea2d79b95ec9eb442a4', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Thanks, Chair. Just on AI, rather than just empowering your staff rather than just empowering your staff to go back and say, ''Can you give us something shorter?'', have you considered just having a form for the public to raise complaints that sets a word limit and maybe breaks out what action is the complainant looking for, rather than just having an open-ended, you know—?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', '16295', 'http://www.senedd.tv/en/16295?startPos=7721&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Finance Committee; evidence session', 0, '2026-10-09T13:34:37.817514', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777636', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eeadaad6df3ba42af962', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'I definitely think it can act as a deterrent. Just sometimes the threat of taking enforcement action is enough to get the owner to engage, and then you can go down all of the routes of offering support. You will always get those owners who won''t do anything, and that''s when you end up in your enforced sales and your compulsory purchase orders, so I definitely think it''s a deterrent.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eeb068526f572616bb31', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Thank you. It''s good to hear that projects are being analysed and how effectively. In business, it''s always good for accountability. I find it incredible that somebody could get paid £890,000 in 2001, four and a half times more than even the UK Prime Minister, for an organisation that was dysfunctional. What is happening now to ensure that those sorts of salaries—which is approximately somewhere in the region of £75,000 a month, which taxpayers are paying, water payers are paying, we''re all paying—aren''t replicated and people are held to account and responsible for how well the company is being run?', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'John Davies', '', '4650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3332&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.180776', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773288', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eebab48bf0d74b0811da', 'committee_transcript', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', 'Can I interject there just slightly and say that we did get a response from Welsh Women''s Aid? It''s in page 141 of the pack. But they have responded. Please continue.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '4. Scrutiny of the Cabinet Minister for Local Government, Housing and Planning on the Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026', '16305', 'http://www.senedd.tv/en/16305?startPos=8264&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Housing minister; LGHP Committee members', '', 'Local Government, Housing and Planning Committee', 0, '2026-10-07T06:31:25.886602', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#774443', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eeda524f0c4cd39c4413', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'I thought it was important for me to speak on this topic, given that, in my previous role as leader of Cardiff Council, one of the final decisions I took formally was the decision to introduce the visitor levy to the capital city.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Huw Thomas', '', '12156', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=14074&l=en', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'visitor levy', 0, '2026-08-04T14:03:16.985824', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767115', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eeda616777061df2b506', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. Yes, I take the point. As I was mentioning, there are ways of ensuring that we engage, not just across the Cabinet, but also with the UK Government, where several of the economic powers and legislation relating to the workplace, for instance, lie in their hands. But, what we are seeking to do, through the schemes that we have—and they are, mainly, as I said, part of the skills agenda, but also the agenda around economic growth, and the productivity mission that the Government has—is that we look at this specifically. And I will be keeping a close eye on that and ensuring that there is a gender element or lens that is applied to those schemes.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4573&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.022873', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771274', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('eefaf384a76a1dbc50cd', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'By focusing on what matters most to the people of Wales, working together and taking a long-term approach, we can build a more confident nation that is ready to fulfil its wealth of untapped potential and give people hope for the future.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=8954&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:19.741850', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#770994', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ef39bd5969c6669cfadf', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. I wondered if you could talk a bit about the devolution of the Welsh benefits system, and where we are with that and what you see this Government hoping to do over the next four years as well.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2095&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.796629', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771189', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('efaa8815ec8b091b4b5d', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Well, the Welsh Government wants to see a Wales Act introduced by the Westminster Government that would look to devolve those powers where there is a certain amount of consensus on what the new powers for the Senedd should be and be implemented here in Wales under the oversight of the Senedd.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('efc3dcd95c575e8e4d1f', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'What''s gone wrong on our end was set out in the final report of the Independent Water Commission—quite painfully, as I described it before—that Ofwat''s part of a system that was too fragmented, and as an economic regulator, we were at too great an arm''s length.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('efd23dfc0968b54a36a9', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'The cracks will remain in the pavement, I''m sure, unfortunately. So, it''s Glas Cymru that we should be holding accountable for any changes and payments over and above what would be normal.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'John Davies', '', '4650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3450&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.193332', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773301', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f004a4f933f47ecbb083', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Those discussions are in their infancy more so than for other areas of reform. Water system planning will need to move to a catchment base across both England and Wales. The natural catchment for Welsh planning is Wales. So, we''re proceeding with Welsh Government on the basis that there will be a national system plan separately for Wales. That will be part of the new regulator. In the run-up to PR29, as I described earlier, we are part of a forum that''s designing what that looks like for the next price review. That will mean in practice us beefing up our presence in Wales even further to act as almost a unit, a Wales economic regulator, within the overall economic regulator. And they''re the steps that we''re taking with the Welsh Government at the moment.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f02fd760e3ecc2690859', 'committee_transcript', 'Health and Social Care Committee', '2. Legislative Consent: Health Bill - evidence session 4', 'We’ll move on to the first item on our agenda. The committee is considering the legislative consent memorandum on the Health Bill. Last week, we heard evidence from a number of organisations, and today is our last evidence session relating to the LCM. I’d like to welcome Mabon ap Gwynfor, Cabinet Minister for Health and Care. Bore da, Mabon. You have been joined by two officials; perhaps your officials would like to introduce themselves.', 'https://record.senedd.wales/Committee/16299', '2026-10-08', 'Jayne Bryant', '', '5038', '', '', 'Health and Social Care Committee', '2. Legislative Consent: Health Bill - evidence session 4', '16299', 'http://www.senedd.tv/en/16299?startPos=47&l=en', NULL, 80.5, 'Medium', 'digest', 'fiscal_and_legislative_context', 'Context', 'Opposition housing leads', 'Opportunity to influence', 'LCM; evidence session', 0, '2026-10-10T14:39:09.055548', 'https://record.senedd.wales/XMLExport/Download?meetingID=16299&xmlDownloadType=EnglishTranscript#777757', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f042ffad5b33fd1cf123', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'There''s a shortage of housing available for renting. There''s an even greater shortage of housing available at affordable rents. The long-term solution is to build more social housing, especially council housing. I have supported rent controls and the return of rent officers for privately rented properties. But we now have a new, very serious problem, Airbnb, which is taking properties out of the private rented sector. This is not a seaside and holiday resort problem only. It is also a problem in cities. What action is the Welsh Government going to take to limit Airbnb in each council area?', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Mike Hedges', '', '332', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=2419&l=en', NULL, 203.5, 'Critical', 'immediate', 'private_rented_sector; rent_controls_and_affordability; second_homes_and_short_term_lets; social_housing', 'Housing system; Planning & place; Private rented sector', 'First Minister / Cabinet; Opposition housing leads', '', 'Airbnb; council housing; private rented; private rented sector; rent controls; social housing', 0, '2026-09-19T12:39:25.158023', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769011', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f04bf20406b124e14a9d', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Yes. Andrew.', 'https://record.senedd.wales/Committee/16294', '2026-10-01', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', '16294', 'http://www.senedd.tv/en/16294?startPos=10261&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Finance Committee; draft budget', 0, '2026-10-02T12:57:52.114907', 'https://record.senedd.wales/XMLExport/Download?meetingID=16294&xmlDownloadType=EnglishTranscript#774346', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f061e644a19a6d1f07a5', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Thank you for the question. Of course, Antoniazzi''s is a well-established business of almost 100 years'' standing. What we will see outlined by the Cabinet Minister for Finance this afternoon will be truly significant. SMEs are the backbone of our economy, and we''ve made it clear, particularly through the Cabinet Minister for Enterprise, Connectivity and Energy, that we are determined to support and grow indigenous Welsh businesses to ensure that successful businesses continue in Welsh ownership and to give them the confidence to invest in their future. The changes presented to non-domestic rates will be introduced as soon as possible, from the beginning of next year or the next financial year. They will be permanent, which again is a step that gives business confidence. I look forward to hearing the details from the Minister later this afternoon.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=612&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-16T11:53:07.103652', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768973', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f086afa20f5a1fadacbc', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Lisa Bowkett, chief finance officer.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lisa Bowkett', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=83&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:36.900608', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777350', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f0a19c6dcf9eb0f62cdf', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Yes, great. Thank you for that. So, as discussed earlier, I think there''s a kind of broad agreement that legislation is there; it just needs to be streamlined and maybe easier to be used. And also the importance of sharing information between authorities—that needs to be something that''s more consistent.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f0a2787b252c45dfb8f6', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I think the current rent is—', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4089&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.540293', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777445', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f0bb653e79594206264b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much for the question and I was very pleased to see that this announcement was part of the announcement on the Government''s legislative programme. We are clearly committed to introducing a Bill on community right to buy and that will be a priority for us in the next few months now.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f0c084c34e1863f21902', 'committee_transcript', 'Finance Committee', '6. Welsh Government Draft Budget 2027-28 - Pre-budget scrutiny: Cabinet Minister for Finance', 'Yes, so, the challenge on the capital budget is significant, and it will be more than that 9 per cent, because of the issues that I raised earlier on the reductions as a result of the defence investment plan. Therefore, there are two aspects to the answer on this. One is that we have undertaken a zero-based analysis of the capital budget in preparing for the allocations for the three years to come, so that we bring a fresh pair of eyes on the pipeline of projects that are coming from different aspects of the public sector—hospitals, maintenance, as well as aspirations for new build within the public sector. But therein lies the issue, then, around how we use innovatively the money at our disposal. You will know that the mutual investment model is one that is continuing and has a pipeline of projects that need to be assessed and are being assessed. That''s a model that we''ve inherited from the previous Government and has worked very effectively in the delivery of new projects, new capital projects.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f0c3cb92b71a24478a10', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Ed, do you want to talk through some of the specifics on the costs?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Peredur Owen Griffiths', '', '8579', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2421&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.278699', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777272', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f0df75492cb4313c0b30', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you for drawing our attention to that. I''m always concerned when there are any circumstances that require police attendance and police involvement. There''s a certain way of doing things, and I think decent courtesy means that that should always be adhered to. I won''t be drawn on commenting on any specifics, because I''m sure you can understand that I''d be straying into difficult territory.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f1611047b9beea569e62', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Okay. And one more question from you, Elfed.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=4668&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.629137', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777402', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f16efb6d3fb930a1dd13', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Okay. And then the last question, I think, about this area: obviously, there was some refurbishment work in Tŷ Hywel ahead of the May 2026 elections—just commenting on what I can see around me, the accommodation looks of really high quality—so to what extent are the benefits of that work going to be retained or lost as part of the building refit?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Huw Thomas', '', '12156', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2793&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.351281', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777483', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f1790ee4d48b1fb25ca2', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'How have you sought to reduce the percentage increase requested for parts of the budget within your control?', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Lyn Ackerman', '', '4967', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=948&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.039782', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777216', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f1cc320f60e51f93a4a0', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Well, that is redolent of and echoes, I think, a number of the recommendations in the Independent Water Commission report of July last year. That said that long-term planning for waste water and water infrastructure investment should be done on a more integrated basis and at a catchment level, and it is the UK Government''s responsibility, DEFRA''s responsibility, and the Welsh Government''s responsibility to articulate, with our input, what that''s going to look like for the future.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Chris Walters', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=2220&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.010758', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773204', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f1e99a3218741517a24f', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Absolutely. Thank you for that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f1ee4f7aa686c66de9b3', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'I''d also say there''s the uncertainty around data centres—obviously, where they''re put—and I think that national picture for water, not just water supply for customers, is one we''re working on with the Welsh Government to highlight that data centres need greater thought.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Mark Squire', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=2529&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.056968', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773233', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f206cd0bed4026c33d78', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', 'Adam, would you like to come in on this?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. Follow-up inquiry into Empty Properties: Evidence session 1', '16305', 'http://www.senedd.tv/en/16305?startPos=931&l=en', NULL, 189.7, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:24.907506', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775335', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f21d6908308bedfa56b5', 'calendar', 'Senedd forward look', 'Local Government, Housing and Planning Committee — 26 November 2026, 09.30', 'Local Government, Housing and Planning Committee is scheduled to meet on 26 November 2026 at 09.30.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f22ce21ee5b3a9ded4ac', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', 'Thank you. We''ll finish with John, then.', 'https://record.senedd.wales/Committee/16234', '2026-09-30', 'Vikki Howells', '', '5107', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '3. Ofwat’s role in the Welsh context - scene setting session', '16234', 'http://www.senedd.tv/en/16234?startPos=3330&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-10-01T06:30:22.179336', 'https://record.senedd.wales/XMLExport/Download?meetingID=16234&xmlDownloadType=EnglishTranscript#773284', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f2485d2ee5f5b6dcf0b8', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'I''ll try and be brief. Minister, you''ll be aware that Cardiff Council is delivering one of the UK''s most ambitious and award-winning council house building schemes. A key factor in achieving that was having an LDP in place that enabled the council to secure greater social housing contributions from large-scale developments. Without a plan in place, Cardiff would have lost control of the process and seen piecemeal developments dispersed across the city. Too often, though, engagement on LDPs is dominated by well-organised voices opposed to development. So, Minister, in your rethinking of LDPs, how will you ensure that the voices of those on housing waiting lists, those living in temporary accommodation who desperately need social housing, are also heard, given they are far less likely to participate in these consultations compared with well-resourced, well-organised groups who don''t want to see any houses built?', 'https://record.senedd.wales/Plenary/16314', '2026-10-07', 'Huw Thomas', '', '12156', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16314', 'http://www.senedd.tv/en/16314?startPos=7227&l=en', NULL, 176.0, 'Critical', 'immediate', 'housing_supply; planning_system; homelessness; social_housing', 'Housing system; Planning & place', 'Housing minister', 'Consultation open', 'LDP; LDPs; consultations; house building; housing waiting lists; social housing; temporary accommodation', 0, '2026-10-10T14:39:12.660995', 'https://record.senedd.wales/XMLExport/Download?meetingID=16314&xmlDownloadType=EnglishTranscript#776764', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f27ddbdf086769f4bcf8', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', 'Thank you, Cabinet Minister. From childcare to business rates and support with the cost of living, this Government is already tackling the issues affecting people across Wales. I''m pleased to see us collaborating across different portfolios and reducing the work carried out in Government silos, which is something that has been needed for many years.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f29b133516adee0315fc', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', '[ Inaudible .]—the idea that, from opposition, we were unable to resolve the problems of the M4—. We were in opposition over those years. He was in the Conservative Party, so I get the confusion there about where his politics land. Listen, I understand that there is frustration in wanting a holiday after eight weeks of being the leader of Reform in here. We will be working through the last 43 days of the 100-day plan, every single day of that reporting on it as we promised the people of Wales we would, and then cracking on with phase 2, which is that programme for government to transform the lives of the people of Wales. But today we need to get a supplementary budget through, to get working on the NHS, on childcare, on additional learning needs and all those issues that matter to the people of Wales.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=1176&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government; supplementary budget', 0, '2026-08-04T14:03:08.294052', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767498', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f2f1b14233242a7e1bdd', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I know very, very well the challenges faced by Bangor High Street. It was my high street growing up, and I''m determined that when we look at Bangor, and all the other high streets throughout Wales, we have a clear focus on using all the tools at our disposal to support them. The town centre taskforce, I remind him, is for all high streets. There has been specific assistance, to the tune of over £600,000, announced for Bangor in recent months; I don''t imagine that that is something that the people of Bangor are unhappy about. But it''s always part of a range of measures that we can take as a Government. That announcement today of the 30 per cent cut in business rates is determinedly targeted at helping high streets like Bangor, through supporting those businesses that bring vibrancy, that bring life to those high streets. This is a Government from the get-go that is showing that we are determined to act on the promises that we made, and Bangor, like many other towns the length and breadth of Wales, will benefit from that.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=502&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-16T11:53:07.089442', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768987', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f2fbe4ce9d0122606611', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'I think there is quite an interesting story, and Cai will have heard us mentioning some of this in the public accounts committee. I think that there is a lot more to report than this brief narrative that''s in the budget. A lot of that story is told in the annual report. So, what we''ll do is pull together a package. We have several performance indicators that relate to hitting specific targets on engagement. We''ve had success in increasing how many people we reach on social media and through different channels. Peredur mentioned the important work that''s undertaken by the team that visits schools and welcomes schools here as well, so with younger people. But we drew up an important campaign, in terms of sharing information with the public, before the election this year and in the month that falls in the current financial year that led up to the election in May. That showed that, in working with other partners such as the Electoral Commission, we had managed to increase information, in a completely neutral way, and to encourage people to vote and to explain to them the new system that would come into force for the next election. So, there is a lot to say about this. We visit shows as well from time to time and we engage with people. At the outset of the seventh Senedd, we are speaking to the Commission, and we''d be happy to speak to other groups, about the strategy for the seventh Senedd.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Manon Bonner', '', '', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=1995&l=en', NULL, 86.2, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', '', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.222929', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777405', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f31e75eb739cda2afb08', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'Dirprwy Lywydd, for too long, silo working has stood in the way of progress. This new Government will work across traditional boundaries to address the greatest challenges facing our society. That is why prevention, productivity, the climate and nature emergency and the Welsh Language—Cymraeg—are embedded throughout every aspect of our programme. They are not separate priorities, they underpin every aspect of how we will deliver change and improve outcomes across Wales. They will shape the work of every Minister and every part of Government.', 'https://record.senedd.wales/Plenary/16262', '2026-09-22', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', '16262', 'http://www.senedd.tv/en/16262?startPos=8522&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-26T13:20:19.666330', 'https://record.senedd.wales/XMLExport/Download?meetingID=16262&xmlDownloadType=EnglishTranscript#770968', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f3390d856968a372ac97', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'From the content of the notification letter, in terms of putting that out there as a risk and to flag that it''s an option, I suppose it''s then on people who''ve received the letter to contact the electoral services team with any concerns. And then, yes, I think we''re content that those conversations happened. We gathered information as part of the pilots on the nature of contact, I suppose, from potential electors when they did want to opt out.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f34fcfcf44366b52fe70', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', 'Yes. I''m glad to hear the answer there just now. I was going to ask about the £25,000, and whether you think it''s sufficient now, because it has gone on, but you''ve answered that. Out of the 18 of the 22 authorities that opted into the grant, I wonder whether any of you here on the panel didn’t opt into the empty homes grant. There are four authorities, so are there any of you here that didn’t opt into that grant?', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '3. Follow-up inquiry into Empty Properties: Evidence session 2', '16305', 'http://www.senedd.tv/en/16305?startPos=4977&l=en', NULL, 218.5, 'Critical', 'immediate', 'taxation_of_property; housing_supply; committee_scrutiny', 'Housing system; Planning & place; Tax & finance', 'LGHP Committee members', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty homes; empty homes grant; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:25.469436', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775066', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f359fd76bdee866ecaea', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. And just finally on that from me, I''ve spent a lot of time in my constituency with Vale Domestic Abuse Services, and one thing that comes from them, and people across the sector, is that these are charities that are trapped in funding cycles, and we should not ever be turning any woman away from a service. So, what consideration is being given to the impact of funding cycles and funding cliffs for these essential services?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5511&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.128144', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771245', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f372087c78457e6df5d5', 'plenary_transcript', 'Plenary', '1. Questions to the Trefnydd, Chief Whip and Cabinet Minister for Culture and Sport', 'I don''t know if my officials have had an opportunity to share with the committee yet the range of evidence that I referred to during my question session with the committee. I referred to the IWA report, the Institute of Welsh Affairs, which was independent and was not commissioned by Government. I referred to academic research that was also not commissioned by Government. There is a broad range of evidence out there. The work done in terms of the co-operation agreement emerged from that.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f3a307780b2f86029e34', 'plenary_transcript', 'Plenary', '5. Statement by the Deputy First Minister and Cabinet Minister for Social Justice and Equality: Update on Early Years Childcare and Play', 'Thank you very much, Llywydd. I''m very pleased to provide this update today on the work to develop the initial phasing and costs of the Government''s ambitious commitment to deliver a universal childcare offer.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f3b5bc9c7afdf7b0b259', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Thank you, Chair. You note that the new strategic plan for 2026-29
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f3b9d62a95743f84542a', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', 'Thank you for your answer, Minister. You are responsible for your party''s programme for government, and that programme did take a significant blow last week. Just like the supplementary budget that you are hoping to pass, with votes you don''t have, your minority Government has to follow the first rule of politics, which is learning to count. There''s little doubt that much of Plaid''s manifesto hinged on an optimistic change of the funding model from Westminster. Now that the Senedd has rejected your calls to change the funding model, what changes have you made to your programme for government?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Cai Parry-Jones', '', '12174', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Government Effectiveness and the Constitution', '16085', 'http://www.senedd.tv/en/16085?startPos=4077&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'programme for government; supplementary budget', 0, '2026-08-04T14:03:08.559240', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767605', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f3e1e4086763ed3eb15c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', 'No. So, something that we do at Cwmpas is to try and tell the stories of the community groups that we''re working with. We had our national conference last week, which was a great success and an opportunity to showcase the groups that we''re supporting. But we''ve also pulled together an exhibition of the community groups that we''re supporting, which will be touring across Wales in the coming months. So, keep your eyes peeled for that exhibition to be in a community venue near you soon.', 'https://record.senedd.wales/Committee/16305', '2026-10-01', 'Casey Edwards', '', '', '', '', 'Local Government, Housing and Planning Committee', '5. Follow-up inquiry into Empty Properties: Evidence session 3', '16305', 'http://www.senedd.tv/en/16305?startPos=17554&l=en', NULL, 155.2, 'Critical', 'immediate', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Consultation open; Opportunity to influence', 'Local Government, Housing and Planning Committee; empty properties; evidence session; inquiry', 0, '2026-10-07T06:31:27.069025', 'https://record.senedd.wales/XMLExport/Download?meetingID=16305&xmlDownloadType=EnglishTranscript#775539', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f407f60c013353f6a3a4', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: ''New Ambition for Wales: Programme for Government 2026-2030''', 'First Minister, can I also thank you for your statement today and congratulate you on publishing your programme for government? This, of course, is the first non-Welsh Labour-led programme for government this Senedd has seen, and we aim to respond to it in a dignified manner, putting the people that we serve and represent first, and of course working in common cause where and when we can. I look forward to working constructively on legislation in particular.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f4194525ef0affe219ce', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Good morning, everyone. I''m Richard Irvine, the Chief Veterinary Officer for Wales.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Richard Irvine', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=86&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.282666', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771849', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f426f87a3f9c6129f733', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Thank you. Last week, First Minister, you issued a statement saying that you will convene a resilience summit focusing on wildfires—very much welcomed. Yet, we must be ready for all of the escalating risks of a changing climate. This includes extreme cold, winter flooding and severe storms this coming winter. The Met Office has warned of a heightened risk on the horizon due to an unprecedented El Niño event this year, only highlighted in shocking headlines yesterday, recording the record breaking of 150 years of records. Weaknesses in our infrastructure and our resilience, such as recently witnessed in Gwaelod-y-garth, will only become more apparent in the coming months.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f432dede1ca0721c7b1e', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Indeed.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5131&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.018143', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770529', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f43e0be98599f14cb6a1', 'committee_transcript', 'Petitions Committee', '2. New Petitions', 'Thank you. Noted. All agreed? Okay.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f44abe4de6e6ff94e132', 'committee_transcript', 'Culture, Communications, Cymraeg and Sport Committee', '2. Ministerial scrutiny session: Cabinet Minister for Education and the Welsh Language', 'Thank you very much, and thank you very much also for the opportunity to make a brief opening statement. I''m very pleased to be here with you—the first time for me to appear before this committee, or any committee, indeed, in my new role. I very much hope that this will be the first of many meetings, because I do believe that your work in scrutinising my work and that of this Government as we deliver upon our priorities for the people of Wales is crucially important work. I do look forward, truly, to hearing your views and opinions on the work of the Government, but also to working with you as we ensure that the Welsh language truly does belong to everyone in Wales. That does mean working across the Government, as has been outlined in the evidence paper that has been submitted to you, and as the programme for government that has just been published also makes clear.
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f4d597cf951e71eeaa34', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'And in terms of data sharing, I think there''s been some precedent set for data sharing between the Department for Work and Pensions for other things involving Welsh Government. Has any consideration been given to outside sources of data, especially those that would cover some of the most vulnerable people? So, that''s the first question—whether they''ve been approached on that. Secondly, does having more data available help or hinder the process of the data cleansing?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2499&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.073873', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769892', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f5076dc515904ebbc70c', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Do you want to pick up any points on that, Huw, in particular, before I bring Cai in? Cai.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=2982&l=en', NULL, 97.7, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Opportunity to influence', 'Finance Committee; draft budget; evidence session', 0, '2026-10-09T13:34:37.374792', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777367', NULL, NULL, NULL, NULL);
