INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f63fc3630b6ce14dcb61', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think 28 days allow electors a sufficient period of time in which they can raise concerns. I think the key thing is around the messaging that sits behind it, so the communications campaign around this taking place, the messaging on the outer envelopes that are sent to make people aware what the content is and the need to engage with it, and obviously the communication, then, that''s within that correspondence as well to make people aware, if they are a vulnerable elector and need to pursue anonymous registration, what their options are in terms of that to mitigate some of those risks and concerns. The Welsh Government has recently passed legislation that removes the open register for the local government register, so, again, that takes away some of those risks about where their information would appear as well.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Clare Sim', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=4615&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.291814', 'https: