INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f716c585cb98130020a2', 'committee_transcript', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', 'Okay. And then just perhaps a broader question before I bring other Members in as well—I''m just interested to understand how you''ve engaged with Members on the draft budget before it was laid before the Senedd.', 'https://record.senedd.wales/Committee/16295', '2026-10-08', 'Sam Rowlands', '', '8734', '', '', 'Finance Committee', '3. Scrutiny of the Senedd Commission Draft Budget 2027-28: Evidence Session', '16295', 'http://www.senedd.tv/en/16295?startPos=687&l=en', NULL, 138.0, 'Critical', 'immediate', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', 'Legislative commitment; Opportunity to influence', 'Finance Committee; draft budget; evidence session; laid before the Senedd', 0, '2026-10-09T13:34:37.010457', 'https://record.senedd.wales/XMLExport/Download?meetingID=16295&xmlDownloadType=EnglishTranscript#777400', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('f71febd87ac8a29f2d2e', 'committee_transcript', 'Finance Committee', '6. Public Services Ombudsman for Wales- Annual Report and Accounts 2025-26, and Estimate 2027-28: Evidence session', 'Thank you, Chair. So, responsible use of AI and automation features is one of the pillars in our digital, data and technology strategy. The approach of the organisation so far has been to put the right foundations in place before expanding the use of AI any further. Over the last year, the organisation has developed an AI policy, and that was agreed by unions. It established an AI governance group for strategic oversight and accountability.
