INSERT INTO runs (run_id, started_at, finished_at, collected, stored, errors, sources, sources_failed, sources_substituted) VALUES ('0d3ce3935068', '2026-08-15T08:56:48.774825', '2026-08-15T09:00:54.824409', 197, 55, '["Senedd Record \u2014 transcripts: no meetings found between 2026-07-25 and 2026-08-15. During recess this is correct \u2014 the Senedd rose for summer on 17 July 2026 and returns on 14 September 2026.", "Welsh Government \u2014 RSS: gov.wales RSS unavailable from this host. This is expected on cloud infrastructure: the CloudFront WAF rejects datacentre IPs with HTTP 403. Use the mailbox route (GovWalesMailboxCollector) or run from the NRLA network. Subscription page: https://www.gov.wales/subscribe/announcements"]', '["Senedd committee consultations and inquiries", "Senedd Record \u2014 transcripts", "Senedd Record \u2014 tabled business", "Legislation (Acts and Welsh SIs)", "Senedd Bills and Acts", "Senedd forward look", "Welsh Government \u2014 RSS", "Senedd Research"]', '["Senedd Record \u2014 transcripts"]', '["Welsh Government \u2014 RSS"]');
INSERT INTO runs (run_id, started_at, finished_at, collected, stored, errors, sources, sources_failed, sources_substituted) VALUES ('11a614a1cf26', '2026-09-24T06:30:23.338788', '2026-09-24T06:35:59.227241', 1841, 417, '["Senedd committee consultations and inquiries: no committee register supplied, so committee inquiry pages were not checked. Pass committees={id: title} from GetCommittees \u2014 without this, inquiries with no consultation record (such as the Empty Properties follow-up) are invisible.", "Senedd forward look: GetCommittees returned HTTP 403", "Senedd forward look: GetAllMeetingsByDate returned HTTP 403", "Senedd forward look: no scheduled Senedd business between 2026-09-24 and 2026-11-19. During a long recess this is correct \u2014 the Senedd rose on 17 July 2026 and returned on 14 September 2026. Outside recess, treat this as a failure and check GetAllMeetingsByDate directly.", "Senedd forthcoming business: The Senedd meetings calendar could not be read, so SCHEDULED PLENARY STATEMENTS AND DEBATES are missing \u2014 a statement on non-domestic rates, say, will not be seen until after it is made. Tabled oral questions are unaffected: they come from record.senedd.wales, which is read separately. Either https://business.senedd.wales/mgCalendarMonthView.aspx is unreachable from this host \u2014 business.senedd.wales returned 403 to GitHub Actions on 11 September 2026, the same datacentre-IP block www.gov.wales uses \u2014 or its markup has changed; the parser looks for links to ieListDocuments."]', '["Senedd committee consultations and inquiries", "Senedd Record \u2014 transcripts", "Senedd Record \u2014 tabled business", "Legislation (Acts and Welsh SIs)", "Senedd Bills and Acts", "Senedd diary (senedd.tv)", "Senedd forward look", "Senedd forthcoming business", "Welsh Government \u2014 consultations", "Welsh Government \u2014 newsroom", "Welsh Government \u2014 RSS", "Senedd Research"]', '[]', '[]');
INSERT INTO runs (run_id, started_at, finished_at, collected, stored, errors, sources, sources_failed, sources_substituted) VALUES ('124b1826b28b', '2026-09-22T11:55:02.178803', '2026-09-22T12:00:24.881394', 1673, 398, '["Senedd committee consultations and inquiries: no committee register supplied, so committee inquiry pages were not checked. Pass committees={id: title} from GetCommittees \u2014 without this, inquiries with no consultation record (such as the Empty Properties follow-up) are invisible.", "Senedd forward look: GetCommittees returned HTTP 403", "Senedd forward look: GetAllMeetingsByDate returned HTTP 403", "Senedd forward look: no scheduled Senedd business between 2026-09-22 and 2026-11-17. During a long recess this is correct \u2014 the Senedd rose on 17 July 2026 and returned on 14 September 2026. Outside recess, treat this as a failure and check GetAllMeetingsByDate directly.", "Senedd forthcoming business: The Senedd meetings calendar could not be read, so SCHEDULED PLENARY STATEMENTS AND DEBATES are missing \u2014 a statement on non-domestic rates, say, will not be seen until after it is made. Tabled oral questions are unaffected: they come from record.senedd.wales, which is read separately. Either https://business.senedd.wales/mgCalendarMonthView.aspx is unreachable from this host \u2014 business.senedd.wales returned 403 to GitHub Actions on 11 September 2026, the same datacentre-IP block www.gov.wales uses \u2014 or its markup has changed; the parser looks for links to ieListDocuments."]', '["Senedd committee consultations and inquiries", "Senedd Record \u2014 transcripts", "Senedd Record \u2014 tabled business", "Legislation (Acts and Welsh SIs)", "Senedd Bills and Acts", "Senedd forward look", "Senedd forthcoming business", "Welsh Government \u2014 consultations", "Welsh Government \u2014 newsroom", "Welsh Government \u2014 RSS", "Senedd Research"]', '["Senedd forward look"]', '[]');
